impl TemplateCompoundTagModel {
    pub fn with_string(mut self, key: &'static str, value: &'static str) -> Self {
        self.values
            .insert(key, TemplateNbtValueModel::String(value));
        self
    }

    pub fn with_long(mut self, key: &'static str, value: i64) -> Self {
        self.values.insert(key, TemplateNbtValueModel::Long(value));
        self
    }

    pub fn merge(&mut self, other: &Self) {
        for (key, value) in &other.values {
            self.values.insert(*key, value.clone());
        }
    }
}

impl RuleBlockEntityModifierModel {
    pub fn modifier_type(&self) -> RuleBlockEntityModifierTypeModel {
        match self {
            Self::Clear => RuleBlockEntityModifierTypeModel::Clear,
            Self::Passthrough => RuleBlockEntityModifierTypeModel::Passthrough,
            Self::AppendStatic { .. } => RuleBlockEntityModifierTypeModel::AppendStatic,
            Self::AppendLoot { .. } => RuleBlockEntityModifierTypeModel::AppendLoot,
        }
    }

    pub fn codec_id(&self) -> &'static str {
        self.modifier_type().id()
    }

    pub fn apply(
        &self,
        random: &mut RandomSourceKind,
        existing_tag: Option<TemplateCompoundTagModel>,
    ) -> Option<TemplateCompoundTagModel> {
        match self {
            Self::Clear => Some(TemplateCompoundTagModel::default()),
            Self::Passthrough => existing_tag,
            Self::AppendStatic { data } => {
                let mut result = existing_tag.unwrap_or_default();
                result.merge(data);
                Some(result)
            }
            Self::AppendLoot { loot_table } => {
                let mut result = existing_tag.unwrap_or_default();
                result
                    .values
                    .insert("LootTable", TemplateNbtValueModel::String(loot_table));
                result.values.insert(
                    "LootTableSeed",
                    TemplateNbtValueModel::Long(random_next_i64(random)),
                );
                Some(result)
            }
        }
    }
}

impl TemplatePathFactoryModel {
    pub fn new(source_dir: impl Into<String>) -> Self {
        Self {
            source_dir: source_dir.into(),
        }
    }

    pub fn for_pack_type(source_dir: &str, pack_type_dir: &str) -> Self {
        Self::new(format!(
            "{}/{}",
            source_dir.trim_end_matches('/'),
            pack_type_dir.trim_matches('/')
        ))
    }

    pub fn create_and_validate_path_to_structure(
        &self,
        id: &Identifier,
        kind: StructureTemplateFileKind,
    ) -> Result<String, String> {
        let relative_path = match kind {
            StructureTemplateFileKind::Nbt => format!("structure/{}.nbt", id.path()),
            StructureTemplateFileKind::Snbt => format!("structure/{}.snbt", id.path()),
        };
        let file_id = Identifier::new(id.namespace(), &relative_path)?;
        self.create_and_validate_path_to_resource(&file_id)
    }

    pub fn create_and_validate_path_to_resource(
        &self,
        resource_location: &Identifier,
    ) -> Result<String, String> {
        let mut parts = Vec::new();
        for part in resource_location.path().split('/') {
            if part.is_empty() || part == "." || part == ".." {
                return Err(format!(
                    "Invalid file path '{}': invalid path segment '{}'",
                    resource_location, part
                ));
            }
            if !is_template_path_part_portable(part) {
                return Err(format!(
                    "Resource path '{}' is not portable",
                    resource_location
                ));
            }
            parts.push(part);
        }

        Ok(format!(
            "{}/{}/{}",
            self.source_dir.trim_end_matches('/'),
            resource_location.namespace(),
            parts.join("/")
        ))
    }
}

impl StructureTemplateManagerModel {
    pub const STRUCTURE_DIRECTORY_NAME: &'static str = "structure";
    pub const STRUCTURE_FILE_EXTENSION: &'static str = ".nbt";
    pub const STRUCTURE_TEXT_FILE_EXTENSION: &'static str = ".snbt";

    pub fn get_or_create(&mut self, id: Identifier) -> &'static str {
        self.cache.entry(id).or_insert(Some("runtime_template"));
        "runtime_template"
    }

    pub fn get_or_try_load(
        &mut self,
        id: Identifier,
        loader: impl FnOnce(&Identifier) -> Option<&'static str>,
    ) -> Option<&'static str> {
        if let Some(cached) = self.cache.get(&id) {
            return *cached;
        }
        let loaded = loader(&id);
        self.cache.insert(id, loaded);
        loaded
    }

    pub fn remove(&mut self, id: &Identifier) {
        self.cache.remove(id);
    }

    pub fn on_resource_manager_reload(&mut self) {
        self.cache.clear();
    }

    pub fn save_kind(debug_save_as_snbt: bool) -> StructureTemplateFileKind {
        if debug_save_as_snbt {
            StructureTemplateFileKind::Snbt
        } else {
            StructureTemplateFileKind::Nbt
        }
    }

    pub fn try_load_from_sources(
        &mut self,
        id: Identifier,
        sources: &[TemplateSourceModel],
    ) -> (Option<&'static str>, Vec<TemplateLoadAttemptModel>) {
        if let Some(cached) = self.cache.get(&id) {
            return (*cached, Vec::new());
        }

        let mut attempts = Vec::new();
        for source in sources {
            let (loaded, result) = source.load(&id);
            attempts.push(TemplateLoadAttemptModel {
                source_kind: source.kind,
                id: id.clone(),
                result,
            });
            if loaded.is_some() {
                self.cache.insert(id, loaded);
                return (loaded, attempts);
            }
        }

        self.cache.insert(id, None);
        (None, attempts)
    }

    pub fn list_templates_from_sources(sources: &[TemplateSourceModel]) -> Vec<Identifier> {
        let mut listed = Vec::new();
        for source in sources {
            for id in source.list() {
                if !listed.contains(&id) {
                    listed.push(id);
                }
            }
        }
        listed
    }
}

fn is_template_path_part_portable(part: &str) -> bool {
    !part.is_empty()
        && part.chars().all(|ch| {
            ch.is_ascii_lowercase() || ch.is_ascii_digit() || matches!(ch, '_' | '-' | '.')
        })
}

impl TemplateSourceModel {
    pub fn directory(
        source_dir: Option<&'static str>,
        load_as_text: bool,
        available: &[(&str, &'static str)],
        fail_on_load: &[&str],
    ) -> Self {
        Self::new(
            TemplateSourceKindModel::Directory,
            source_dir,
            load_as_text,
            available,
            fail_on_load,
        )
    }

    pub fn resource_manager(available: &[(&str, &'static str)], fail_on_load: &[&str]) -> Self {
        Self::new(
            TemplateSourceKindModel::ResourceManager,
            None,
            false,
            available,
            fail_on_load,
        )
    }

    fn new(
        kind: TemplateSourceKindModel,
        source_dir: Option<&'static str>,
        load_as_text: bool,
        available: &[(&str, &'static str)],
        fail_on_load: &[&str],
    ) -> Self {
        Self {
            kind,
            source_dir,
            load_as_text,
            available: available
                .iter()
                .map(|(id, template)| {
                    (
                        Identifier::parse(id).expect("valid template id fixture"),
                        *template,
                    )
                })
                .collect(),
            fail_on_load: fail_on_load
                .iter()
                .map(|id| Identifier::parse(id).expect("valid template id fixture"))
                .collect(),
        }
    }

    pub fn load(&self, id: &Identifier) -> (Option<&'static str>, TemplateLoadAttemptResultModel) {
        if self.kind == TemplateSourceKindModel::Directory && self.source_dir.is_none() {
            return (None, TemplateLoadAttemptResultModel::SourceUnavailable);
        }
        if self.fail_on_load.contains(id) {
            return (None, TemplateLoadAttemptResultModel::ErrorSuppressed);
        }
        match self.available.get(id).copied() {
            Some(template) => (Some(template), TemplateLoadAttemptResultModel::Loaded),
            None => (None, TemplateLoadAttemptResultModel::Missing),
        }
    }

    pub fn list(&self) -> Vec<Identifier> {
        if self.kind == TemplateSourceKindModel::Directory && self.source_dir.is_none() {
            return Vec::new();
        }
        self.available.keys().cloned().collect()
    }
}

pub fn structure_random_rule_test_matches(
    block_matches: bool,
    probability: f32,
    random_next_float: f32,
) -> bool {
    block_matches && random_next_float < probability
}

pub fn structure_linear_pos_chance(
    dist: i32,
    min_dist: i32,
    max_dist: i32,
    min_chance: f32,
    max_chance: f32,
) -> Result<f32, String> {
    if min_dist >= max_dist {
        return Err(format!("Invalid range: [{min_dist},{max_dist}]"));
    }
    let t = ((dist - min_dist) as f32 / (max_dist - min_dist) as f32).clamp(0.0, 1.0);
    Ok(min_chance + (max_chance - min_chance) * t)
}

pub fn structure_axis_aligned_distance(
    world_pos: (i32, i32, i32),
    reference: (i32, i32, i32),
    axis: char,
) -> i32 {
    match axis {
        'x' | 'X' => (world_pos.0 - reference.0).abs(),
        'y' | 'Y' => (world_pos.1 - reference.1).abs(),
        'z' | 'Z' => (world_pos.2 - reference.2).abs(),
        _ => 0,
    }
}

impl TerrainAdjustmentModel {
    pub fn id(self) -> &'static str {
        match self {
            TerrainAdjustmentModel::None => "none",
            TerrainAdjustmentModel::Bury => "bury",
            TerrainAdjustmentModel::BeardThin => "beard_thin",
            TerrainAdjustmentModel::BeardBox => "beard_box",
            TerrainAdjustmentModel::Encapsulate => "encapsulate",
        }
    }

    pub fn from_id(id: &str) -> Option<Self> {
        match id {
            "none" => Some(TerrainAdjustmentModel::None),
            "bury" => Some(TerrainAdjustmentModel::Bury),
            "beard_thin" => Some(TerrainAdjustmentModel::BeardThin),
            "beard_box" => Some(TerrainAdjustmentModel::BeardBox),
            "encapsulate" => Some(TerrainAdjustmentModel::Encapsulate),
            _ => None,
        }
    }

    pub fn jigsaw_edge_needed(self) -> i32 {
        match self {
            TerrainAdjustmentModel::None => 0,
            TerrainAdjustmentModel::Bury
            | TerrainAdjustmentModel::BeardThin
            | TerrainAdjustmentModel::BeardBox
            | TerrainAdjustmentModel::Encapsulate => 12,
        }
    }
}

pub fn structure_adjust_bounding_box(
    terrain_adjustment: TerrainAdjustmentModel,
    bounding_box: StructureBoundingBoxModel,
) -> StructureBoundingBoxModel {
    if terrain_adjustment == TerrainAdjustmentModel::None {
        bounding_box
    } else {
        bounding_box.inflated_by(12)
    }
}

pub fn jigsaw_max_distance_with_terrain_is_valid(
    horizontal_max_distance_from_center: i32,
    terrain_adjustment: TerrainAdjustmentModel,
) -> bool {
    horizontal_max_distance_from_center + terrain_adjustment.jigsaw_edge_needed() <= 128
}

impl StructureStartModel {
    pub fn invalid() -> Self {
        Self {
            structure: None,
            chunk_pos: ChunkPos { x: 0, z: 0 },
            references: 0,
            pieces: Vec::new(),
        }
    }

    pub fn is_valid(&self) -> bool {
        !self.pieces.is_empty()
    }

    pub fn max_references(&self) -> i32 {
        1
    }

    pub fn can_be_referenced(&self) -> bool {
        self.references < self.max_references()
    }

    pub fn add_reference(&mut self) {
        self.references += 1;
    }

    pub fn bounding_box(&self) -> Option<StructureBoundingBoxModel> {
        self.pieces
            .iter()
            .map(|piece| piece.bounding_box)
            .reduce(StructureBoundingBoxModel::union)
    }

    pub fn create_tag(&self, chunk_pos: ChunkPos) -> StructureStartTagModel {
        if self.is_valid() {
            StructureStartTagModel {
                id: self.structure.unwrap_or("minecraft:unknown"),
                chunk_x: Some(chunk_pos.x),
                chunk_z: Some(chunk_pos.z),
                references: Some(self.references),
                children: self.pieces.len(),
            }
        } else {
            StructureStartTagModel {
                id: "INVALID",
                chunk_x: None,
                chunk_z: None,
                references: None,
                children: 0,
            }
        }
    }
}

impl StructureAccessModel {
    pub fn get_start_for_structure(&self, structure: &'static str) -> Option<&StructureStartModel> {
        self.starts.get(structure)
    }

    pub fn set_start_for_structure(&mut self, structure: &'static str, start: StructureStartModel) {
        self.starts.insert(structure, start);
        self.unsaved = true;
    }

    pub fn set_all_starts(&mut self, starts: BTreeMap<&'static str, StructureStartModel>) {
        self.starts = starts;
        self.unsaved = true;
    }

    pub fn get_references_for_structure(&self, structure: &'static str) -> &[i64] {
        self.references
            .get(structure)
            .map(Vec::as_slice)
            .unwrap_or(&[])
    }

    pub fn add_reference_for_structure(&mut self, structure: &'static str, reference: i64) {
        let references = self.references.entry(structure).or_default();
        if !references.contains(&reference) {
            references.push(reference);
        }
        self.unsaved = true;
    }

    pub fn set_all_references(&mut self, references: BTreeMap<&'static str, Vec<i64>>) {
        self.references = references;
        self.unsaved = true;
    }

    pub fn has_any_structure_references(&self) -> bool {
        self.references
            .values()
            .any(|references| !references.is_empty())
    }
}

pub fn structure_access_to_chunk_structures_tag(
    access: &StructureAccessModel,
    chunk_pos: ChunkPos,
) -> Tag {
    let starts = access
        .starts
        .iter()
        .map(|(structure, start)| {
            (
                (*structure).to_string(),
                structure_start_to_chunk_tag(start, chunk_pos),
            )
        })
        .collect();
    let references = access
        .references
        .iter()
        .map(|(structure, reference_chunks)| {
            (
                (*structure).to_string(),
                Tag::LongArray(reference_chunks.clone()),
            )
        })
        .collect();
    Tag::Compound(vec![
        ("starts".to_string(), Tag::Compound(starts)),
        ("References".to_string(), Tag::Compound(references)),
    ])
}

fn structure_start_to_chunk_tag(start: &StructureStartModel, chunk_pos: ChunkPos) -> Tag {
    let tag = start.create_tag(chunk_pos);
    let mut fields = vec![("id".to_string(), Tag::String(tag.id.to_string()))];
    if let Some(chunk_x) = tag.chunk_x {
        fields.push(("ChunkX".to_string(), Tag::Int(chunk_x)));
    }
    if let Some(chunk_z) = tag.chunk_z {
        fields.push(("ChunkZ".to_string(), Tag::Int(chunk_z)));
    }
    if let Some(references) = tag.references {
        fields.push(("references".to_string(), Tag::Int(references)));
    }
    fields.push((
        "Children".to_string(),
        Tag::List(
            start
                .pieces
                .iter()
                .map(|piece| {
                    Tag::Compound(vec![(
                        "BB".to_string(),
                        Tag::IntArray(vec![
                            piece.bounding_box.min_x,
                            piece.bounding_box.min_y,
                            piece.bounding_box.min_z,
                            piece.bounding_box.max_x,
                            piece.bounding_box.max_y,
                            piece.bounding_box.max_z,
                        ]),
                    )])
                })
                .collect(),
        ),
    ));
    Tag::Compound(fields)
}

pub fn structure_start_reference_pos(first_piece: StructurePieceModel) -> BlockPos {
    let center = first_piece.bounding_box.center();
    BlockPos {
        x: center.x,
        y: first_piece.bounding_box.min_y,
        z: center.z,
    }
}

pub fn structure_pieces_intersecting_chunk(
    start: &StructureStartModel,
    chunk_bb: StructureBoundingBoxModel,
) -> Vec<StructurePieceModel> {
    start
        .pieces
        .iter()
        .copied()
        .filter(|piece| piece.bounding_box.intersects(chunk_bb))
        .collect()
}

pub fn structure_has_piece_at(pos: BlockPos, start: &StructureStartModel) -> bool {
    start
        .pieces
        .iter()
        .any(|piece| piece.bounding_box.is_inside(pos))
}

pub fn structure_start_contains_pos(pos: BlockPos, start: &StructureStartModel) -> bool {
    start
        .bounding_box()
        .is_some_and(|bounding_box| bounding_box.is_inside(pos))
}

pub fn structure_spawn_override_applies(
    pos: BlockPos,
    start: &StructureStartModel,
    override_model: StructureSpawnOverrideModel,
) -> bool {
    match override_model.bounding_box {
        StructureSpawnBoundingBoxTypeModel::Piece => structure_has_piece_at(pos, start),
        StructureSpawnBoundingBoxTypeModel::Full => structure_start_contains_pos(pos, start),
    }
}

pub fn chunk_generator_mobs_at<'a>(
    biome_spawns: &'a [&'a str],
    mob_category: &str,
    pos: BlockPos,
    structures_at_pos: &[StructureSpawnCandidateModel<'_>],
) -> Vec<&'a str> {
    for candidate in structures_at_pos {
        let Some(override_model) = candidate.override_model else {
            continue;
        };
        if override_model.category == mob_category
            && structure_spawn_override_applies(pos, candidate.start, override_model)
        {
            return override_model.spawns.to_vec();
        }
    }
    biome_spawns.to_vec()
}

pub fn first_structure_start_containing_pos(
    pos: BlockPos,
    starts: &[StructureStartModel],
) -> Option<StructureStartModel> {
    starts
        .iter()
        .find(|start| structure_start_contains_pos(pos, start))
        .cloned()
}

pub fn first_structure_start_with_piece_at(
    pos: BlockPos,
    starts: &[StructureStartModel],
) -> Option<StructureStartModel> {
    starts
        .iter()
        .find(|start| structure_has_piece_at(pos, start))
        .cloned()
}

pub fn structure_check_result_from_cached_references(
    references: Option<i32>,
    require_unreferenced: bool,
) -> StructureCheckResultModel {
    match references {
        None => StructureCheckResultModel::StartNotPresent,
        Some(reference_count) if require_unreferenced && reference_count != 0 => {
            StructureCheckResultModel::StartNotPresent
        }
        Some(_) => StructureCheckResultModel::StartPresent,
    }
}

pub fn structure_fast_check_allows_lookup(result: StructureCheckResultModel) -> bool {
    result != StructureCheckResultModel::StartNotPresent
}

pub fn structure_locate_can_return_fast(
    result: StructureCheckResultModel,
    create_reference: bool,
) -> bool {
    !create_reference && result == StructureCheckResultModel::StartPresent
}

pub fn structure_start_can_satisfy_lookup(
    start: &StructureStartModel,
    create_reference: bool,
) -> bool {
    start.is_valid() && (!create_reference || start.can_be_referenced())
}

pub fn structure_try_add_reference(start: &mut StructureStartModel) -> bool {
    if start.can_be_referenced() {
        start.add_reference();
        true
    } else {
        false
    }
}

pub fn structure_access_valid_starts_for_references(
    access_by_chunk: &BTreeMap<i64, StructureAccessModel>,
    structure: &'static str,
    references: &[i64],
) -> Vec<StructureStartModel> {
    references
        .iter()
        .filter_map(|reference| access_by_chunk.get(reference))
        .filter_map(|access| access.get_start_for_structure(structure))
        .filter(|start| start.is_valid())
        .cloned()
        .collect()
}

pub fn chunk_pos_key(chunk_pos: ChunkPos) -> i64 {
    (chunk_pos.x as u32 as i64) | ((chunk_pos.z as u32 as i64) << 32)
}

pub fn structure_reference_writable_area(chunk_pos: ChunkPos) -> StructureBoundingBoxModel {
    StructureBoundingBoxModel {
        min_x: chunk_pos.x * 16,
        min_y: i32::MIN,
        min_z: chunk_pos.z * 16,
        max_x: chunk_pos.x * 16 + 15,
        max_y: i32::MAX,
        max_z: chunk_pos.z * 16 + 15,
    }
}

pub fn structure_references_for_chunk(
    access_by_chunk: &BTreeMap<i64, StructureAccessModel>,
    target_chunk: ChunkPos,
) -> Vec<StructureReferenceModel> {
    let target_area = structure_reference_writable_area(target_chunk);
    let mut references = Vec::new();
    for source_x in target_chunk.x - 8..=target_chunk.x + 8 {
        for source_z in target_chunk.z - 8..=target_chunk.z + 8 {
            let source_chunk = ChunkPos {
                x: source_x,
                z: source_z,
            };
            let source_key = chunk_pos_key(source_chunk);
            let Some(access) = access_by_chunk.get(&source_key) else {
                continue;
            };
            for start in access.starts.values() {
                if start.is_valid()
                    && start
                        .bounding_box()
                        .is_some_and(|bbox| bbox.intersects(target_area))
                {
                    references.push(StructureReferenceModel {
                        structure: start.structure.unwrap_or("minecraft:unknown"),
                        source_chunk_key: source_key,
                    });
                }
            }
        }
    }
    references
}

pub fn create_structure_references_for_chunk(
    access_by_chunk: &BTreeMap<i64, StructureAccessModel>,
    target_chunk: ChunkPos,
    target_access: &mut StructureAccessModel,
) -> Vec<StructureReferenceModel> {
    let references = structure_references_for_chunk(access_by_chunk, target_chunk);
    for reference in &references {
        target_access.add_reference_for_structure(reference.structure, reference.source_chunk_key);
    }
    references
}

pub fn buried_treasure_generation_piece(chunk_pos: ChunkPos) -> BuriedTreasurePieceModel {
    let pos = BlockPos {
        x: chunk_pos.x * 16 + 9,
        y: 90,
        z: chunk_pos.z * 16 + 9,
    };
    BuriedTreasurePieceModel {
        bounding_box: StructureBoundingBoxModel {
            min_x: pos.x,
            min_y: pos.y,
            min_z: pos.z,
            max_x: pos.x,
            max_y: pos.y,
            max_z: pos.z,
        },
    }
}

pub fn buried_treasure_is_liquid(state: &'static str) -> bool {
    matches!(state, "minecraft:water" | "minecraft:lava")
}

pub fn buried_treasure_is_support(state: &'static str) -> bool {
    matches!(
        state,
        "minecraft:sandstone"
            | "minecraft:stone"
            | "minecraft:andesite"
            | "minecraft:granite"
            | "minecraft:diorite"
    )
}

pub fn buried_treasure_soft_state(current_state: &'static str) -> &'static str {
    if current_state == "minecraft:air" || buried_treasure_is_liquid(current_state) {
        "minecraft:sand"
    } else {
        current_state
    }
}

pub fn buried_treasure_place(
    piece: BuriedTreasurePieceModel,
    ocean_floor_y: i32,
    min_y: i32,
    mut block_state_at: impl FnMut(BlockPos) -> &'static str,
) -> Option<BuriedTreasurePlacementModel> {
    let x = piece.bounding_box.min_x;
    let z = piece.bounding_box.min_z;
    for y in (min_y + 1..=ocean_floor_y).rev() {
        let pos = BlockPos { x, y, z };
        let below_pos = BlockPos { x, y: y - 1, z };
        let below_state = block_state_at(below_pos);
        if !buried_treasure_is_support(below_state) {
            continue;
        }

        let soft_state = buried_treasure_soft_state(block_state_at(pos));
        let directions = [
            BlockPos { x: 0, y: -1, z: 0 },
            BlockPos { x: 0, y: 1, z: 0 },
            BlockPos { x: 0, y: 0, z: -1 },
            BlockPos { x: 0, y: 0, z: 1 },
            BlockPos { x: -1, y: 0, z: 0 },
            BlockPos { x: 1, y: 0, z: 0 },
        ];
        let side_fill = directions.map(|delta| {
            let relative_pos = BlockPos {
                x: pos.x + delta.x,
                y: pos.y + delta.y,
                z: pos.z + delta.z,
            };
            let relative_state = block_state_at(relative_pos);
            let fill_state =
                if relative_state == "minecraft:air" || buried_treasure_is_liquid(relative_state) {
                    let below_relative_pos = BlockPos {
                        x: relative_pos.x,
                        y: relative_pos.y - 1,
                        z: relative_pos.z,
                    };
                    let below_relative_state = block_state_at(below_relative_pos);
                    if delta.y != 1
                        && (below_relative_state == "minecraft:air"
                            || buried_treasure_is_liquid(below_relative_state))
                    {
                        below_state
                    } else {
                        soft_state
                    }
                } else {
                    relative_state
                };
            (fill_state, relative_pos)
        });

        return Some(BuriedTreasurePlacementModel {
            chest_pos: pos,
            bounding_box: StructureBoundingBoxModel {
                min_x: pos.x,
                min_y: pos.y,
                min_z: pos.z,
                max_x: pos.x,
                max_y: pos.y,
                max_z: pos.z,
            },
            side_fill,
        });
    }
    None
}

pub fn scattered_feature_piece(
    west: i32,
    floor: i32,
    north: i32,
    width: i32,
    height: i32,
    depth: i32,
    orientation: HorizontalDirection,
) -> ScatteredFeaturePieceModel {
    ScatteredFeaturePieceModel {
        bounding_box: structure_make_bounding_box(
            west,
            floor,
            north,
            orientation,
            width,
            height,
            depth,
        ),
        orientation,
        width,
        height,
        depth,
        height_position: -1,
    }
}

pub fn scattered_feature_update_average_ground_height(
    piece: &mut ScatteredFeaturePieceModel,
    chunk_bb: StructureBoundingBoxModel,
    offset: i32,
    mut height_at: impl FnMut(i32, i32) -> i32,
) -> bool {
    if piece.height_position >= 0 {
        return true;
    }
    let mut total = 0;
    let mut count = 0;
    for z in piece.bounding_box.min_z..=piece.bounding_box.max_z {
        for x in piece.bounding_box.min_x..=piece.bounding_box.max_x {
            if chunk_bb.is_inside(BlockPos { x, y: 64, z }) {
                total += height_at(x, z);
                count += 1;
            }
        }
    }
    if count == 0 {
        return false;
    }
    piece.height_position = total / count;
    let dy = piece.height_position - piece.bounding_box.min_y + offset;
    piece.bounding_box = piece.bounding_box.moved(0, dy, 0);
    true
}

