impl NoiseSettings {
    pub const fn new(min_y: i32, height: i32, size_horizontal: i32, size_vertical: i32) -> Self {
        Self {
            min_y,
            height,
            size_horizontal,
            size_vertical,
        }
    }

    pub fn validate(self) -> Result<(), String> {
        if self.min_y + self.height > 2032 {
            return Err("min_y + height cannot be higher than: 2032".to_string());
        }
        if self.height % 16 != 0 {
            return Err("height has to be a multiple of 16".to_string());
        }
        if self.min_y % 16 != 0 {
            return Err("min_y has to be a multiple of 16".to_string());
        }
        if !(1..=4).contains(&self.size_horizontal) {
            return Err("size_horizontal must be in 1..=4".to_string());
        }
        if !(1..=4).contains(&self.size_vertical) {
            return Err("size_vertical must be in 1..=4".to_string());
        }
        Ok(())
    }

    pub fn cell_height(self) -> i32 {
        self.size_vertical * 4
    }

    pub fn cell_width(self) -> i32 {
        self.size_horizontal * 4
    }

    pub fn clamp_to_height(self, min_y: i32, max_y: i32) -> Self {
        let new_min_y = self.min_y.max(min_y);
        let new_height = (self.min_y + self.height).min(max_y + 1) - new_min_y;
        Self::new(
            new_min_y,
            new_height,
            self.size_horizontal,
            self.size_vertical,
        )
    }
}

impl VerticalAnchor {
    pub fn resolve_y(self, context: WorldGenerationHeightContext) -> i32 {
        match self {
            VerticalAnchor::Absolute(y) => y,
            VerticalAnchor::AboveBottom(offset) => context.min_y + offset,
            VerticalAnchor::BelowTop(offset) => context.min_y + context.height - 1 - offset,
        }
    }
}

pub fn height_provider_type(id: &str) -> Option<&'static HeightProviderType> {
    let name = id.strip_prefix("minecraft:").unwrap_or(id);
    HEIGHT_PROVIDER_TYPES.iter().find(|provider_type| {
        provider_type
            .id
            .strip_prefix("minecraft:")
            .unwrap_or(provider_type.id)
            == name
    })
}

pub fn height_provider_sample_bounds(
    provider: HeightProvider,
    context: WorldGenerationHeightContext,
) -> (i32, i32) {
    match provider {
        HeightProvider::Constant { value } => {
            let y = value.resolve_y(context);
            (y, y)
        }
        HeightProvider::Uniform {
            min_inclusive,
            max_inclusive,
        }
        | HeightProvider::Trapezoid {
            min_inclusive,
            max_inclusive,
            ..
        } => {
            let min = min_inclusive.resolve_y(context);
            let max = max_inclusive.resolve_y(context);
            if min > max {
                (min, min)
            } else {
                (min, max)
            }
        }
        HeightProvider::BiasedToBottom {
            min_inclusive,
            max_inclusive,
            inner,
        }
        | HeightProvider::VeryBiasedToBottom {
            min_inclusive,
            max_inclusive,
            inner,
        } => {
            let min = min_inclusive.resolve_y(context);
            let max = max_inclusive.resolve_y(context);
            if max - min - inner + 1 <= 0 {
                (min, min)
            } else {
                (min, max - 1)
            }
        }
        HeightProvider::WeightedList { distribution } => distribution
            .iter()
            .map(|entry| height_provider_sample_bounds(entry.provider, context))
            .reduce(|(min_a, max_a), (min_b, max_b)| (min_a.min(min_b), max_a.max(max_b)))
            .unwrap_or((context.min_y, context.min_y)),
    }
}

pub fn height_provider_sample_with_rolls(
    provider: HeightProvider,
    context: WorldGenerationHeightContext,
    first_roll: i32,
    second_roll: i32,
    third_roll: i32,
) -> i32 {
    match provider {
        HeightProvider::Constant { value } => value.resolve_y(context),
        HeightProvider::Uniform {
            min_inclusive,
            max_inclusive,
        } => {
            let min = min_inclusive.resolve_y(context);
            let max = max_inclusive.resolve_y(context);
            if min > max {
                min
            } else {
                min + first_roll.rem_euclid(max - min + 1)
            }
        }
        HeightProvider::BiasedToBottom {
            min_inclusive,
            max_inclusive,
            inner,
        } => {
            let min = min_inclusive.resolve_y(context);
            let max = max_inclusive.resolve_y(context);
            let outer_bound = max - min - inner + 1;
            if outer_bound <= 0 {
                min
            } else {
                let limit = first_roll.rem_euclid(outer_bound);
                min + second_roll.rem_euclid(limit + inner)
            }
        }
        HeightProvider::VeryBiasedToBottom {
            min_inclusive,
            max_inclusive,
            inner,
        } => {
            let min = min_inclusive.resolve_y(context);
            let max = max_inclusive.resolve_y(context);
            if max - min - inner + 1 <= 0 {
                min
            } else {
                let upper = min + inner + first_roll.rem_euclid(max - (min + inner) + 1);
                let biased_upper = min + second_roll.rem_euclid(upper - min);
                min + third_roll.rem_euclid(biased_upper - min + inner)
            }
        }
        HeightProvider::Trapezoid {
            min_inclusive,
            max_inclusive,
            plateau,
        } => {
            let min = min_inclusive.resolve_y(context);
            let max = max_inclusive.resolve_y(context);
            if min > max {
                return min;
            }

            let range = max - min;
            if plateau >= range {
                return min + first_roll.rem_euclid(range + 1);
            }

            let plateau_start = (range - plateau) / 2;
            let plateau_end = range - plateau_start;
            min + first_roll.rem_euclid(plateau_end + 1) + second_roll.rem_euclid(plateau_start + 1)
        }
        HeightProvider::WeightedList { distribution } => {
            let positive_weight_total = distribution
                .iter()
                .map(|entry| entry.weight.max(0))
                .sum::<i32>();
            if positive_weight_total <= 0 {
                return context.min_y;
            }

            let mut choice = first_roll.rem_euclid(positive_weight_total);
            let selected = distribution
                .iter()
                .find(|entry| {
                    let weight = entry.weight.max(0);
                    if choice < weight {
                        true
                    } else {
                        choice -= weight;
                        false
                    }
                })
                .expect("positive total weight must select a provider");
            height_provider_sample_with_rolls(
                selected.provider,
                context,
                second_roll,
                third_roll,
                0,
            )
        }
    }
}

pub fn block_predicate_type(id: &str) -> Option<&'static BlockPredicateType> {
    let name = id.strip_prefix("minecraft:").unwrap_or(id);
    BLOCK_PREDICATE_TYPES.iter().find(|predicate_type| {
        predicate_type
            .id
            .strip_prefix("minecraft:")
            .unwrap_or(predicate_type.id)
            == name
    })
}

pub fn block_predicate_test(
    predicate: BlockPredicate,
    context: BlockPredicateContext,
    origin_y: i32,
) -> bool {
    block_predicate_test_with_vertical_context(predicate, context, context, origin_y)
}

pub fn block_predicate_test_with_vertical_context(
    predicate: BlockPredicate,
    origin_context: BlockPredicateContext,
    offset_context: BlockPredicateContext,
    origin_y: i32,
) -> bool {
    match predicate {
        BlockPredicate::MatchingBlocks { blocks } => blocks.contains(&origin_context.block),
        BlockPredicate::MatchingBlocksAt { offset_y, blocks } => {
            block_predicate_offset_context(offset_context, origin_y, offset_y)
                .is_some_and(|offset_context| blocks.contains(&offset_context.block))
        }
        BlockPredicate::MatchingBlockTag { tag } => block_matches_tag(origin_context.block, tag),
        BlockPredicate::MatchingFluids { fluids } => fluids.contains(&origin_context.fluid),
        BlockPredicate::MatchingFluidsAt { offset_y, fluids } => {
            block_predicate_offset_context(offset_context, origin_y, offset_y)
                .is_some_and(|offset_context| fluids.contains(&offset_context.fluid))
        }
        BlockPredicate::Solid => origin_context.solid,
        BlockPredicate::SolidAt { offset_y } => {
            block_predicate_offset_context(offset_context, origin_y, offset_y)
                .is_some_and(|offset_context| offset_context.solid)
        }
        BlockPredicate::Replaceable => origin_context.replaceable,
        BlockPredicate::ReplaceableAt { offset_y } => {
            block_predicate_offset_context(offset_context, origin_y, offset_y)
                .is_some_and(|offset_context| offset_context.replaceable)
        }
        BlockPredicate::WouldSurvive {
            offset_y,
            state: _,
            survives,
        } => block_predicate_offset_context(offset_context, origin_y, offset_y)
            .is_some_and(|_| survives),
        BlockPredicate::HasSturdyFace {
            offset_y,
            direction: _,
            sturdy,
        } => block_predicate_offset_context(offset_context, origin_y, offset_y)
            .is_some_and(|_| sturdy),
        BlockPredicate::InsideWorldBounds { offset_y } => {
            let y = origin_y + offset_y;
            y >= origin_context.min_y && y < origin_context.min_y + origin_context.height
        }
        BlockPredicate::AnyOf { predicates } => predicates.iter().any(|predicate| {
            block_predicate_test_with_vertical_context(
                *predicate,
                origin_context,
                offset_context,
                origin_y,
            )
        }),
        BlockPredicate::AllOf { predicates } => predicates.iter().all(|predicate| {
            block_predicate_test_with_vertical_context(
                *predicate,
                origin_context,
                offset_context,
                origin_y,
            )
        }),
        BlockPredicate::Not { predicate } => !block_predicate_test_with_vertical_context(
            *predicate,
            origin_context,
            offset_context,
            origin_y,
        ),
        BlockPredicate::True => true,
        BlockPredicate::Unobstructed => origin_context.unobstructed,
    }
}

fn block_predicate_offset_context(
    context: BlockPredicateContext,
    origin_y: i32,
    offset_y: i32,
) -> Option<BlockPredicateContext> {
    let y = origin_y + offset_y;
    (y >= context.min_y && y < context.min_y + context.height).then_some(context)
}

fn block_matches_tag(block: &str, tag: &str) -> bool {
    let tag = tag.strip_prefix("minecraft:").unwrap_or(tag);
    match tag {
        "air" => {
            block == "minecraft:air"
                || block == "minecraft:cave_air"
                || block == "minecraft:void_air"
        }
        "stone_ore_replaceables" => matches!(
            block,
            "minecraft:stone" | "minecraft:granite" | "minecraft:diorite" | "minecraft:andesite"
        ),
        "deepslate_ore_replaceables" => {
            matches!(block, "minecraft:deepslate" | "minecraft:tuff")
        }
        "base_stone_overworld" => {
            block_matches_tag(block, "minecraft:stone_ore_replaceables")
                || block_matches_tag(block, "minecraft:deepslate_ore_replaceables")
        }
        "base_stone_nether" => {
            matches!(
                block,
                "minecraft:netherrack" | "minecraft:basalt" | "minecraft:blackstone"
            )
        }
        "logs" => matches!(
            block,
            "minecraft:oak_log"
                | "minecraft:spruce_log"
                | "minecraft:birch_log"
                | "minecraft:jungle_log"
                | "minecraft:acacia_log"
                | "minecraft:dark_oak_log"
                | "minecraft:mangrove_log"
                | "minecraft:cherry_log"
                | "minecraft:pale_oak_log"
                | "minecraft:crimson_stem"
                | "minecraft:warped_stem"
                | "minecraft:stripped_oak_log"
                | "minecraft:stripped_spruce_log"
                | "minecraft:stripped_birch_log"
                | "minecraft:stripped_jungle_log"
                | "minecraft:stripped_acacia_log"
                | "minecraft:stripped_dark_oak_log"
                | "minecraft:stripped_mangrove_log"
                | "minecraft:stripped_cherry_log"
                | "minecraft:stripped_pale_oak_log"
                | "minecraft:stripped_crimson_stem"
                | "minecraft:stripped_warped_stem"
        ),
        "leaves" => matches!(
            block,
            "minecraft:oak_leaves"
                | "minecraft:spruce_leaves"
                | "minecraft:birch_leaves"
                | "minecraft:jungle_leaves"
                | "minecraft:acacia_leaves"
                | "minecraft:dark_oak_leaves"
                | "minecraft:mangrove_leaves"
                | "minecraft:cherry_leaves"
                | "minecraft:pale_oak_leaves"
                | "minecraft:azalea_leaves"
                | "minecraft:flowering_azalea_leaves"
        ),
        "small_flowers" => matches!(
            block,
            "minecraft:dandelion"
                | "minecraft:poppy"
                | "minecraft:blue_orchid"
                | "minecraft:allium"
                | "minecraft:azure_bluet"
                | "minecraft:red_tulip"
                | "minecraft:orange_tulip"
                | "minecraft:white_tulip"
                | "minecraft:pink_tulip"
                | "minecraft:oxeye_daisy"
                | "minecraft:cornflower"
                | "minecraft:lily_of_the_valley"
                | "minecraft:wither_rose"
                | "minecraft:closed_eyeblossom"
                | "minecraft:open_eyeblossom"
        ),
        "replaceable_by_trees" => {
            block_matches_tag(block, "minecraft:leaves")
                || block_matches_tag(block, "minecraft:small_flowers")
                || matches!(
                    block,
                    "minecraft:pale_moss_carpet"
                        | "minecraft:short_grass"
                        | "minecraft:fern"
                        | "minecraft:dead_bush"
                        | "minecraft:vine"
                        | "minecraft:glow_lichen"
                        | "minecraft:sunflower"
                        | "minecraft:lilac"
                        | "minecraft:rose_bush"
                        | "minecraft:peony"
                        | "minecraft:tall_grass"
                        | "minecraft:large_fern"
                        | "minecraft:hanging_roots"
                        | "minecraft:pitcher_plant"
                        | "minecraft:water"
                        | "minecraft:seagrass"
                        | "minecraft:tall_seagrass"
                        | "minecraft:bush"
                        | "minecraft:firefly_bush"
                        | "minecraft:warped_roots"
                        | "minecraft:nether_sprouts"
                        | "minecraft:crimson_roots"
                        | "minecraft:leaf_litter"
                        | "minecraft:short_dry_grass"
                        | "minecraft:tall_dry_grass"
                )
        }
        "dirt" => matches!(
            block,
            "minecraft:dirt" | "minecraft:coarse_dirt" | "minecraft:rooted_dirt"
        ),
        "grass_blocks" => matches!(
            block,
            "minecraft:grass_block" | "minecraft:podzol" | "minecraft:mycelium"
        ),
        "mud" => matches!(block, "minecraft:mud" | "minecraft:muddy_mangrove_roots"),
        "moss_blocks" => matches!(block, "minecraft:moss_block" | "minecraft:pale_moss_block"),
        "substrate_overworld" => {
            block_matches_tag(block, "minecraft:dirt")
                || block_matches_tag(block, "minecraft:mud")
                || block_matches_tag(block, "minecraft:moss_blocks")
                || block_matches_tag(block, "minecraft:grass_blocks")
        }
        "supports_vegetation" => {
            block_matches_tag(block, "minecraft:substrate_overworld")
                || block == "minecraft:farmland"
        }
        "cannot_replace_below_tree_trunk" => {
            block_matches_tag(block, "minecraft:dirt")
                || block_matches_tag(block, "minecraft:mud")
                || block_matches_tag(block, "minecraft:moss_blocks")
                || block == "minecraft:podzol"
        }
        "replaceable" => {
            block == "minecraft:air"
                || block == "minecraft:cave_air"
                || block == "minecraft:void_air"
        }
        _ => false,
    }
}

pub fn placement_modifier_type(id: &str) -> Option<&'static str> {
    let name = id.strip_prefix("minecraft:").unwrap_or(id);
    WORLDGEN_TYPE_REGISTRIES
        .iter()
        .find(|registry| registry.id == "minecraft:placement_modifier_type")?
        .entries
        .iter()
        .copied()
        .find(|entry| entry.strip_prefix("minecraft:").unwrap_or(entry) == name)
}

pub fn placement_modifier_positions(
    modifier: PlacementModifier,
    origin: BlockPos,
    first_roll: i32,
    second_roll: i32,
    third_roll: i32,
) -> Vec<BlockPos> {
    match modifier {
        PlacementModifier::RarityFilter { chance } => {
            if chance > 0 && first_roll.rem_euclid(chance) == 0 {
                vec![origin]
            } else {
                Vec::new()
            }
        }
        PlacementModifier::Count { count } => vec![origin; count.max(0) as usize],
        PlacementModifier::CountProvider {
            sampled_count,
            provider: _,
        } => vec![origin; sampled_count.max(0) as usize],
        PlacementModifier::NoiseBasedCount {
            noise_to_count_ratio,
            noise_factor: _,
            noise_offset,
            sampled_noise,
        } => {
            let count =
                ((sampled_noise + noise_offset) * noise_to_count_ratio as f64).ceil() as i32;
            vec![origin; count.max(0) as usize]
        }
        PlacementModifier::NoiseThresholdCount {
            noise_level,
            below_noise,
            above_noise,
            sampled_noise,
        } => {
            let count = if sampled_noise < noise_level {
                below_noise
            } else {
                above_noise
            };
            vec![origin; count.max(0) as usize]
        }
        PlacementModifier::CountOnEveryLayer { positions } => positions.to_vec(),
        PlacementModifier::InSquare => vec![BlockPos {
            x: origin.x + first_roll.rem_euclid(16),
            y: origin.y,
            z: origin.z + second_roll.rem_euclid(16),
        }],
        PlacementModifier::RandomOffset {
            xz_spread,
            y_spread,
        } => {
            let xz_bound = xz_spread.abs() * 2 + 1;
            let y_bound = y_spread.abs() * 2 + 1;
            vec![BlockPos {
                x: origin.x + first_roll.rem_euclid(xz_bound) - xz_spread.abs(),
                y: origin.y + second_roll.rem_euclid(y_bound) - y_spread.abs(),
                z: origin.z + third_roll.rem_euclid(xz_bound) - xz_spread.abs(),
            }]
        }
        PlacementModifier::Fixed { positions } => {
            let chunk_x = origin.x.div_euclid(16);
            let chunk_z = origin.z.div_euclid(16);
            positions
                .iter()
                .copied()
                .filter(|pos| pos.x.div_euclid(16) == chunk_x && pos.z.div_euclid(16) == chunk_z)
                .collect()
        }
        PlacementModifier::BiomeFilter
        | PlacementModifier::BlockPredicateFilter { .. }
        | PlacementModifier::EnvironmentScan { .. }
        | PlacementModifier::SurfaceWaterDepthFilter { .. }
        | PlacementModifier::SurfaceRelativeThresholdFilter { .. }
        | PlacementModifier::Heightmap { .. }
        | PlacementModifier::HeightRange { .. } => Vec::new(),
    }
}

pub fn placed_feature_positions(
    modifiers: &[PlacementModifier],
    origin: BlockPos,
    context: PlacementContextModel,
    rolls: &[(i32, i32, i32)],
) -> Vec<BlockPos> {
    modifiers
        .iter()
        .enumerate()
        .fold(vec![origin], |positions, (index, modifier)| {
            let (first_roll, second_roll, third_roll) =
                rolls.get(index).copied().unwrap_or((0, 0, 0));
            positions
                .into_iter()
                .flat_map(|position| {
                    placement_modifier_positions_with_context(
                        *modifier,
                        position,
                        context,
                        first_roll,
                        second_roll,
                        third_roll,
                    )
                })
                .collect()
        })
}

pub fn placed_feature_invocations(
    configured_feature_id: &'static str,
    modifiers: &[PlacementModifier],
    origin: BlockPos,
    context: PlacementContextModel,
    rolls: &[(i32, i32, i32)],
) -> Result<Vec<PlacedFeatureInvocation>, String> {
    let feature = configured_feature(configured_feature_id)
        .ok_or_else(|| format!("unknown configured feature {configured_feature_id}"))?;
    Ok(placed_feature_positions(modifiers, origin, context, rolls)
        .into_iter()
        .map(|pos| PlacedFeatureInvocation {
            feature: feature.id,
            source: feature.source,
            pos,
        })
        .collect())
}

pub fn placement_modifier_positions_with_context(
    modifier: PlacementModifier,
    origin: BlockPos,
    context: PlacementContextModel,
    first_roll: i32,
    second_roll: i32,
    third_roll: i32,
) -> Vec<BlockPos> {
    match modifier {
        PlacementModifier::BiomeFilter => {
            if context.biome_allows_feature {
                vec![origin]
            } else {
                Vec::new()
            }
        }
        PlacementModifier::BlockPredicateFilter { predicate } => {
            if block_predicate_test(predicate, context.block_predicate, origin.y) {
                vec![origin]
            } else {
                Vec::new()
            }
        }
        PlacementModifier::SurfaceWaterDepthFilter { max_water_depth } => {
            if context.world_surface_height - context.ocean_floor_height <= max_water_depth {
                vec![origin]
            } else {
                Vec::new()
            }
        }
        PlacementModifier::SurfaceRelativeThresholdFilter {
            heightmap,
            min_inclusive,
            max_inclusive,
        } => {
            let surface = placement_context_height(context, heightmap);
            let min_y = surface + min_inclusive;
            let max_y = surface + max_inclusive;
            if (min_y..=max_y).contains(&origin.y) {
                vec![origin]
            } else {
                Vec::new()
            }
        }
        PlacementModifier::Heightmap { heightmap } => {
            let height = placement_context_height(context, heightmap);
            if height > context.min_y {
                vec![BlockPos {
                    x: origin.x,
                    y: height,
                    z: origin.z,
                }]
            } else {
                Vec::new()
            }
        }
        PlacementModifier::HeightRange { height } => vec![BlockPos {
            x: origin.x,
            y: height_provider_sample_with_rolls(
                height,
                WorldGenerationHeightContext {
                    min_y: context.min_y,
                    height: context.block_predicate.height,
                },
                first_roll,
                second_roll,
                third_roll,
            ),
            z: origin.z,
        }],
        PlacementModifier::EnvironmentScan {
            direction_y,
            target_condition,
            allowed_search_condition,
            max_steps,
            states,
        } => environment_scan_placement_position(
            origin,
            context,
            direction_y,
            target_condition,
            allowed_search_condition,
            max_steps,
            states,
        )
        .into_iter()
        .collect(),
        _ => placement_modifier_positions(modifier, origin, first_roll, second_roll, third_roll),
    }
}

pub fn environment_scan_placement_position(
    origin: BlockPos,
    fallback_context: PlacementContextModel,
    direction_y: i32,
    target_condition: BlockPredicate,
    allowed_search_condition: BlockPredicate,
    max_steps: i32,
    states: &[BlockPredicateContext],
) -> Option<BlockPos> {
    if !(1..=32).contains(&max_steps) || direction_y == 0 {
        return None;
    }

    let step = direction_y.signum();
    for i in 0..=max_steps {
        let pos = BlockPos {
            x: origin.x,
            y: origin.y + i * step,
            z: origin.z,
        };
        if pos.y < fallback_context.min_y
            || pos.y >= fallback_context.min_y + fallback_context.block_predicate.height
        {
            return None;
        }

        let block_context = states
            .get(i as usize)
            .copied()
            .unwrap_or(fallback_context.block_predicate);
        if i == 0 && !block_predicate_test(allowed_search_condition, block_context, pos.y) {
            return None;
        }
        if block_predicate_test(target_condition, block_context, pos.y) {
            return Some(pos);
        }
        if i == max_steps {
            break;
        }
        if !block_predicate_test(allowed_search_condition, block_context, pos.y) {
            return None;
        }
    }
    None
}

fn placement_context_height(context: PlacementContextModel, heightmap: HeightmapKind) -> i32 {
    match heightmap {
        HeightmapKind::WorldSurface | HeightmapKind::WorldSurfaceWg => context.world_surface_height,
        HeightmapKind::OceanFloor
        | HeightmapKind::OceanFloorWg
        | HeightmapKind::MotionBlocking
        | HeightmapKind::MotionBlockingNoLeaves => context.ocean_floor_height,
    }
}

pub fn flat_generator_preset(id: &str) -> Option<&'static FlatGeneratorPreset> {
    let name = id.strip_prefix("minecraft:").unwrap_or(id);
    FLAT_GENERATOR_PRESETS
        .iter()
        .find(|preset| preset.id.strip_prefix("minecraft:").unwrap_or(preset.id) == name)
}

pub fn flat_layers_total_height(layers: &[FlatLayerInfo]) -> i32 {
    layers.iter().map(|layer| layer.height).sum()
}

pub fn validate_flat_layers(layers: &[FlatLayerInfo]) -> Result<(), String> {
    let total_height = flat_layers_total_height(layers);
    if total_height > 384 {
        Err("Sum of layer heights is > 384".to_string())
    } else {
        Ok(())
    }
}

pub fn flat_block_at_y(layers: &[FlatLayerInfo], y: i32) -> Option<&'static str> {
    if y < 0 {
        return None;
    }
    let mut cursor = 0;
    for layer in layers {
        let next = cursor + layer.height;
        if y < next {
            return Some(layer.block);
        }
        cursor = next;
    }
    None
}

pub fn flat_layers_are_void(layers: &[FlatLayerInfo]) -> bool {
    layers.iter().all(|layer| layer.block == "minecraft:air")
}

pub fn world_preset(id: &str) -> Option<&'static WorldPresetEntry> {
    let name = id.strip_prefix("minecraft:").unwrap_or(id);
    WORLD_PRESETS
        .iter()
        .find(|preset| preset.id.strip_prefix("minecraft:").unwrap_or(preset.id) == name)
}

pub fn chunk_generator_kind(id: &str) -> Option<ChunkGeneratorKind> {
    match id.strip_prefix("minecraft:").unwrap_or(id) {
        "noise" => Some(ChunkGeneratorKind::Noise),
        "flat" => Some(ChunkGeneratorKind::Flat),
        "debug" => Some(ChunkGeneratorKind::Debug),
        _ => None,
    }
}

pub fn resolve_level_stem(stem: &LevelStemPreset) -> Result<ResolvedLevelStem, String> {
    let generator = match chunk_generator_kind(stem.generator)
        .ok_or_else(|| format!("Unknown chunk generator {}", stem.generator))?
    {
        ChunkGeneratorKind::Noise => {
            let settings_id = stem
                .noise_settings
                .ok_or_else(|| format!("Noise generator {} has no settings", stem.dimension))?;
            let settings = builtin_noise_generator_settings(settings_id)
                .ok_or_else(|| format!("Unknown noise settings {settings_id}"))?;
            let biome_source_model = biome_source_from_stem_id(stem.biome_source)
                .ok_or_else(|| format!("Unknown biome source {}", stem.biome_source))?;
            ResolvedChunkGenerator::Noise {
                biome_source: stem.biome_source,
                biome_source_model,
                noise_settings: settings,
            }
        }
        ChunkGeneratorKind::Flat => {
            if stem.noise_settings.is_some() {
                return Err(format!(
                    "Flat generator {} must not carry noise settings",
                    stem.dimension
                ));
            }
            let biome_source_model = biome_source_from_stem_id(stem.biome_source)
                .ok_or_else(|| format!("Unknown biome source {}", stem.biome_source))?;
            ResolvedChunkGenerator::Flat {
                biome_source_model,
                settings: default_flat_generator_settings()?,
            }
        }
        ChunkGeneratorKind::Debug => {
            if stem.noise_settings.is_some() {
                return Err(format!(
                    "Debug generator {} must not carry noise settings",
                    stem.dimension
                ));
            }
            let biome_source_model = biome_source_from_stem_id(stem.biome_source)
                .ok_or_else(|| format!("Unknown biome source {}", stem.biome_source))?;
            ResolvedChunkGenerator::Debug {
                biome: stem.biome_source,
                biome_source_model,
            }
        }
    };
    Ok(ResolvedLevelStem {
        dimension: stem.dimension,
        generator,
    })
}

pub fn resolve_world_preset(id: &str) -> Result<ResolvedWorldPreset, String> {
    let preset = world_preset(id).ok_or_else(|| format!("Unknown world preset {id}"))?;
    Ok(ResolvedWorldPreset {
        id: preset.id,
        overworld: resolve_level_stem(&preset.overworld)?,
        nether: resolve_level_stem(&preset.nether)?,
        end: resolve_level_stem(&preset.end)?,
    })
}

pub fn resolve_world_preset_from_registry(
    registry: &ParsedWorldgenPresetRegistry,
    id: &str,
) -> Result<ResolvedWorldPreset, String> {
    let id = static_world_preset_id(id).ok_or_else(|| format!("Unknown world preset {id}"))?;
    let parsed = registry
        .world_presets
        .get(id)
        .ok_or_else(|| format!("Missing world preset registry entry {id}"))?;
    let overworld = parsed_level_stem(parsed, "minecraft:overworld")?;
    let nether = parsed_level_stem(parsed, "minecraft:the_nether")?;
    let end = parsed_level_stem(parsed, "minecraft:the_end")?;
    Ok(ResolvedWorldPreset {
        id,
        overworld: resolve_parsed_level_stem("minecraft:overworld", overworld)?,
        nether: resolve_parsed_level_stem("minecraft:the_nether", nether)?,
        end: resolve_parsed_level_stem("minecraft:the_end", end)?,
    })
}

fn parsed_level_stem<'a>(
    preset: &'a ParsedWorldPreset,
    id: &str,
) -> Result<&'a ParsedLevelStem, String> {
    preset
        .dimensions
        .stems
        .iter()
        .find(|(stem_id, _)| stem_id == id)
        .map(|(_, stem)| stem)
        .ok_or_else(|| format!("Missing dimension {id}"))
}

fn resolve_parsed_level_stem(
    dimension: &'static str,
    stem: &ParsedLevelStem,
) -> Result<ResolvedLevelStem, String> {
    let parsed_dimension = static_dimension_type(&stem.dimension_type)
        .ok_or_else(|| format!("Unknown dimension type {}", stem.dimension_type))?;
    if parsed_dimension != dimension {
        return Err(format!(
            "Dimension {dimension} has mismatched type {}",
            stem.dimension_type
        ));
    }

    let generator = match &stem.generator {
        ParsedChunkGenerator::Noise {
            biome_source,
            settings,
        } => {
            let settings = builtin_noise_generator_settings(settings)
                .ok_or_else(|| format!("Unknown noise settings {settings}"))?;
            let (biome_source, biome_source_model) = resolve_parsed_biome_source(biome_source)?;
            ResolvedChunkGenerator::Noise {
                biome_source,
                biome_source_model,
                noise_settings: settings,
            }
        }
        ParsedChunkGenerator::Flat { settings } => {
            let biome_source_model = BiomeSourceModel::Fixed {
                biome: static_biome_id(&settings.biome)
                    .ok_or_else(|| format!("Unknown biome {}", settings.biome))?,
            };
            ResolvedChunkGenerator::Flat {
                biome_source_model,
                settings: flat_generator_settings_from_parsed(settings)?,
            }
        }
        ParsedChunkGenerator::Debug => ResolvedChunkGenerator::Debug {
            biome: "minecraft:plains",
            biome_source_model: BiomeSourceModel::Fixed {
                biome: "minecraft:plains",
            },
        },
    };

    Ok(ResolvedLevelStem {
        dimension,
        generator,
    })
}

fn resolve_parsed_biome_source(
    biome_source: &ParsedBiomeSource,
) -> Result<(&'static str, BiomeSourceModel), String> {
    match biome_source {
        ParsedBiomeSource::MultiNoisePreset { preset } => match strip_minecraft(preset) {
            "overworld" => Ok((
                "minecraft:multi_noise/overworld",
                BiomeSourceModel::MultiNoisePreset {
                    preset: "minecraft:overworld",
                },
            )),
            "nether" => Ok((
                "minecraft:multi_noise/nether",
                BiomeSourceModel::MultiNoisePreset {
                    preset: "minecraft:nether",
                },
            )),
            _ => Err(format!("Unknown multi-noise biome source preset {preset}")),
        },
        ParsedBiomeSource::TheEnd => Ok(("minecraft:the_end", BiomeSourceModel::TheEnd)),
        ParsedBiomeSource::Fixed { biome } => {
            let biome = static_biome_id(biome).ok_or_else(|| format!("Unknown biome {biome}"))?;
            Ok((biome, BiomeSourceModel::Fixed { biome }))
        }
        ParsedBiomeSource::Checkerboard { biomes, scale } => {
            let scale = i32::try_from(*scale)
                .map_err(|_| format!("checkerboard scale {scale} overflows i32"))?;
            let biomes = biomes
                .iter()
                .map(|biome| static_biome_id(biome).ok_or_else(|| format!("Unknown biome {biome}")))
                .collect::<Result<Vec<_>, _>>()?;
            Ok((
                "minecraft:checkerboard",
                BiomeSourceModel::Checkerboard { biomes, scale },
            ))
        }
    }
}

fn flat_generator_settings_from_parsed(
    parsed: &ParsedFlatGeneratorSettings,
) -> Result<FlatGeneratorSettingsModel, String> {
    let layers = parsed
        .layers
        .iter()
        .map(|(height, block)| {
            Ok(FlatLayerInfo {
                height: *height,
                block: static_block_id(block).ok_or_else(|| format!("Unknown block {block}"))?,
            })
        })
        .collect::<Result<Vec<_>, String>>()?;
    let expanded_raw = expand_flat_layers(&layers)?;
    let mut expanded_layers = expanded_raw.clone();
    let mut top_layer_modifications = Vec::new();
    let void_generation = expanded_layers
        .iter()
        .all(|state| state.map(|block| block == "minecraft:air").unwrap_or(true));

    for (y, state) in expanded_layers.iter_mut().enumerate() {
        let Some(block) = *state else {
            continue;
        };
        if !block_blocks_motion(block) {
            *state = None;
            top_layer_modifications.push((y, block));
        }
    }

    let structure_overrides = parsed
        .structure_overrides
        .iter()
        .map(|structure| {
            static_structure_set_id(structure)
                .ok_or_else(|| format!("Unknown structure override {structure}"))
        })
        .collect::<Result<Vec<_>, _>>()?;

    Ok(FlatGeneratorSettingsModel {
        biome: static_biome_id(&parsed.biome)
            .ok_or_else(|| format!("Unknown biome {}", parsed.biome))?,
        structure_overrides,
        add_lakes: parsed.add_lakes,
        decoration: parsed.decoration,
        layers,
        expanded_layers,
        top_layer_modifications,
        void_generation,
    })
}

