fn pine_foliage_rows(offset: i32, foliage_height: i32, leaf_radius: i32) -> Vec<(i32, i32)> {
    let mut rows = Vec::new();
    let mut current_radius = 0;
    for y_offset in (offset - foliage_height..=offset).rev() {
        rows.push((y_offset, current_radius));
        if current_radius >= 1 && y_offset == offset - foliage_height + 1 {
            current_radius -= 1;
        } else if current_radius < leaf_radius {
            current_radius += 1;
        }
    }
    rows
}

fn fancy_foliage_rows(offset: i32, foliage_height: i32, leaf_radius: i32) -> Vec<(i32, i32)> {
    let mut rows = Vec::new();
    for y_offset in (offset - foliage_height..=offset).rev() {
        let current_radius = leaf_radius
            + if y_offset != offset && y_offset != offset - foliage_height {
                1
            } else {
                0
            };
        rows.push((y_offset, current_radius));
    }
    rows
}

fn mega_jungle_foliage_rows(offset: i32, leaf_height: i32, leaf_radius: i32) -> Vec<(i32, i32)> {
    let mut rows = Vec::new();
    for y_offset in (offset - leaf_height..=offset).rev() {
        rows.push((y_offset, leaf_radius + 1 - y_offset));
    }
    rows
}

fn cherry_foliage_rows(foliage_height: i32, leaf_radius: i32) -> Vec<(i32, i32)> {
    let current_radius = leaf_radius - 1;
    let mut rows = vec![
        (foliage_height - 3, current_radius - 2),
        (foliage_height - 4, current_radius - 1),
    ];
    for y_offset in (0..=foliage_height - 5).rev() {
        rows.push((y_offset, current_radius));
    }
    rows.push((-1, current_radius));
    rows.push((-2, current_radius - 1));
    rows
}

fn random_spread_foliage_positions(
    origin: BlockPos,
    foliage_height: i32,
    leaf_radius: i32,
    leaf_placement_attempts: i32,
    rolls: &[i32],
) -> Vec<BlockPos> {
    if foliage_height <= 0 || leaf_radius <= 0 || leaf_placement_attempts <= 0 {
        return Vec::new();
    }
    let mut positions = Vec::new();
    for attempt in 0..leaf_placement_attempts as usize {
        let base = attempt * 6;
        let sample = |index: usize, bound: i32| {
            rolls
                .get(base + index)
                .copied()
                .unwrap_or(0)
                .rem_euclid(bound)
        };
        positions.push(BlockPos {
            x: origin.x + sample(0, leaf_radius) - sample(1, leaf_radius),
            y: origin.y + sample(2, foliage_height) - sample(3, foliage_height),
            z: origin.z + sample(4, leaf_radius) - sample(5, leaf_radius),
        });
    }
    positions
}

fn deterministic_random_spread_rolls(
    rand_a: i32,
    rand_b: i32,
    leaf_radius: i32,
    foliage_height: i32,
    leaf_placement_attempts: i32,
) -> Vec<i32> {
    if foliage_height <= 0 || leaf_radius <= 0 || leaf_placement_attempts <= 0 {
        return Vec::new();
    }
    let mut seed = (rand_a as i64 as u64)
        ^ (rand_b as i64 as u64).rotate_left(29)
        ^ (leaf_radius as i64 as u64).wrapping_mul(0x9e37_79b9_7f4a_7c15)
        ^ (foliage_height as i64 as u64).wrapping_mul(0xbf58_476d_1ce4_e5b9);
    let mut rolls = Vec::with_capacity(leaf_placement_attempts as usize * 6);
    for _ in 0..leaf_placement_attempts * 6 {
        seed = splitmix64(seed);
        rolls.push((seed >> 1) as i32);
    }
    rolls
}

fn splitmix64(mut value: u64) -> u64 {
    value = value.wrapping_add(0x9e37_79b9_7f4a_7c15);
    let mut mixed = value;
    mixed = (mixed ^ (mixed >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
    mixed = (mixed ^ (mixed >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
    mixed ^ (mixed >> 31)
}

fn mega_pine_foliage_rows(
    origin_y: i32,
    offset: i32,
    foliage_height: i32,
    leaf_radius: i32,
) -> Vec<(i32, i32)> {
    if foliage_height <= 0 {
        return vec![(offset, leaf_radius)];
    }
    let mut rows = Vec::new();
    let mut prev_radius = 0;
    for y_offset in (offset - foliage_height)..=offset {
        let yo = -y_offset;
        let smooth_radius =
            leaf_radius + ((yo as f32 / foliage_height as f32) * 3.5).floor() as i32;
        let jagged_radius =
            if yo > 0 && smooth_radius == prev_radius && (origin_y + y_offset).rem_euclid(2) == 0 {
                smooth_radius + 1
            } else {
                smooth_radius
            };
        rows.push((y_offset, jagged_radius));
        prev_radius = smooth_radius;
    }
    rows
}

fn spruce_foliage_rows(
    offset: i32,
    foliage_height: i32,
    leaf_radius: i32,
    initial_radius: i32,
) -> Vec<(i32, i32)> {
    let mut rows = Vec::new();
    let mut current_radius = initial_radius.clamp(0, 1);
    let mut max_radius = 1;
    let mut min_radius = 0;
    for y_offset in (-foliage_height..=offset).rev() {
        rows.push((y_offset, current_radius));
        if current_radius >= max_radius {
            current_radius = min_radius;
            min_radius = 1;
            max_radius = (max_radius + 1).min(leaf_radius);
        } else {
            current_radius += 1;
        }
    }
    rows
}

fn sample_inclusive_i32(min: i32, max: i32, roll: i32) -> i32 {
    if max <= min {
        min
    } else {
        min + roll.rem_euclid(max - min + 1)
    }
}

fn simple_leaves_row_should_skip_corner(
    dx: i32,
    y_offset: i32,
    dz: i32,
    radius: i32,
    blob_shape: bool,
    rand_a: i32,
    rand_b: i32,
) -> bool {
    if dx.abs() != radius || dz.abs() != radius {
        return false;
    }
    if blob_shape && y_offset == 0 {
        return true;
    }
    simple_tree_corner_roll(dx, y_offset, dz, rand_a, rand_b) == 0
}

fn live_blob_leaves_row_should_skip(
    dx: i32,
    y_offset: i32,
    dz: i32,
    radius: i32,
    random: &mut RandomSourceKind,
) -> bool {
    if dx.abs() != radius || dz.abs() != radius {
        return false;
    }
    random_next_i32_bound(random, 2) == 0 || y_offset == 0
}

fn acacia_leaves_row_should_skip(dx: i32, y_offset: i32, dz: i32, radius: i32) -> bool {
    if y_offset == 0 {
        (dx > 1 || dz > 1) && dx != 0 && dz != 0
    } else {
        dx == radius && dz == radius && radius > 0
    }
}

fn dark_oak_single_trunk_leaves_row_should_skip(
    dx: i32,
    y_offset: i32,
    dz: i32,
    radius: i32,
) -> bool {
    y_offset == -1 && dx == radius && dz == radius
}

fn conifer_leaves_row_should_skip(dx: i32, dz: i32, radius: i32) -> bool {
    dx == radius && dz == radius && radius > 0
}

fn fancy_leaves_row_should_skip(dx: i32, dz: i32, radius: i32) -> bool {
    let dx = dx.abs() as f32 + 0.5;
    let dz = dz.abs() as f32 + 0.5;
    dx * dx + dz * dz > (radius * radius) as f32
}

fn cherry_leaves_row_should_skip(
    dx: i32,
    y_offset: i32,
    dz: i32,
    radius: i32,
    wide_bottom_layer_hole_chance: f32,
    corner_hole_chance: f32,
    rand_a: i32,
    rand_b: i32,
) -> bool {
    if y_offset == -1
        && (dx == radius || dz == radius)
        && deterministic_chance_roll(dx, y_offset, dz, rand_a, rand_b)
            < wide_bottom_layer_hole_chance
    {
        return true;
    }

    let corner = dx == radius && dz == radius;
    let wide_layer = radius > 2;
    if wide_layer {
        corner
            || (dx + dz > radius * 2 - 2
                && deterministic_chance_roll(dx, y_offset, dz, rand_b, rand_a) < corner_hole_chance)
    } else {
        corner && deterministic_chance_roll(dx, y_offset, dz, rand_b, rand_a) < corner_hole_chance
    }
}

fn deterministic_chance_roll(dx: i32, y_offset: i32, dz: i32, rand_a: i32, rand_b: i32) -> f32 {
    (simple_tree_corner_roll(dx, y_offset, dz, rand_a, rand_b) as f32) * 0.5
}

fn mega_pine_leaves_row_should_skip(dx: i32, dz: i32, radius: i32) -> bool {
    dx + dz >= 7 || dx * dx + dz * dz > radius * radius
}

fn simple_tree_corner_roll(dx: i32, y_offset: i32, dz: i32, rand_a: i32, rand_b: i32) -> i32 {
    let mut value = (rand_a as i64 as u64)
        ^ (rand_b as i64 as u64).rotate_left(17)
        ^ (dx as i64 as u64).wrapping_mul(0x9e37_79b9_7f4a_7c15)
        ^ (y_offset as i64 as u64).wrapping_mul(0xbf58_476d_1ce4_e5b9)
        ^ (dz as i64 as u64).wrapping_mul(0x94d0_49bb_1331_11eb);
    value ^= value >> 30;
    value = value.wrapping_mul(0xbf58_476d_1ce4_e5b9);
    value ^= value >> 27;
    value = value.wrapping_mul(0x94d0_49bb_1331_11eb);
    ((value ^ (value >> 31)) & 1) as i32
}

fn push_tree_block(blocks: &mut Vec<TreePlacementBlock>, block: TreePlacementBlock) {
    if !blocks.iter().any(|existing| existing.pos == block.pos) {
        blocks.push(block);
    }
}

pub fn tree_leaf_distance_updates(
    logs: &[BlockPos],
    leaves: &[(BlockPos, i32)],
    decorations: &[BlockPos],
    roots: &[BlockPos],
) -> Vec<TreeLeafDistanceUpdate> {
    let Some(bounds) = bounding_box_for_positions(
        logs.iter()
            .chain(leaves.iter().map(|(pos, _)| pos))
            .chain(decorations.iter())
            .chain(roots.iter())
            .copied()
            .collect::<Vec<_>>()
            .as_slice(),
    ) else {
        return Vec::new();
    };

    let mut full = Vec::new();
    for pos in decorations.iter().chain(roots.iter()).copied() {
        if block_pos_inside_bounds(pos, bounds) && !full.contains(&pos) {
            full.push(pos);
        }
    }
    let mut to_check: Vec<Vec<BlockPos>> = vec![Vec::new(); 7];
    for pos in logs.iter().copied() {
        if block_pos_inside_bounds(pos, bounds) && !to_check[0].contains(&pos) {
            to_check[0].push(pos);
        }
    }

    let mut updates: Vec<TreeLeafDistanceUpdate> = Vec::new();
    let mut smallest_distance = 0_usize;
    while smallest_distance < 7 {
        if to_check[smallest_distance].is_empty() {
            smallest_distance += 1;
            continue;
        }
        let pos = to_check[smallest_distance].remove(0);
        if !block_pos_inside_bounds(pos, bounds) {
            continue;
        }
        if smallest_distance != 0 && !updates.iter().any(|update| update.pos == pos) {
            updates.push(TreeLeafDistanceUpdate {
                pos,
                distance: smallest_distance as i32,
            });
        }
        if !full.contains(&pos) {
            full.push(pos);
        }

        for neighbor in block_pos_six_neighbors(pos) {
            if !block_pos_inside_bounds(neighbor, bounds) || full.contains(&neighbor) {
                continue;
            }
            let Some((_, current_distance)) =
                leaves.iter().find(|(leaf_pos, _)| *leaf_pos == neighbor)
            else {
                continue;
            };
            let new_distance = (*current_distance).min(smallest_distance as i32 + 1);
            if new_distance < 7 {
                let bucket = new_distance as usize;
                if !to_check[bucket].contains(&neighbor) {
                    to_check[bucket].push(neighbor);
                }
                smallest_distance = smallest_distance.min(bucket);
            }
        }
    }

    updates
}

fn bounding_box_for_positions(positions: &[BlockPos]) -> Option<(BlockPos, BlockPos)> {
    let first = *positions.first()?;
    let mut min = first;
    let mut max = first;
    for pos in positions.iter().copied().skip(1) {
        min.x = min.x.min(pos.x);
        min.y = min.y.min(pos.y);
        min.z = min.z.min(pos.z);
        max.x = max.x.max(pos.x);
        max.y = max.y.max(pos.y);
        max.z = max.z.max(pos.z);
    }
    Some((min, max))
}

fn block_pos_inside_bounds(pos: BlockPos, bounds: (BlockPos, BlockPos)) -> bool {
    pos.x >= bounds.0.x
        && pos.y >= bounds.0.y
        && pos.z >= bounds.0.z
        && pos.x <= bounds.1.x
        && pos.y <= bounds.1.y
        && pos.z <= bounds.1.z
}

fn block_pos_six_neighbors(pos: BlockPos) -> [BlockPos; 6] {
    [
        BlockPos {
            x: pos.x + 1,
            ..pos
        },
        BlockPos {
            x: pos.x - 1,
            ..pos
        },
        BlockPos {
            y: pos.y + 1,
            ..pos
        },
        BlockPos {
            y: pos.y - 1,
            ..pos
        },
        BlockPos {
            z: pos.z + 1,
            ..pos
        },
        BlockPos {
            z: pos.z - 1,
            ..pos
        },
    ]
}

pub fn validate_feature_size(size: FeatureSizeModel) -> Result<FeatureSizeModel, String> {
    let min_clipped_height = match size {
        FeatureSizeModel::TwoLayers {
            min_clipped_height, ..
        }
        | FeatureSizeModel::ThreeLayers {
            min_clipped_height, ..
        } => min_clipped_height,
    };
    if min_clipped_height.is_some_and(|height| !(0..=80).contains(&height)) {
        return Err("min_clipped_height must be in 0..=80".to_string());
    }
    let valid = match size {
        FeatureSizeModel::TwoLayers {
            limit,
            lower_size,
            upper_size,
            ..
        } => {
            (0..=81).contains(&limit)
                && (0..=16).contains(&lower_size)
                && (0..=16).contains(&upper_size)
        }
        FeatureSizeModel::ThreeLayers {
            limit,
            upper_limit,
            lower_size,
            middle_size,
            upper_size,
            ..
        } => {
            (0..=80).contains(&limit)
                && (0..=80).contains(&upper_limit)
                && (0..=16).contains(&lower_size)
                && (0..=16).contains(&middle_size)
                && (0..=16).contains(&upper_size)
        }
    };
    if valid {
        Ok(size)
    } else {
        Err("feature size fields are outside vanilla codec ranges".to_string())
    }
}

pub fn feature_size_at_height(size: FeatureSizeModel, tree_height: i32, yo: i32) -> i32 {
    match size {
        FeatureSizeModel::TwoLayers {
            limit,
            lower_size,
            upper_size,
            ..
        } => {
            if yo < limit {
                lower_size
            } else {
                upper_size
            }
        }
        FeatureSizeModel::ThreeLayers {
            limit,
            upper_limit,
            lower_size,
            middle_size,
            upper_size,
            ..
        } => {
            if yo < limit {
                lower_size
            } else if yo >= tree_height - upper_limit {
                upper_size
            } else {
                middle_size
            }
        }
    }
}

pub fn tree_decorator_type(id: &str) -> Option<&'static str> {
    let name = id.strip_prefix("minecraft:").unwrap_or(id);
    WORLDGEN_TYPE_REGISTRIES
        .iter()
        .find(|registry| registry.id == "minecraft:tree_decorator_type")?
        .entries
        .iter()
        .copied()
        .find(|entry| entry.strip_prefix("minecraft:") == Some(name))
}

pub fn validate_tree_decorator(
    decorator: TreeDecoratorModel,
) -> Result<TreeDecoratorModel, String> {
    let probability = match decorator {
        TreeDecoratorModel::Cocoa { probability }
        | TreeDecoratorModel::LeaveVine { probability }
        | TreeDecoratorModel::Beehive { probability }
        | TreeDecoratorModel::CreakingHeart { probability }
        | TreeDecoratorModel::AttachedToLeaves { probability }
        | TreeDecoratorModel::AttachedToLogs { probability } => Some(probability),
        TreeDecoratorModel::TrunkVine
        | TreeDecoratorModel::PaleMoss { .. }
        | TreeDecoratorModel::AlterGround
        | TreeDecoratorModel::PlaceOnGround => None,
    };
    if probability.is_some_and(|probability| !(0.0..=1.0).contains(&probability)) {
        Err("tree decorator probability must be in 0.0..=1.0".to_string())
    } else if let TreeDecoratorModel::PaleMoss {
        leaves_probability,
        trunk_probability,
        ground_probability,
    } = decorator
    {
        if [leaves_probability, trunk_probability, ground_probability]
            .iter()
            .any(|probability| !(0.0..=1.0).contains(probability))
        {
            Err("pale moss decorator probabilities must be in 0.0..=1.0".to_string())
        } else {
            Ok(decorator)
        }
    } else {
        Ok(decorator)
    }
}

pub fn validate_attached_to_leaves_decorator_fields(
    exclusion_radius_xz: i32,
    exclusion_radius_y: i32,
    required_empty_blocks: i32,
    directions_len: usize,
) -> Result<(), String> {
    if !(0..=16).contains(&exclusion_radius_xz) || !(0..=16).contains(&exclusion_radius_y) {
        return Err("attached-to-leaves exclusion radii must be in 0..=16".to_string());
    }
    if !(1..=16).contains(&required_empty_blocks) {
        return Err("attached-to-leaves required_empty_blocks must be in 1..=16".to_string());
    }
    if directions_len == 0 {
        return Err("attached-to-leaves directions list must be non-empty".to_string());
    }
    Ok(())
}

pub fn validate_place_on_ground_decorator_fields(
    tries: i32,
    radius: i32,
    height: i32,
) -> Result<(), String> {
    if tries <= 0 {
        return Err("place-on-ground tries must be positive".to_string());
    }
    if radius < 0 || height < 0 {
        return Err("place-on-ground radius and height must be non-negative".to_string());
    }
    Ok(())
}

pub fn tree_decorator_should_place(probability: f32, random_next_float: f32) -> bool {
    random_next_float < probability
}

pub fn tree_lowest_trunk_or_root_positions(logs: &[BlockPos], roots: &[BlockPos]) -> Vec<BlockPos> {
    let mut sorted_logs = logs.to_vec();
    let mut sorted_roots = roots.to_vec();
    sorted_logs.sort_by_key(|pos| pos.y);
    sorted_roots.sort_by_key(|pos| pos.y);
    if sorted_roots.is_empty() {
        sorted_logs
    } else if sorted_logs
        .first()
        .zip(sorted_roots.first())
        .is_some_and(|(log, root)| log.y == root.y)
    {
        sorted_logs
            .into_iter()
            .chain(sorted_roots)
            .collect::<Vec<_>>()
    } else {
        sorted_roots
    }
}

pub fn trunk_vine_decorator_placement(
    logs: &[TrunkVineLogContext],
    random_next_int_3: &[i32],
) -> Vec<TreeDecoratorPlacement> {
    let mut sorted_logs = logs.to_vec();
    sorted_logs.sort_by_key(|log| log.pos.y);
    let mut roll_index = 0;
    let mut placements = Vec::new();
    for log in sorted_logs {
        for (target, air, state) in [
            (
                BlockPos {
                    x: log.pos.x - 1,
                    y: log.pos.y,
                    z: log.pos.z,
                },
                log.west_air,
                "minecraft:vine[east=true]",
            ),
            (
                BlockPos {
                    x: log.pos.x + 1,
                    y: log.pos.y,
                    z: log.pos.z,
                },
                log.east_air,
                "minecraft:vine[west=true]",
            ),
            (
                BlockPos {
                    x: log.pos.x,
                    y: log.pos.y,
                    z: log.pos.z - 1,
                },
                log.north_air,
                "minecraft:vine[south=true]",
            ),
            (
                BlockPos {
                    x: log.pos.x,
                    y: log.pos.y,
                    z: log.pos.z + 1,
                },
                log.south_air,
                "minecraft:vine[north=true]",
            ),
        ] {
            let roll = random_next_int_3.get(roll_index).copied().unwrap_or(0);
            roll_index += 1;
            if roll.rem_euclid(3) > 0 && air {
                placements.push(TreeDecoratorPlacement { pos: target, state });
            }
        }
    }
    placements
}

fn add_hanging_vine_placements(
    placements: &mut Vec<TreeDecoratorPlacement>,
    pos: BlockPos,
    direction_state: &'static str,
    below_air: &[bool; 4],
) {
    placements.push(TreeDecoratorPlacement {
        pos,
        state: direction_state,
    });
    for (index, air) in below_air.iter().copied().enumerate() {
        if !air {
            break;
        }
        placements.push(TreeDecoratorPlacement {
            pos: BlockPos {
                x: pos.x,
                y: pos.y - 1 - index as i32,
                z: pos.z,
            },
            state: direction_state,
        });
    }
}

pub fn leave_vine_decorator_placement(
    leaves: &[LeaveVineLeafContext],
    probability: f32,
    side_rolls: &[f32],
) -> Vec<TreeDecoratorPlacement> {
    let mut sorted_leaves = leaves.to_vec();
    sorted_leaves.sort_by_key(|leaf| leaf.pos.y);
    let mut roll_index = 0;
    let mut placements = Vec::new();
    for leaf in sorted_leaves {
        for (target, air, below_air, state) in [
            (
                BlockPos {
                    x: leaf.pos.x - 1,
                    y: leaf.pos.y,
                    z: leaf.pos.z,
                },
                leaf.west_air,
                leaf.west_below_air,
                "minecraft:vine[east=true]",
            ),
            (
                BlockPos {
                    x: leaf.pos.x + 1,
                    y: leaf.pos.y,
                    z: leaf.pos.z,
                },
                leaf.east_air,
                leaf.east_below_air,
                "minecraft:vine[west=true]",
            ),
            (
                BlockPos {
                    x: leaf.pos.x,
                    y: leaf.pos.y,
                    z: leaf.pos.z - 1,
                },
                leaf.north_air,
                leaf.north_below_air,
                "minecraft:vine[south=true]",
            ),
            (
                BlockPos {
                    x: leaf.pos.x,
                    y: leaf.pos.y,
                    z: leaf.pos.z + 1,
                },
                leaf.south_air,
                leaf.south_below_air,
                "minecraft:vine[north=true]",
            ),
        ] {
            let roll = side_rolls.get(roll_index).copied().unwrap_or(1.0);
            roll_index += 1;
            if roll < probability && air {
                add_hanging_vine_placements(&mut placements, target, state, &below_air);
            }
        }
    }
    placements
}

pub fn cocoa_decorator_placement(
    logs: &[CocoaLogContext],
    probability: f32,
    global_roll: f32,
    side_rolls: &[f32],
    age_rolls: &[i32],
) -> Vec<TreeDecoratorPlacement> {
    if global_roll >= probability {
        return Vec::new();
    }
    let mut sorted_logs = logs.to_vec();
    sorted_logs.sort_by_key(|log| log.pos.y);
    let Some(tree_y) = sorted_logs.first().map(|log| log.pos.y) else {
        return Vec::new();
    };
    let mut side_roll_index = 0;
    let mut age_roll_index = 0;
    let mut placements = Vec::new();
    for log in sorted_logs {
        if log.pos.y - tree_y > 2 {
            continue;
        }
        for (target, air, facing) in [
            (
                BlockPos {
                    x: log.pos.x,
                    y: log.pos.y,
                    z: log.pos.z + 1,
                },
                log.south_air,
                "north",
            ),
            (
                BlockPos {
                    x: log.pos.x - 1,
                    y: log.pos.y,
                    z: log.pos.z,
                },
                log.west_air,
                "east",
            ),
            (
                BlockPos {
                    x: log.pos.x,
                    y: log.pos.y,
                    z: log.pos.z - 1,
                },
                log.north_air,
                "south",
            ),
            (
                BlockPos {
                    x: log.pos.x + 1,
                    y: log.pos.y,
                    z: log.pos.z,
                },
                log.east_air,
                "west",
            ),
        ] {
            let side_roll = side_rolls.get(side_roll_index).copied().unwrap_or(1.0);
            side_roll_index += 1;
            if side_roll <= 0.25 && air {
                let age = age_rolls
                    .get(age_roll_index)
                    .copied()
                    .unwrap_or(0)
                    .rem_euclid(3);
                age_roll_index += 1;
                placements.push(TreeDecoratorPlacement {
                    pos: target,
                    state: match (age, facing) {
                        (0, "north") => "minecraft:cocoa[age=0,facing=north]",
                        (1, "north") => "minecraft:cocoa[age=1,facing=north]",
                        (2, "north") => "minecraft:cocoa[age=2,facing=north]",
                        (0, "east") => "minecraft:cocoa[age=0,facing=east]",
                        (1, "east") => "minecraft:cocoa[age=1,facing=east]",
                        (2, "east") => "minecraft:cocoa[age=2,facing=east]",
                        (0, "south") => "minecraft:cocoa[age=0,facing=south]",
                        (1, "south") => "minecraft:cocoa[age=1,facing=south]",
                        (2, "south") => "minecraft:cocoa[age=2,facing=south]",
                        (0, "west") => "minecraft:cocoa[age=0,facing=west]",
                        (1, "west") => "minecraft:cocoa[age=1,facing=west]",
                        _ => "minecraft:cocoa[age=2,facing=west]",
                    },
                });
            }
        }
    }
    placements
}

pub fn beehive_decorator_placement(
    logs: &[BlockPos],
    leaves: &[BlockPos],
    probability: f32,
    global_roll: f32,
    leafless_height_roll: i32,
    shuffled_candidate_indices: &[usize],
    candidate_air: &[(BlockPos, bool, bool)],
    bee_count_roll: i32,
    bee_ticks_rolls: &[i32],
) -> Option<BeehiveDecoratorPlacement> {
    if logs.is_empty() || global_roll >= probability {
        return None;
    }
    let mut sorted_logs = logs.to_vec();
    sorted_logs.sort_by_key(|pos| pos.y);
    let mut sorted_leaves = leaves.to_vec();
    sorted_leaves.sort_by_key(|pos| pos.y);
    let first_log_y = sorted_logs.first()?.y;
    let last_log_y = sorted_logs.last()?.y;
    let hive_y = if let Some(first_leaf) = sorted_leaves.first() {
        (first_leaf.y - 1).max(first_log_y + 1)
    } else {
        (first_log_y + 1 + leafless_height_roll.rem_euclid(3)).min(last_log_y)
    };
    let mut candidates = Vec::new();
    for log in sorted_logs.iter().filter(|pos| pos.y == hive_y) {
        candidates.extend([
            BlockPos {
                x: log.x + 1,
                y: log.y,
                z: log.z,
            },
            BlockPos {
                x: log.x,
                y: log.y,
                z: log.z + 1,
            },
            BlockPos {
                x: log.x - 1,
                y: log.y,
                z: log.z,
            },
        ]);
    }
    if candidates.is_empty() {
        return None;
    }
    let mut candidate_order = shuffled_candidate_indices
        .iter()
        .copied()
        .filter_map(|index| candidates.get(index).copied())
        .collect::<Vec<_>>();
    if candidate_order.len() < candidates.len() {
        for candidate in candidates {
            if !candidate_order.contains(&candidate) {
                candidate_order.push(candidate);
            }
        }
    }
    let hive_pos = candidate_order.into_iter().find(|candidate| {
        candidate_air
            .iter()
            .find(|(pos, _, _)| pos == candidate)
            .is_some_and(|(_, self_air, front_air)| *self_air && *front_air)
    })?;
    let bee_count = 2 + bee_count_roll.rem_euclid(2);
    let bee_ticks_in_hive = (0..bee_count as usize)
        .map(|index| {
            bee_ticks_rolls
                .get(index)
                .copied()
                .unwrap_or(0)
                .rem_euclid(599)
        })
        .collect();
    Some(BeehiveDecoratorPlacement {
        pos: hive_pos,
        state: "minecraft:bee_nest[facing=south,honey_level=0]",
        bee_ticks_in_hive,
    })
}

pub fn creaking_heart_decorator_placement(
    logs: &[BlockPos],
    probability: f32,
    global_roll: f32,
    shuffled_log_indices: &[usize],
    adjacent_log_checks: &[(BlockPos, [bool; 6])],
) -> Option<TreeDecoratorPlacement> {
    if logs.is_empty() || global_roll >= probability {
        return None;
    }
    let mut sorted_logs = logs.to_vec();
    sorted_logs.sort_by_key(|pos| pos.y);
    let mut log_order = shuffled_log_indices
        .iter()
        .copied()
        .filter_map(|index| sorted_logs.get(index).copied())
        .collect::<Vec<_>>();
    if log_order.len() < sorted_logs.len() {
        for log in sorted_logs {
            if !log_order.contains(&log) {
                log_order.push(log);
            }
        }
    }
    let pos = log_order.into_iter().find(|candidate| {
        adjacent_log_checks
            .iter()
            .find(|(pos, _)| pos == candidate)
            .is_some_and(|(_, checks)| checks.iter().all(|is_log| *is_log))
    })?;
    Some(TreeDecoratorPlacement {
        pos,
        state: "minecraft:creaking_heart[active=false,axis=y,natural=true]",
    })
}

pub fn place_on_ground_decorator_placement(
    lowest_trunk_or_root_positions: &[BlockPos],
    tries: i32,
    radius: i32,
    height: i32,
    block_state: &'static str,
    attempts: &[PlaceOnGroundAttemptContext],
) -> Result<Vec<TreeDecoratorPlacement>, String> {
    validate_place_on_ground_decorator_fields(tries, radius, height)?;
    let Some(origin) = lowest_trunk_or_root_positions.first().copied() else {
        return Ok(Vec::new());
    };
    let min_y = origin.y;
    let mut min_x = origin.x;
    let mut max_x = origin.x;
    let mut min_z = origin.z;
    let mut max_z = origin.z;
    for position in lowest_trunk_or_root_positions {
        if position.y == min_y {
            min_x = min_x.min(position.x);
            max_x = max_x.max(position.x);
            min_z = min_z.min(position.z);
            max_z = max_z.max(position.z);
        }
    }
    let bounds_min_x = min_x - radius;
    let bounds_max_x = max_x + radius;
    let bounds_min_y = min_y - height;
    let bounds_max_y = min_y + height;
    let bounds_min_z = min_z - radius;
    let bounds_max_z = max_z + radius;
    let mut placements = Vec::new();
    for attempt in attempts.iter().take(tries as usize) {
        if attempt.pos.x < bounds_min_x
            || attempt.pos.x > bounds_max_x
            || attempt.pos.y < bounds_min_y
            || attempt.pos.y > bounds_max_y
            || attempt.pos.z < bounds_min_z
            || attempt.pos.z > bounds_max_z
        {
            continue;
        }
        let above_pos = BlockPos {
            x: attempt.pos.x,
            y: attempt.pos.y + 1,
            z: attempt.pos.z,
        };
        if attempt.above_is_air_or_vine
            && attempt.pos_is_solid_render
            && attempt.motion_blocking_no_leaves_height <= above_pos.y
        {
            placements.push(TreeDecoratorPlacement {
                pos: above_pos,
                state: block_state,
            });
        }
    }
    Ok(placements)
}

fn alter_ground_scan_context_at(
    scan_contexts: &[AlterGroundScanContext],
    pos: BlockPos,
) -> AlterGroundScanContext {
    scan_contexts
        .iter()
        .copied()
        .find(|context| context.pos == pos)
        .unwrap_or(AlterGroundScanContext {
            pos,
            provider_state: None,
            is_air: true,
        })
}

fn alter_ground_place_block_at(
    placements: &mut Vec<TreeDecoratorPlacement>,
    pos: BlockPos,
    scan_contexts: &[AlterGroundScanContext],
) {
    for dy in (-3..=2).rev() {
        let cursor = BlockPos {
            x: pos.x,
            y: pos.y + dy,
            z: pos.z,
        };
        let context = alter_ground_scan_context_at(scan_contexts, cursor);
        if let Some(state) = context.provider_state {
            placements.push(TreeDecoratorPlacement { pos: cursor, state });
            break;
        }
        if !context.is_air && dy < 0 {
            break;
        }
    }
}

fn alter_ground_place_circle(
    placements: &mut Vec<TreeDecoratorPlacement>,
    pos: BlockPos,
    scan_contexts: &[AlterGroundScanContext],
) {
    for dx in -2i32..=2 {
        for dz in -2i32..=2 {
            if dx.abs() == 2 && dz.abs() == 2 {
                continue;
            }
            alter_ground_place_block_at(
                placements,
                BlockPos {
                    x: pos.x + dx,
                    y: pos.y,
                    z: pos.z + dz,
                },
                scan_contexts,
            );
        }
    }
}

pub fn alter_ground_decorator_placement(
    lowest_trunk_or_root_positions: &[BlockPos],
    random_next_int_64: &[i32],
    scan_contexts: &[AlterGroundScanContext],
) -> Vec<TreeDecoratorPlacement> {
    let mut sorted_positions = lowest_trunk_or_root_positions.to_vec();
    sorted_positions.sort_by_key(|pos| pos.y);
    let Some(min_y) = sorted_positions.first().map(|pos| pos.y) else {
        return Vec::new();
    };
    let roots = sorted_positions
        .into_iter()
        .filter(|pos| pos.y == min_y)
        .collect::<Vec<_>>();
    let mut placements = Vec::new();
    let mut roll_index = 0;
    for pos in roots {
        for anchor in [
            BlockPos {
                x: pos.x - 1,
                y: pos.y,
                z: pos.z - 1,
            },
            BlockPos {
                x: pos.x + 2,
                y: pos.y,
                z: pos.z - 1,
            },
            BlockPos {
                x: pos.x - 1,
                y: pos.y,
                z: pos.z + 2,
            },
            BlockPos {
                x: pos.x + 2,
                y: pos.y,
                z: pos.z + 2,
            },
        ] {
            alter_ground_place_circle(&mut placements, anchor, scan_contexts);
        }
        for _ in 0..5 {
            let placement = random_next_int_64
                .get(roll_index)
                .copied()
                .unwrap_or(0)
                .rem_euclid(64);
            roll_index += 1;
            let x_offset = placement % 8;
            let z_offset = placement / 8;
            if x_offset == 0 || x_offset == 7 || z_offset == 0 || z_offset == 7 {
                alter_ground_place_circle(
                    &mut placements,
                    BlockPos {
                        x: pos.x - 3 + x_offset,
                        y: pos.y,
                        z: pos.z - 3 + z_offset,
                    },
                    scan_contexts,
                );
            }
        }
    }
    placements
}

fn add_pale_moss_hanger_placements(
    placements: &mut Vec<TreeDecoratorPlacement>,
    mut pos: BlockPos,
    below_air: &[bool],
    hanger_rolls: &[f32],
    hanger_roll_index: &mut usize,
) {
    let mut below_index = 0;
    while below_air.get(below_index).copied().unwrap_or(false) {
        let roll = hanger_rolls.get(*hanger_roll_index).copied().unwrap_or(0.0);
        *hanger_roll_index += 1;
        if roll < 0.5 {
            break;
        }
        placements.push(TreeDecoratorPlacement {
            pos,
            state: "minecraft:pale_hanging_moss[tip=false]",
        });
        pos = BlockPos {
            x: pos.x,
            y: pos.y - 1,
            z: pos.z,
        };
        below_index += 1;
    }
    placements.push(TreeDecoratorPlacement {
        pos,
        state: "minecraft:pale_hanging_moss[tip=true]",
    });
}

pub fn pale_moss_decorator_placement(
    logs: &[PaleMossAttachmentContext],
    leaves: &[PaleMossAttachmentContext],
    leaves_probability: f32,
    trunk_probability: f32,
    ground_probability: f32,
    ground_roll: f32,
    trunk_rolls: &[f32],
    leaf_rolls: &[f32],
    hanger_rolls: &[f32],
) -> Vec<TreeDecoratorPlacement> {
    if logs.is_empty() {
        return Vec::new();
    }
    let mut sorted_logs = logs.to_vec();
    sorted_logs.sort_by_key(|log| log.pos.y);
    let mut sorted_leaves = leaves.to_vec();
    sorted_leaves.sort_by_key(|leaf| leaf.pos.y);
    let mut placements = Vec::new();
    if ground_roll < ground_probability {
        let origin = sorted_logs
            .iter()
            .map(|log| log.pos)
            .min_by_key(|pos| pos.y)
            .expect("logs is non-empty");
        placements.push(TreeDecoratorPlacement {
            pos: BlockPos {
                x: origin.x,
                y: origin.y + 1,
                z: origin.z,
            },
            state: "minecraft:configured_feature/pale_moss_patch",
        });
    }
    let mut hanger_roll_index = 0;
    for (index, log) in sorted_logs.iter().enumerate() {
        let roll = trunk_rolls.get(index).copied().unwrap_or(1.0);
        if roll < trunk_probability && log.down_air {
            add_pale_moss_hanger_placements(
                &mut placements,
                BlockPos {
                    x: log.pos.x,
                    y: log.pos.y - 1,
                    z: log.pos.z,
                },
                &log.below_air,
                hanger_rolls,
                &mut hanger_roll_index,
            );
        }
    }
    for (index, leaf) in sorted_leaves.iter().enumerate() {
        let roll = leaf_rolls.get(index).copied().unwrap_or(1.0);
        if roll < leaves_probability && leaf.down_air {
            add_pale_moss_hanger_placements(
                &mut placements,
                BlockPos {
                    x: leaf.pos.x,
                    y: leaf.pos.y - 1,
                    z: leaf.pos.z,
                },
                &leaf.below_air,
                hanger_rolls,
                &mut hanger_roll_index,
            );
        }
    }
    placements
}

fn relative_direction(pos: BlockPos, direction: &str) -> BlockPos {
    match direction {
        "down" => BlockPos {
            x: pos.x,
            y: pos.y - 1,
            z: pos.z,
        },
        "up" => BlockPos {
            x: pos.x,
            y: pos.y + 1,
            z: pos.z,
        },
        "north" => BlockPos {
            x: pos.x,
            y: pos.y,
            z: pos.z - 1,
        },
        "south" => BlockPos {
            x: pos.x,
            y: pos.y,
            z: pos.z + 1,
        },
        "west" => BlockPos {
            x: pos.x - 1,
            y: pos.y,
            z: pos.z,
        },
        "east" => BlockPos {
            x: pos.x + 1,
            y: pos.y,
            z: pos.z,
        },
        _ => pos,
    }
}

pub fn attached_to_logs_decorator_placement(
    logs: &[BlockPos],
    probability: f32,
    block_state: &'static str,
    shuffled_log_indices: &[usize],
    direction_choices: &[&str],
    probability_rolls: &[f32],
    placement_air: &[(BlockPos, bool)],
) -> Vec<TreeDecoratorPlacement> {
    let mut sorted_logs = logs.to_vec();
    sorted_logs.sort_by_key(|pos| pos.y);
    let mut log_order = shuffled_log_indices
        .iter()
        .copied()
        .filter_map(|index| sorted_logs.get(index).copied())
        .collect::<Vec<_>>();
    if log_order.len() < sorted_logs.len() {
        for log in sorted_logs {
            if !log_order.contains(&log) {
                log_order.push(log);
            }
        }
    }
    let mut placements = Vec::new();
    for (index, log) in log_order.into_iter().enumerate() {
        let direction = direction_choices.get(index).copied().unwrap_or("north");
        let placement_pos = relative_direction(log, direction);
        let roll = probability_rolls.get(index).copied().unwrap_or(1.0);
        let is_air = placement_air
            .iter()
            .find(|(pos, _)| *pos == placement_pos)
            .is_some_and(|(_, air)| *air);
        if roll <= probability && is_air {
            placements.push(TreeDecoratorPlacement {
                pos: placement_pos,
                state: block_state,
            });
        }
    }
    placements
}

fn contains_required_empty_blocks(
    leaf_pos: BlockPos,
    direction: &str,
    required_empty_blocks: i32,
    air_checks: &[(BlockPos, bool)],
) -> bool {
    (1..=required_empty_blocks).all(|distance| {
        let check_pos = match direction {
            "down" => BlockPos {
                x: leaf_pos.x,
                y: leaf_pos.y - distance,
                z: leaf_pos.z,
            },
            "up" => BlockPos {
                x: leaf_pos.x,
                y: leaf_pos.y + distance,
                z: leaf_pos.z,
            },
            "north" => BlockPos {
                x: leaf_pos.x,
                y: leaf_pos.y,
                z: leaf_pos.z - distance,
            },
            "south" => BlockPos {
                x: leaf_pos.x,
                y: leaf_pos.y,
                z: leaf_pos.z + distance,
            },
            "west" => BlockPos {
                x: leaf_pos.x - distance,
                y: leaf_pos.y,
                z: leaf_pos.z,
            },
            "east" => BlockPos {
                x: leaf_pos.x + distance,
                y: leaf_pos.y,
                z: leaf_pos.z,
            },
            _ => leaf_pos,
        };
        air_checks
            .iter()
            .find(|(pos, _)| *pos == check_pos)
            .is_some_and(|(_, air)| *air)
    })
}

pub fn attached_to_leaves_decorator_placement(
    leaves: &[BlockPos],
    probability: f32,
    exclusion_radius_xz: i32,
    exclusion_radius_y: i32,
    required_empty_blocks: i32,
    block_state: &'static str,
    shuffled_leaf_indices: &[usize],
    direction_choices: &[&str],
    probability_rolls: &[f32],
    air_checks: &[(BlockPos, bool)],
) -> Result<Vec<TreeDecoratorPlacement>, String> {
    validate_attached_to_leaves_decorator_fields(
        exclusion_radius_xz,
        exclusion_radius_y,
        required_empty_blocks,
        direction_choices.len(),
    )?;
    let mut sorted_leaves = leaves.to_vec();
    sorted_leaves.sort_by_key(|pos| pos.y);
    let mut leaf_order = shuffled_leaf_indices
        .iter()
        .copied()
        .filter_map(|index| sorted_leaves.get(index).copied())
        .collect::<Vec<_>>();
    if leaf_order.len() < sorted_leaves.len() {
        for leaf in sorted_leaves {
            if !leaf_order.contains(&leaf) {
                leaf_order.push(leaf);
            }
        }
    }
    let mut blacklist = Vec::new();
    let mut placements = Vec::new();
    for (index, leaf_pos) in leaf_order.into_iter().enumerate() {
        let direction = direction_choices.get(index).copied().unwrap_or("down");
        let placement_pos = relative_direction(leaf_pos, direction);
        let roll = probability_rolls.get(index).copied().unwrap_or(1.0);
        if blacklist.contains(&(placement_pos.x, placement_pos.y, placement_pos.z))
            || roll >= probability
        {
            continue;
        }
        if !contains_required_empty_blocks(leaf_pos, direction, required_empty_blocks, air_checks) {
            continue;
        }
        for x in placement_pos.x - exclusion_radius_xz..=placement_pos.x + exclusion_radius_xz {
            for y in placement_pos.y - exclusion_radius_y..=placement_pos.y + exclusion_radius_y {
                for z in
                    placement_pos.z - exclusion_radius_xz..=placement_pos.z + exclusion_radius_xz
                {
                    blacklist.push((x, y, z));
                }
            }
        }
        placements.push(TreeDecoratorPlacement {
            pos: placement_pos,
            state: block_state,
        });
    }
    Ok(placements)
}

pub fn spring_feature_can_place(
    valid_above: bool,
    requires_block_below: bool,
    valid_below: bool,
    current_is_air_or_valid: bool,
    adjacent_rock_count: i32,
    adjacent_hole_count: i32,
    required_rock_count: i32,
    required_hole_count: i32,
) -> bool {
    valid_above
        && (!requires_block_below || valid_below)
        && current_is_air_or_valid
        && adjacent_rock_count == required_rock_count
        && adjacent_hole_count == required_hole_count
}

pub fn spring_placement_plan(
    config: &SpringConfigurationModel,
    context: SpringPlacementContext,
) -> Option<SpringPlacementPlan> {
    let valid_above = config.valid_blocks.contains(&context.above_block);
    let valid_below = config.valid_blocks.contains(&context.below_block);
    let current_is_air_or_valid = context.current_block == "minecraft:air"
        || config.valid_blocks.contains(&context.current_block);
    let adjacent_blocks = [
        context.west_block,
        context.east_block,
        context.north_block,
        context.south_block,
        context.below_block,
    ];
    let adjacent_rock_count = adjacent_blocks
        .iter()
        .filter(|block| config.valid_blocks.contains(block))
        .count() as i32;
    let adjacent_hole_count = adjacent_blocks
        .iter()
        .filter(|block| **block == "minecraft:air")
        .count() as i32;
    spring_feature_can_place(
        valid_above,
        config.requires_block_below,
        valid_below,
        current_is_air_or_valid,
        adjacent_rock_count,
        adjacent_hole_count,
        config.rock_count,
        config.hole_count,
    )
    .then_some(SpringPlacementPlan {
        pos: context.origin,
        state: config.state,
        schedule_tick: true,
    })
}

pub fn monster_room_opening_count_is_valid(openings: i32) -> bool {
    openings >= MONSTER_ROOM_BOUNDS.min_openings && openings <= MONSTER_ROOM_BOUNDS.max_openings
}

pub fn monster_room_radii(x_roll: i32, z_roll: i32) -> MonsterRoomRadii {
    MonsterRoomRadii {
        x_radius: x_roll.rem_euclid(2) + 2,
        z_radius: z_roll.rem_euclid(2) + 2,
    }
}

pub fn monster_room_bounds_for_radius(radius: i32) -> (i32, i32) {
    (-radius - 1, radius + 1)
}

pub fn monster_room_opening_count(
    radii: MonsterRoomRadii,
    probes: &[MonsterRoomProbe],
) -> Option<i32> {
    let (min_x, max_x) = monster_room_bounds_for_radius(radii.x_radius);
    let (min_z, max_z) = monster_room_bounds_for_radius(radii.z_radius);
    let mut openings = 0;
    for probe in probes {
        if probe.dy == MONSTER_ROOM_BOUNDS.min_y && !probe.solid {
            return None;
        }
        if probe.dy == MONSTER_ROOM_BOUNDS.max_y && !probe.solid {
            return None;
        }
        if (probe.dx == min_x || probe.dx == max_x || probe.dz == min_z || probe.dz == max_z)
            && probe.dy == 0
            && probe.empty
            && probe.above_empty
        {
            openings += 1;
        }
    }
    Some(openings)
}

pub fn monster_room_can_place(radii: MonsterRoomRadii, probes: &[MonsterRoomProbe]) -> bool {
    monster_room_opening_count(radii, probes).is_some_and(monster_room_opening_count_is_valid)
}

pub fn monster_room_shell_state(
    dx: i32,
    dy: i32,
    dz: i32,
    radii: MonsterRoomRadii,
    y: i32,
    below_solid: bool,
    current_solid: bool,
    current_is_chest: bool,
    mossy_roll: i32,
) -> Option<&'static str> {
    let (min_x, max_x) = monster_room_bounds_for_radius(radii.x_radius);
    let (min_z, max_z) = monster_room_bounds_for_radius(radii.z_radius);
    let boundary = dx == min_x
        || dy == MONSTER_ROOM_BOUNDS.min_y
        || dz == min_z
        || dx == max_x
        || dy == MONSTER_ROOM_BOUNDS.max_y
        || dz == max_z;
    if boundary {
        if y >= 0 && !below_solid {
            Some("minecraft:cave_air")
        } else if current_solid && !current_is_chest {
            if dy == MONSTER_ROOM_BOUNDS.min_y && mossy_roll.rem_euclid(4) != 0 {
                Some("minecraft:mossy_cobblestone")
            } else {
                Some("minecraft:cobblestone")
            }
        } else {
            None
        }
    } else if !current_is_chest {
        Some("minecraft:cave_air")
    } else {
        None
    }
}

pub fn monster_room_chest_can_place(empty: bool, horizontal_solid_neighbors: i32) -> bool {
    empty && horizontal_solid_neighbors == 1
}

pub fn monster_room_spawner_mob(mob_roll: i32) -> &'static str {
    match mob_roll.rem_euclid(4) {
        0 => "minecraft:skeleton",
        1 | 2 => "minecraft:zombie",
        _ => "minecraft:spider",
    }
}

pub fn ore_vein_sphere_is_shadowed(radius_delta: f64, dx: f64, dy: f64, dz: f64) -> bool {
    radius_delta * radius_delta > dx * dx + dy * dy + dz * dz
}

pub fn blending_height_to_offset(height: f64) -> f64 {
    let target_y = height + 0.5;
    let target_y_mod = target_y.rem_euclid(8.0);
    (32.0 * (target_y - 128.0) - 3.0 * (target_y - 120.0) * target_y_mod
        + 3.0 * target_y_mod * target_y_mod)
        / (128.0 * (32.0 - 3.0 * target_y_mod))
}

pub fn blending_smooth_alpha(distance: f64, range_cells: i32) -> f64 {
    let alpha = (distance / f64::from(range_cells + 1)).clamp(0.0, 1.0);
    3.0 * alpha * alpha - 2.0 * alpha * alpha * alpha
}

pub fn validate_blending_data_packed(data: BlendingDataPacked<'_>) -> Result<(), String> {
    match data.heights {
        Some(heights) if heights.len() != BLENDING_CELL_COLUMN_COUNT => Err(format!(
            "heights has to be of length {BLENDING_CELL_COLUMN_COUNT}"
        )),
        _ => Ok(()),
    }
}

pub fn blending_output_for_old_height(
    height: Option<f64>,
    distance_cells: Option<f64>,
) -> BlendingOutput {
    match (height, distance_cells) {
        (Some(height), Some(distance)) => BlendingOutput {
            alpha: blending_smooth_alpha(distance, BLENDING_CONSTANTS.height_blending_range_cells),
            blending_offset: blending_height_to_offset(height),
        },
        (Some(height), None) => BlendingOutput {
            alpha: 0.0,
            blending_offset: blending_height_to_offset(height),
        },
        (None, _) => BlendingOutput {
            alpha: 1.0,
            blending_offset: 0.0,
        },
    }
}

pub fn below_zero_replace_old_bedrock_action(y: i32, state: &str) -> Option<&'static str> {
    (0..=BELOW_ZERO_RETROGEN_MODEL.max_generated_bedrock_y)
        .contains(&y)
        .then_some(state)
        .filter(|state| *state == "minecraft:bedrock")
        .map(|_| "minecraft:deepslate")
}

pub fn below_zero_missing_bedrock_bit_index(x: i32, z: i32) -> usize {
    ((z & 15) * 16 + (x & 15)) as usize
}

pub fn below_zero_has_bedrock_hole(missing_bedrock: &[u64], x: i32, z: i32) -> bool {
    let bit = below_zero_missing_bedrock_bit_index(x, z);
    missing_bedrock
        .get(bit / 64)
        .is_some_and(|word| (word & (1_u64 << (bit % 64))) != 0)
}

pub fn below_zero_bedrock_mask_air_columns(
    min_y: i32,
    max_y: i32,
    missing_bedrock: &[u64],
) -> Vec<FeaturePlacementBlock> {
    let mut blocks = Vec::new();
    for x in 0..16 {
        for z in 0..16 {
            if below_zero_has_bedrock_hole(missing_bedrock, x, z) {
                for y in min_y..=max_y {
                    blocks.push(FeaturePlacementBlock {
                        pos: BlockPos { x, y, z },
                        state: "minecraft:air",
                    });
                }
            }
        }
    }
    blocks
}

pub fn below_zero_retrogen_biome(
    upgrading: bool,
    resolved_biome: &'static str,
    existing_chunk_biome_at_y0: &'static str,
) -> &'static str {
    if upgrading
        && !BELOW_ZERO_RETROGEN_MODEL
            .retained_biomes
            .contains(&resolved_biome)
    {
        existing_chunk_biome_at_y0
    } else {
        resolved_biome
    }
}

pub fn initial_spawn_position(
    debug_only_half_world: bool,
    debug_world_recreate: bool,
    is_debug: bool,
    spawn_chunk_x: i32,
    spawn_chunk_z: i32,
    generator_spawn_height: i32,
    min_y: i32,
    world_surface_height_at_chunk_center: i32,
) -> InitialSpawnKind {
    if debug_only_half_world && debug_world_recreate {
        InitialSpawnKind::DebugHalfWorld {
            x: 0,
            y: 64,
            z: -100,
        }
    } else if is_debug {
        InitialSpawnKind::DebugWorld { x: 0, y: 80, z: 0 }
    } else {
        let y = if generator_spawn_height < min_y {
            world_surface_height_at_chunk_center
        } else {
            generator_spawn_height
        };
        InitialSpawnKind::Normal {
            x: spawn_chunk_x * 16 + 8,
            y,
            z: spawn_chunk_z * 16 + 8,
        }
    }
}

pub fn initial_spawn_chunk_spiral_offsets() -> Vec<(i32, i32)> {
    let radius = SPAWN_SELECTION_CONSTANTS.initial_chunk_search_radius;
    let mut x_offset = 0;
    let mut z_offset = 0;
    let mut dx = 0;
    let mut dz = -1;
    let mut offsets = Vec::with_capacity(((radius * 2 + 1) * (radius * 2 + 1)) as usize);

    for _ in 0..(radius * 2 + 1).pow(2) {
        if x_offset >= -radius && x_offset <= radius && z_offset >= -radius && z_offset <= radius {
            offsets.push((x_offset, z_offset));
        }

        if x_offset == z_offset
            || (x_offset < 0 && x_offset == -z_offset)
            || (x_offset > 0 && x_offset == 1 - z_offset)
        {
            let old_dx = dx;
            dx = -dz;
            dz = old_dx;
        }

        x_offset += dx;
        z_offset += dz;
    }

    offsets
}

pub fn climate_spawn_position(
    target_climates: &[ClimateParameterPoint],
    noise_router: NoiseRouter,
    settings: NoiseGeneratorSettings,
    seed: i64,
) -> BlockPos {
    if target_climates.is_empty() {
        return BlockPos { x: 0, y: 0, z: 0 };
    }
    let sampler = ClimateSampler::from_noise_router(&noise_router, seed, settings);
    let mut best = climate_spawn_position_and_fitness(target_climates, &sampler, 0, 0);
    climate_spawn_radial_search(target_climates, &sampler, &mut best, 2048.0, 512.0);
    climate_spawn_radial_search(target_climates, &sampler, &mut best, 512.0, 32.0);
    best.location
}

fn climate_spawn_radial_search(
    target_climates: &[ClimateParameterPoint],
    sampler: &ClimateSampler,
    best: &mut ClimateSpawnCandidate,
    max_radius: f32,
    radius_increment: f32,
) {
    let mut angle = 0.0_f32;
    let mut radius = radius_increment;
    let search_origin = best.location;
    while radius <= max_radius {
        let x = search_origin.x + (angle.sin() * radius) as i32;
        let z = search_origin.z + (angle.cos() * radius) as i32;
        let candidate = climate_spawn_position_and_fitness(target_climates, sampler, x, z);
        if candidate.fitness < best.fitness {
            *best = candidate;
        }
        angle += radius_increment / radius;
        if angle > std::f32::consts::TAU {
            angle = 0.0;
            radius += radius_increment;
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct ClimateSpawnCandidate {
    location: BlockPos,
    fitness: i64,
}

fn climate_spawn_position_and_fitness(
    target_climates: &[ClimateParameterPoint],
    sampler: &ClimateSampler,
    block_x: i32,
    block_z: i32,
) -> ClimateSpawnCandidate {
    let target = sampler.sample(block_x.div_euclid(4), 0, block_z.div_euclid(4));
    let zero_depth_target = ClimateTarget { depth: 0, ..target };
    let min_fitness = target_climates
        .iter()
        .map(|point| point.fitness(zero_depth_target))
        .min()
        .unwrap_or(i64::MAX);
    let distance_bias =
        i64::from(block_x) * i64::from(block_x) + i64::from(block_z) * i64::from(block_z);
    ClimateSpawnCandidate {
        location: BlockPos {
            x: block_x,
            y: 0,
            z: block_z,
        },
        fitness: min_fitness
            .saturating_mul(2048_i64 * 2048_i64)
            .saturating_add(distance_bias),
    }
}

pub fn spawn_search_candidate_count(radius: i32) -> i32 {
    let side = i64::from(radius.max(0)) * 2 + 1;
    i64::from(SPAWN_SELECTION_CONSTANTS.spawn_search_absolute_max_attempts).min(side * side) as i32
}

pub fn spawn_search_coprime(candidate_count: i32) -> i32 {
    if candidate_count <= SPAWN_SELECTION_CONSTANTS.small_search_coprime_threshold {
        candidate_count - 1
    } else {
        SPAWN_SELECTION_CONSTANTS.large_search_coprime
    }
}

pub fn spawn_search_radius(respawn_radius_rule: i32, distance_to_border: i32) -> i32 {
    let mut radius = respawn_radius_rule.max(0);
    if distance_to_border < radius {
        radius = distance_to_border;
    }
    if distance_to_border <= 1 {
        radius = 1;
    }
    radius
}

pub fn spawn_search_candidate(
    spawn_x: i32,
    spawn_z: i32,
    radius: i32,
    random_offset: i32,
    candidate_index: i32,
) -> Option<(i32, i32)> {
    let candidate_count = spawn_search_candidate_count(radius);
    if candidate_index >= candidate_count {
        return None;
    }
    let side = radius.max(0) * 2 + 1;
    let value = (random_offset.rem_euclid(candidate_count)
        + spawn_search_coprime(candidate_count) * candidate_index)
        .rem_euclid(candidate_count);
    let delta_x = value % side;
    let delta_z = value / side;
    Some((spawn_x + delta_x - radius, spawn_z + delta_z - radius))
}

pub fn initial_spawn_required_chunks(center: ChunkPos) -> Vec<ChunkPos> {
    let radius = SPAWN_SELECTION_CONSTANTS.player_spawn_ticket_radius;
    let mut chunks = Vec::with_capacity(((radius * 2 + 1) * (radius * 2 + 1)) as usize);
    for z in center.z - radius..=center.z + radius {
        for x in center.x - radius..=center.x + radius {
            chunks.push(ChunkPos { x, z });
        }
    }
    chunks
}

pub fn initial_spawn_readiness_report(
    center: ChunkPos,
    generated_chunks: &[SpawnChunkStatusSnapshot],
) -> InitialSpawnReadinessReport {
    let required_status = "minecraft:full";
    let required_index = chunk_status(required_status)
        .map(|status| status.index)
        .unwrap_or(usize::MAX);
    let status_by_pos: BTreeMap<ChunkPos, &'static str> = generated_chunks
        .iter()
        .map(|snapshot| (snapshot.pos, snapshot.status))
        .collect();
    let mut missing_chunks = Vec::new();
    let mut not_ready_chunks = Vec::new();

    for pos in initial_spawn_required_chunks(center) {
        let Some(status) = status_by_pos.get(&pos).copied() else {
            missing_chunks.push(pos);
            continue;
        };
        let status_index = chunk_status(status).map(|entry| entry.index).unwrap_or(0);
        if status_index < required_index {
            not_ready_chunks.push(SpawnChunkStatusSnapshot { pos, status });
        }
    }

    InitialSpawnReadinessReport {
        center,
        required_radius: SPAWN_SELECTION_CONSTANTS.player_spawn_ticket_radius,
        required_status,
        ticket_type: "minecraft:player_spawn",
        ticket_level: crate::chunk_ticket::FULL_CHUNK_LEVEL
            - SPAWN_SELECTION_CONSTANTS.player_spawn_ticket_radius,
        missing_chunks,
        not_ready_chunks,
    }
}

pub fn initial_spawn_chunks_ready(
    center: ChunkPos,
    generated_chunks: &[SpawnChunkStatusSnapshot],
) -> bool {
    initial_spawn_readiness_report(center, generated_chunks).is_ready()
}

pub fn overworld_respawn_y(
    heights: SpawnColumnHeights,
    cave_world: bool,
    blocks_from_top_plus_one_down: &[SpawnBlockKind],
) -> Option<i32> {
    let top_y = heights.top_y;
    if top_y < heights.min_y {
        return None;
    }
    if heights.surface_y <= top_y && heights.surface_y > heights.ocean_floor_y {
        return None;
    }
    let mut y = top_y + 1;
    for block in blocks_from_top_plus_one_down {
        if y < heights.min_y {
            break;
        }
        if *block == SpawnBlockKind::Fluid {
            break;
        }
        if *block == SpawnBlockKind::Solid {
            return Some(y + 1);
        }
        y -= 1;
    }
    if cave_world && blocks_from_top_plus_one_down.is_empty() {
        None
    } else {
        None
    }
}

pub fn fixup_spawn_height(
    spawn_y: i32,
    min_y: i32,
    max_y: i32,
    no_collision_no_liquid: impl Fn(i32) -> bool,
) -> i32 {
    let mut y = spawn_y;
    while !no_collision_no_liquid(y) && y < max_y {
        y += 1;
    }
    y -= 1;
    while no_collision_no_liquid(y) && y > min_y {
        y -= 1;
    }
    y + 1
}

pub fn spawn_block_kind(block: &str) -> SpawnBlockKind {
    match block {
        "minecraft:air" | "minecraft:cave_air" | "minecraft:void_air" => SpawnBlockKind::Air,
        "minecraft:water" | "minecraft:lava" => SpawnBlockKind::Fluid,
        "minecraft:short_grass"
        | "minecraft:tall_grass"
        | "minecraft:snow"
        | "minecraft:fire"
        | "minecraft:soul_fire" => SpawnBlockKind::NonSolid,
        _ => SpawnBlockKind::Solid,
    }
}

pub fn carver_can_reach(
    chunk_mid_x: f64,
    chunk_mid_z: f64,
    x: f64,
    z: f64,
    current_step: i32,
    total_steps: i32,
    thickness: f32,
) -> bool {
    let xd = x - chunk_mid_x;
    let zd = z - chunk_mid_z;
    let remaining = f64::from(total_steps - current_step);
    let rr = f64::from(thickness + 2.0 + 16.0);
    xd * xd + zd * zd - remaining * remaining <= rr * rr
}

// ============================================================================
// NoiseChunk — cell-based trilinear interpolation
//
// Mirrors Java's `NoiseChunk` / `NoiseInterpolator` in
// `net.minecraft.world.level.levelgen.NoiseChunk`.
//
// Overview
// --------
// The overworld divides the world into *cells* (4×4 blocks wide, 8 blocks
// tall by default).  For each Interpolated-marker density function in the
// `final_density` tree, the inner function is sampled at every cell *corner*
// (one call per corner per interpolator).  Inside the cell the sampled corner
// values are trilinearly interpolated, avoiding per-block full noise
// evaluation.
//
// Iteration order matches Java's `doFill` in `NoiseBasedChunkGenerator`:
//
//   for cell_x in 0..cell_count_xz:
//     advance_cell_x(cell_x)          ← fills the next-X slice
//     for cell_z in 0..cell_count_xz:
//       for cell_y in (0..cell_count_y).rev():
//         select_cell_yz(cell_y, cell_z)
//         for y_in_cell in (0..cell_height).rev():
//           update_for_y(…)
//           for x_in_cell in 0..cell_width:
//             update_for_x(…)
//             for z_in_cell in 0..cell_width:
//               update_for_z(…)
//               // read interpolated_density(…)
//     swap_slices()                   ← swap current / next
// ============================================================================

/// Pack a `(block_x, block_z)` pair into a single `i64` key.
///
/// Matches Java `ColumnPos.asLong(blockX, blockZ)`:
/// `(blockX & 0xFFFF_FFFF_L) | ((long) blockZ << 32)`.
fn pack_column(x: i32, z: i32) -> i64 {
    ((x as i64) & 0xFFFF_FFFF) | ((z as i64) << 32)
}

fn density_cache_key(df: &DensityFunction, kind: DensityMarker) -> usize {
    (df as *const DensityFunction as usize) ^ ((kind as usize) << 3)
}

fn density_function_key(df: &DensityFunction) -> usize {
    df as *const DensityFunction as usize
}

fn lookup_density_index(entries: &HashMap<usize, usize>, key: usize) -> Option<usize> {
    entries.get(&key).copied()
}

fn build_density_lookup(inputs: &[&'static DensityFunction]) -> HashMap<usize, usize> {
    inputs
        .iter()
        .enumerate()
        .map(|(i, &fn_ref)| (fn_ref as *const DensityFunction as usize, i))
        .collect()
}

fn collect_marker_inputs(
    df: DensityFunction,
    target: DensityMarker,
    out: &mut Vec<&'static DensityFunction>,
) {
    match df {
        DensityFunction::Marker { kind, input } => {
            if kind == target {
                let ptr = input as *const DensityFunction as usize;
                if !out
                    .iter()
                    .any(|existing| *existing as *const DensityFunction as usize == ptr)
                {
                    out.push(input);
                }
            }
            collect_marker_inputs(*input, target, out);
        }
        DensityFunction::BlendDensity { input }
        | DensityFunction::Clamp { input, .. }
        | DensityFunction::Mapped { input, .. }
        | DensityFunction::WeirdScaledSampler { input, .. } => {
            collect_marker_inputs(*input, target, out);
        }
        DensityFunction::Binary {
            argument1,
            argument2,
            ..
        } => {
            collect_marker_inputs(*argument1, target, out);
            collect_marker_inputs(*argument2, target, out);
        }
        DensityFunction::RangeChoice {
            input,
            when_in_range,
            when_out_of_range,
            ..
        } => {
            collect_marker_inputs(*input, target, out);
            collect_marker_inputs(*when_in_range, target, out);
            collect_marker_inputs(*when_out_of_range, target, out);
        }
        DensityFunction::ShiftedNoise {
            shift_x,
            shift_y,
            shift_z,
            ..
        } => {
            collect_marker_inputs(*shift_x, target, out);
            collect_marker_inputs(*shift_y, target, out);
            collect_marker_inputs(*shift_z, target, out);
        }
        DensityFunction::FindTopSurface {
            density,
            upper_bound,
            ..
        } => {
            collect_marker_inputs(*density, target, out);
            collect_marker_inputs(*upper_bound, target, out);
        }
        DensityFunction::Reference(id) => {
            if let Some(entry) = builtin_density_function(id) {
                collect_marker_inputs(entry.function, target, out);
            }
        }
        _ => {}
    }
}

/// Walk a `DensityFunction` tree depth-first and collect the `&'static`
/// inner functions of every `Marker(Interpolated)` node.
///
/// Duplicates (by pointer identity) are not added twice — this matches Java's
/// `HashMap<DensityFunction, DensityFunction>` deduplication in `NoiseChunk.wrap`.
fn collect_interpolated_inputs(df: DensityFunction, out: &mut Vec<&'static DensityFunction>) {
    collect_marker_inputs(df, DensityMarker::Interpolated, out);
}

#[derive(Clone)]
struct NoiseChunkTemplate {
    interpolated_inputs: Arc<[&'static DensityFunction]>,
    cache_all_inputs: Arc<[&'static DensityFunction]>,
    flat_cache_inputs: Arc<[&'static DensityFunction]>,
    cache_2d_inputs: Arc<[&'static DensityFunction]>,
    cache_once_inputs: Arc<[&'static DensityFunction]>,
    interp_by_ptr: Arc<HashMap<usize, usize>>,
    cache_all_by_ptr: Arc<HashMap<usize, usize>>,
    flat_cache_by_ptr: Arc<HashMap<usize, usize>>,
    cache_2d_by_ptr: Arc<HashMap<usize, usize>>,
    cache_once_by_ptr: Arc<HashMap<usize, usize>>,
}

static NOISE_CHUNK_TEMPLATE_CACHE: OnceLock<Mutex<HashMap<&'static str, NoiseChunkTemplate>>> =
    OnceLock::new();

fn noise_chunk_template(
    settings_id: &'static str,
    noise_router: NoiseRouter,
) -> NoiseChunkTemplate {
    let cache = NOISE_CHUNK_TEMPLATE_CACHE.get_or_init(|| Mutex::new(HashMap::new()));
    if let Ok(cache) = cache.lock() {
        if let Some(template) = cache.get(settings_id) {
            return template.clone();
        }
    }

    let mut interpolated_inputs: Vec<&'static DensityFunction> = Vec::new();
    for function in [
        noise_router.final_density,
        noise_router.vein_toggle,
        noise_router.vein_ridged,
        noise_router.vein_gap,
        noise_router.barrier,
        noise_router.fluid_level_floodedness,
        noise_router.fluid_level_spread,
        noise_router.lava,
        noise_router.erosion,
        noise_router.depth,
        noise_router.preliminary_surface_level,
    ] {
        collect_interpolated_inputs(function, &mut interpolated_inputs);
    }

    let mut cache_all_inputs: Vec<&'static DensityFunction> = Vec::new();
    let mut flat_cache_inputs: Vec<&'static DensityFunction> = Vec::new();
    let mut cache_2d_inputs: Vec<&'static DensityFunction> = Vec::new();
    let mut cache_once_inputs: Vec<&'static DensityFunction> = Vec::new();
    for function in [
        noise_router.final_density,
        noise_router.vein_toggle,
        noise_router.vein_ridged,
        noise_router.vein_gap,
        noise_router.barrier,
        noise_router.fluid_level_floodedness,
        noise_router.fluid_level_spread,
        noise_router.lava,
        noise_router.erosion,
        noise_router.depth,
        noise_router.preliminary_surface_level,
    ] {
        collect_marker_inputs(
            function,
            DensityMarker::CacheAllInCell,
            &mut cache_all_inputs,
        );
        collect_marker_inputs(function, DensityMarker::FlatCache, &mut flat_cache_inputs);
        collect_marker_inputs(function, DensityMarker::Cache2D, &mut cache_2d_inputs);
        collect_marker_inputs(function, DensityMarker::CacheOnce, &mut cache_once_inputs);
    }

    let template = NoiseChunkTemplate {
        interp_by_ptr: Arc::new(build_density_lookup(&interpolated_inputs)),
        cache_all_by_ptr: Arc::new(build_density_lookup(&cache_all_inputs)),
        flat_cache_by_ptr: Arc::new(build_density_lookup(&flat_cache_inputs)),
        cache_2d_by_ptr: Arc::new(build_density_lookup(&cache_2d_inputs)),
        cache_once_by_ptr: Arc::new(build_density_lookup(&cache_once_inputs)),
        interpolated_inputs: Arc::from(interpolated_inputs.into_boxed_slice()),
        cache_all_inputs: Arc::from(cache_all_inputs.into_boxed_slice()),
        flat_cache_inputs: Arc::from(flat_cache_inputs.into_boxed_slice()),
        cache_2d_inputs: Arc::from(cache_2d_inputs.into_boxed_slice()),
        cache_once_inputs: Arc::from(cache_once_inputs.into_boxed_slice()),
    };
    if let Ok(mut cache) = cache.lock() {
        cache.insert(settings_id, template.clone());
    }
    template
}

#[derive(Debug, Clone)]
struct CacheOnceState {
    last_counter: i64,
    last_array_counter: i64,
    last_value: f64,
    last_array: Option<Vec<f64>>,
}

impl Default for CacheOnceState {
    fn default() -> Self {
        Self {
            last_counter: i64::MIN,
            last_array_counter: i64::MIN,
            last_value: 0.0,
            last_array: None,
        }
    }
}

#[derive(Clone, Copy)]
enum DensityArrayFillMode {
    Slice { block_x: i32, block_z: i32 },
    Cell,
}

/// Evaluate a `DensityFunction` tree, substituting interpolated values for
/// every `Marker(Interpolated)` node whose inner function is tracked by the
/// chunk's interpolator table.
///
/// Takes `&NoiseChunk` directly (instead of a pre-built HashMap) to avoid a
/// 98,304-allocation-per-chunk overhead and to correctly handle
/// `DensityFunction::Reference` nodes by following them recursively.
///
/// This mirrors how Java's `NoiseChunk` wraps each density function so that
/// `compute(NoiseChunk.this)` returns the pre-interpolated value.
fn eval_density_fn_with_interp(
    df: DensityFunction,
    chunk: &NoiseChunk,
    x: i32,
    y: i32,
    z: i32,
) -> f64 {
    let seed = chunk.seed;
    let settings = chunk.settings;
    match df {
        DensityFunction::Marker { kind, input } => match kind {
            DensityMarker::Interpolated => {
                let ptr = input as *const DensityFunction as usize;
                if let Some(idx) = lookup_density_index(&chunk.interp_by_ptr, ptr) {
                    // Return the trilinearly-interpolated value cached by the interpolator.
                    chunk.interpolator_value(idx)
                } else {
                    // Not tracked — fall back to point evaluation.
                    input.compute_with_noise(seed, settings, x, y, z)
                }
            }
            DensityMarker::Cache2D => {
                let ptr = input as *const DensityFunction as usize;
                let pos_key = pack_column(x, z);
                if let Some(cache_index) = lookup_density_index(&chunk.cache_2d_by_ptr, ptr) {
                    if let Some(value) = {
                        let cache = chunk.cache_2d.borrow();
                        let state = &cache[cache_index];
                        (state.last_pos_2d == pos_key).then_some(state.last_value)
                    } {
                        return value;
                    }

                    let inner_fn = {
                        let cache = chunk.cache_2d.borrow();
                        cache[cache_index].inner_fn
                    };
                    let value = eval_density_fn_with_interp(*inner_fn, chunk, x, y, z);
                    let mut cache = chunk.cache_2d.borrow_mut();
                    let state = &mut cache[cache_index];
                    state.last_pos_2d = pos_key;
                    state.last_value = value;
                    value
                } else {
                    eval_density_fn_with_interp(*input, chunk, x, y, z)
                }
            }
            DensityMarker::CacheOnce => {
                let ptr = input as *const DensityFunction as usize;
                let Some(cache_index) = lookup_density_index(&chunk.cache_once_by_ptr, ptr) else {
                    chunk
                        .cache_once_scalar_misses
                        .set(chunk.cache_once_scalar_misses.get().saturating_add(1));
                    return eval_density_fn_with_interp(*input, chunk, x, y, z);
                };
                if let Some(value) = {
                    let cache = chunk.cache_once_values.borrow();
                    let state = &cache[cache_index];
                    if state.last_array_counter == chunk.array_interpolation_counter {
                        state
                            .last_array
                            .as_ref()
                            .and_then(|array| array.get(chunk.array_index).copied())
                    } else if state.last_counter == chunk.interpolation_counter {
                        Some(state.last_value)
                    } else {
                        None
                    }
                } {
                    chunk
                        .cache_once_scalar_hits
                        .set(chunk.cache_once_scalar_hits.get().saturating_add(1));
                    return value;
                }
                chunk
                    .cache_once_scalar_misses
                    .set(chunk.cache_once_scalar_misses.get().saturating_add(1));
                let value = eval_density_fn_with_interp(*input, chunk, x, y, z);
                {
                    let mut cache = chunk.cache_once_values.borrow_mut();
                    let state = &mut cache[cache_index];
                    state.last_counter = chunk.interpolation_counter;
                    state.last_value = value;
                }
                value
            }
            DensityMarker::FlatCache => {
                let ptr = input as *const DensityFunction as usize;
                if let Some(cache_index) = lookup_density_index(&chunk.flat_cache_by_ptr, ptr) {
                    let cache = &chunk.flat_cache[cache_index];
                    let quart_x = x >> 2;
                    let quart_z = z >> 2;
                    let local_x = quart_x - (chunk.first_cell_x * chunk.cell_width >> 2);
                    let local_z = quart_z - (chunk.first_cell_z * chunk.cell_width >> 2);
                    if local_x >= 0
                        && local_z >= 0
                        && (local_x as usize) < cache.size_xz
                        && (local_z as usize) < cache.size_xz
                    {
                        return cache.values[local_x as usize + local_z as usize * cache.size_xz];
                    }
                    return eval_density_fn_with_interp(*cache.inner_fn, chunk, x, y, z);
                }
                eval_density_fn_with_interp(*input, chunk, x, y, z)
            }
            DensityMarker::CacheAllInCell => {
                if !chunk.filling_cell_cache.get() {
                    let ptr = input as *const DensityFunction as usize;
                    if let (Some(cache_index), Some(value_index)) = (
                        lookup_density_index(&chunk.cache_all_by_ptr, ptr),
                        chunk.cache_all_cell_index(),
                    ) {
                        if let Some(value) =
                            chunk.cache_all_in_cell[cache_index].values.get(value_index)
                        {
                            return *value;
                        }
                    }
                }
                eval_density_fn_with_interp(*input, chunk, x, y, z)
            }
        },
        // Follow references into the built-in density function registry.
        // This is critical: the overworld's final_density IS a Reference node,
        // so without this arm the entire interpolation system is bypassed.
        DensityFunction::Reference(id) => {
            if let Some(entry) = builtin_density_function(id) {
                eval_density_fn_with_interp(entry.function, chunk, x, y, z)
            } else {
                0.0
            }
        }
        DensityFunction::BlendDensity { input } => {
            eval_density_fn_with_interp(*input, chunk, x, y, z)
        }
        DensityFunction::Clamp { input, min, max } => {
            eval_density_fn_with_interp(*input, chunk, x, y, z).clamp(min, max)
        }
        DensityFunction::Mapped { kind, input } => {
            kind.transform(eval_density_fn_with_interp(*input, chunk, x, y, z))
        }
        DensityFunction::Binary {
            kind,
            argument1,
            argument2,
        } => {
            let first = eval_density_fn_with_interp(*argument1, chunk, x, y, z);
            let second_bounds = chunk.density_value_bounds(argument2);
            kind.apply_lazy(first, second_bounds, || {
                eval_density_fn_with_interp(*argument2, chunk, x, y, z)
            })
        }
        DensityFunction::RangeChoice {
            input,
            min_inclusive,
            max_exclusive,
            when_in_range,
            when_out_of_range,
        } => {
            let v = eval_density_fn_with_interp(*input, chunk, x, y, z);
            if v >= min_inclusive && v < max_exclusive {
                eval_density_fn_with_interp(*when_in_range, chunk, x, y, z)
            } else {
                eval_density_fn_with_interp(*when_out_of_range, chunk, x, y, z)
            }
        }
        DensityFunction::Spline { kind } => {
            chunk.terrain_spline_value(kind, terrain_spline_context(seed, settings, x, y, z))
        }
        DensityFunction::Noise {
            noise,
            xz_scale,
            y_scale,
        } => chunk.normal_noise_sample(
            noise,
            f64::from(x) * xz_scale,
            f64::from(y) * y_scale,
            f64::from(z) * xz_scale,
        ),
        DensityFunction::ShiftA { noise } => {
            chunk.normal_noise_sample(noise, f64::from(x) * 0.25, 0.0, f64::from(z) * 0.25) * 4.0
        }
        DensityFunction::ShiftB { noise } => {
            chunk.normal_noise_sample(noise, f64::from(z) * 0.25, f64::from(x) * 0.25, 0.0) * 4.0
        }
        DensityFunction::Shift { noise } => {
            chunk.normal_noise_sample(
                noise,
                f64::from(x) * 0.25,
                f64::from(y) * 0.25,
                f64::from(z) * 0.25,
            ) * 4.0
        }
        DensityFunction::ShiftedNoise {
            shift_x,
            shift_y,
            shift_z,
            xz_scale,
            y_scale,
            noise,
        } => {
            let sample_x =
                f64::from(x) * xz_scale + eval_density_fn_with_interp(*shift_x, chunk, x, y, z);
            let sample_y =
                f64::from(y) * y_scale + eval_density_fn_with_interp(*shift_y, chunk, x, y, z);
            let sample_z =
                f64::from(z) * xz_scale + eval_density_fn_with_interp(*shift_z, chunk, x, y, z);
            chunk.normal_noise_sample(noise, sample_x, sample_y, sample_z)
        }
        DensityFunction::BlendedNoise {
            xz_scale,
            y_scale,
            xz_factor,
            y_factor,
            smear_scale_multiplier,
        } => chunk.blended_noise_sample(
            xz_scale,
            y_scale,
            xz_factor,
            y_factor,
            smear_scale_multiplier,
            f64::from(x),
            f64::from(y),
            f64::from(z),
        ),
        DensityFunction::WeirdScaledSampler {
            input,
            noise,
            rarity_mapper,
        } => {
            let input_value = eval_density_fn_with_interp(*input, chunk, x, y, z);
            weird_scaled_sampler_value(chunk, noise, rarity_mapper, x, y, z, input_value)
        }
        // All remaining variants have no children containing Interpolated markers
        // (or are already fully evaluated at slice-fill time): delegate to
        // compute_with_noise for correctness.
        other => other.compute_with_noise(seed, settings, x, y, z),
    }
}

fn weird_scaled_sampler_value(
    chunk: &NoiseChunk,
    noise: &'static str,
    rarity_mapper: RarityValueMapper,
    block_x: i32,
    block_y: i32,
    block_z: i32,
    input_value: f64,
) -> f64 {
    let rarity = rarity_mapper.map_value(input_value);
    rarity
        * chunk
            .normal_noise_sample(
                noise,
                f64::from(block_x) / rarity,
                f64::from(block_y) / rarity,
                f64::from(block_z) / rarity,
            )
            .abs()
}

fn eval_density_fn_single_point(
    df: DensityFunction,
    chunk: &NoiseChunk,
    x: i32,
    y: i32,
    z: i32,
) -> f64 {
    match df {
        DensityFunction::Reference(id) => builtin_density_function(id)
            .map(|entry| eval_density_fn_single_point(entry.function, chunk, x, y, z))
            .unwrap_or(0.0),
        DensityFunction::Marker { kind, input } => match kind {
            DensityMarker::FlatCache => {
                let ptr = input as *const DensityFunction as usize;
                if let Some(cache_index) = lookup_density_index(&chunk.flat_cache_by_ptr, ptr) {
                    let cache = &chunk.flat_cache[cache_index];
                    let quart_x = x >> 2;
                    let quart_z = z >> 2;
                    let local_x = quart_x - (chunk.first_cell_x * chunk.cell_width >> 2);
                    let local_z = quart_z - (chunk.first_cell_z * chunk.cell_width >> 2);
                    if local_x >= 0
                        && local_z >= 0
                        && (local_x as usize) < cache.size_xz
                        && (local_z as usize) < cache.size_xz
                    {
                        return cache.values[local_x as usize + local_z as usize * cache.size_xz];
                    }
                }
                eval_density_fn_single_point(*input, chunk, x, y, z)
            }
            DensityMarker::Cache2D => {
                let ptr = input as *const DensityFunction as usize;
                let pos_key = pack_column(x, z);
                if let Some(cache_index) = lookup_density_index(&chunk.cache_2d_by_ptr, ptr) {
                    if let Some(value) = {
                        let cache = chunk.cache_2d.borrow();
                        let state = &cache[cache_index];
                        (state.last_pos_2d == pos_key).then_some(state.last_value)
                    } {
                        return value;
                    }

                    let inner_fn = {
                        let cache = chunk.cache_2d.borrow();
                        cache[cache_index].inner_fn
                    };
                    let value = eval_density_fn_single_point(*inner_fn, chunk, x, y, z);
                    let mut cache = chunk.cache_2d.borrow_mut();
                    let state = &mut cache[cache_index];
                    state.last_pos_2d = pos_key;
                    state.last_value = value;
                    value
                } else {
                    eval_density_fn_single_point(*input, chunk, x, y, z)
                }
            }
            DensityMarker::Interpolated
            | DensityMarker::CacheOnce
            | DensityMarker::CacheAllInCell => eval_density_fn_single_point(*input, chunk, x, y, z),
        },
        DensityFunction::BlendDensity { input } => {
            eval_density_fn_single_point(*input, chunk, x, y, z)
        }
        DensityFunction::Clamp { input, min, max } => {
            eval_density_fn_single_point(*input, chunk, x, y, z).clamp(min, max)
        }
        DensityFunction::Mapped { kind, input } => {
            kind.transform(eval_density_fn_single_point(*input, chunk, x, y, z))
        }
        DensityFunction::Binary {
            kind,
            argument1,
            argument2,
        } => {
            let first = eval_density_fn_single_point(*argument1, chunk, x, y, z);
            let second_bounds = chunk.density_value_bounds(argument2);
            kind.apply_lazy(first, second_bounds, || {
                eval_density_fn_single_point(*argument2, chunk, x, y, z)
            })
        }
        DensityFunction::RangeChoice {
            input,
            min_inclusive,
            max_exclusive,
            when_in_range,
            when_out_of_range,
        } => {
            let value = eval_density_fn_single_point(*input, chunk, x, y, z);
            if value >= min_inclusive && value < max_exclusive {
                eval_density_fn_single_point(*when_in_range, chunk, x, y, z)
            } else {
                eval_density_fn_single_point(*when_out_of_range, chunk, x, y, z)
            }
        }
        DensityFunction::Spline { kind } => chunk.terrain_spline_value(
            kind,
            terrain_spline_context(chunk.seed, chunk.settings, x, y, z),
        ),
        DensityFunction::Noise {
            noise,
            xz_scale,
            y_scale,
        } => chunk.normal_noise_sample(
            noise,
            f64::from(x) * xz_scale,
            f64::from(y) * y_scale,
            f64::from(z) * xz_scale,
        ),
        DensityFunction::ShiftA { noise } => {
            chunk.normal_noise_sample(noise, f64::from(x) * 0.25, 0.0, f64::from(z) * 0.25) * 4.0
        }
        DensityFunction::ShiftB { noise } => {
            chunk.normal_noise_sample(noise, f64::from(z) * 0.25, f64::from(x) * 0.25, 0.0) * 4.0
        }
        DensityFunction::Shift { noise } => {
            chunk.normal_noise_sample(
                noise,
                f64::from(x) * 0.25,
                f64::from(y) * 0.25,
                f64::from(z) * 0.25,
            ) * 4.0
        }
        DensityFunction::ShiftedNoise {
            shift_x,
            shift_y,
            shift_z,
            xz_scale,
            y_scale,
            noise,
        } => {
            let sample_x =
                f64::from(x) * xz_scale + eval_density_fn_single_point(*shift_x, chunk, x, y, z);
            let sample_y =
                f64::from(y) * y_scale + eval_density_fn_single_point(*shift_y, chunk, x, y, z);
            let sample_z =
                f64::from(z) * xz_scale + eval_density_fn_single_point(*shift_z, chunk, x, y, z);
            chunk.normal_noise_sample(noise, sample_x, sample_y, sample_z)
        }
        DensityFunction::BlendedNoise {
            xz_scale,
            y_scale,
            xz_factor,
            y_factor,
            smear_scale_multiplier,
        } => chunk.blended_noise_sample(
            xz_scale,
            y_scale,
            xz_factor,
            y_factor,
            smear_scale_multiplier,
            f64::from(x),
            f64::from(y),
            f64::from(z),
        ),
        DensityFunction::WeirdScaledSampler {
            input,
            noise,
            rarity_mapper,
        } => {
            let input_value = eval_density_fn_single_point(*input, chunk, x, y, z);
            weird_scaled_sampler_value(chunk, noise, rarity_mapper, x, y, z, input_value)
        }
        DensityFunction::FindTopSurface {
            density,
            upper_bound,
            lower_bound,
            cell_height,
        } => find_top_surface_compute(
            |sample_y| eval_density_fn_single_point(*density, chunk, x, sample_y, z),
            eval_density_fn_single_point(*upper_bound, chunk, x, y, z),
            lower_bound,
            cell_height,
        ),
        DensityFunction::Constant(value) => value,
        DensityFunction::YClampedGradient { .. } => df.compute(y),
        DensityFunction::BlendAlpha => 1.0,
        DensityFunction::BlendOffset | DensityFunction::Beardifier => 0.0,
        DensityFunction::EndIslands {
            seed: function_seed,
        } => end_island_density_sample(
            if function_seed == 0 {
                chunk.seed
            } else {
                function_seed
            },
            x,
            z,
        ),
    }
}

fn fill_density_array_with_interp(
    df: DensityFunction,
    chunk: &mut NoiseChunk,
    output: &mut [f64],
    mode: DensityArrayFillMode,
) {
    match df {
        DensityFunction::Reference(id) => {
            if let Some(entry) = builtin_density_function(id) {
                fill_density_array_with_interp(entry.function, chunk, output, mode);
            } else {
                output.fill(0.0);
            }
        }
        DensityFunction::Marker { kind, input } => match kind {
            DensityMarker::CacheOnce => {
                let ptr = input as *const DensityFunction as usize;
                let Some(cache_index) = lookup_density_index(&chunk.cache_once_by_ptr, ptr) else {
                    chunk
                        .cache_once_array_misses
                        .set(chunk.cache_once_array_misses.get().saturating_add(1));
                    fill_density_array_with_interp(*input, chunk, output, mode);
                    return;
                };
                let copied_cached_array = {
                    let cache = chunk.cache_once_values.borrow();
                    let state = &cache[cache_index];
                    if let Some(array) = (state.last_array_counter
                        == chunk.array_interpolation_counter)
                        .then_some(state.last_array.as_deref())
                        .flatten()
                        .filter(|array| array.len() == output.len())
                    {
                        output.copy_from_slice(array);
                        true
                    } else {
                        false
                    }
                };
                if copied_cached_array {
                    chunk
                        .cache_once_array_hits
                        .set(chunk.cache_once_array_hits.get().saturating_add(1));
                    return;
                }

                chunk
                    .cache_once_array_misses
                    .set(chunk.cache_once_array_misses.get().saturating_add(1));
                fill_density_array_with_interp(*input, chunk, output, mode);

                let mut cache = chunk.cache_once_values.borrow_mut();
                let state = &mut cache[cache_index];
                state.last_array_counter = chunk.array_interpolation_counter;
                if let Some(array) = state
                    .last_array
                    .as_mut()
                    .filter(|array| array.len() == output.len())
                {
                    array.copy_from_slice(output);
                } else {
                    state.last_array = Some(output.to_vec());
                }
            }
            DensityMarker::Interpolated => {
                match mode {
                    // While building an interpolator's corner slices, evaluate the wrapped
                    // function directly at the cell corners. Once a block-cell cache is being
                    // populated, the interpolators have already selected their current cell, so
                    // sampling the marker itself preserves Java's trilinear interpolation.
                    DensityArrayFillMode::Slice { .. } => {
                        fill_density_array_with_interp(*input, chunk, output, mode);
                    }
                    DensityArrayFillMode::Cell => {
                        fill_density_array_direct(df, chunk, output, mode);
                    }
                }
            }
            DensityMarker::CacheAllInCell => {
                if !chunk.filling_cell_cache.get() {
                    let ptr = input as *const DensityFunction as usize;
                    if let Some(cache_index) = lookup_density_index(&chunk.cache_all_by_ptr, ptr) {
                        if chunk.cache_all_in_cell[cache_index].values.len() == output.len() {
                            output.copy_from_slice(&chunk.cache_all_in_cell[cache_index].values);
                            return;
                        }
                    }
                }
                fill_density_array_with_interp(*input, chunk, output, mode);
            }
            DensityMarker::Cache2D => {
                fill_density_array_with_interp(*input, chunk, output, mode);
            }
            DensityMarker::FlatCache => {
                fill_density_array_direct(df, chunk, output, mode);
            }
        },
        DensityFunction::BlendDensity { input } => {
            fill_density_array_with_interp(*input, chunk, output, mode);
        }
        DensityFunction::Clamp { input, min, max } => {
            fill_density_array_with_interp(*input, chunk, output, mode);
            for value in output {
                *value = value.clamp(min, max);
            }
        }
        DensityFunction::Mapped { kind, input } => {
            fill_density_array_with_interp(*input, chunk, output, mode);
            for value in output {
                *value = kind.transform(*value);
            }
        }
        DensityFunction::Binary {
            kind,
            argument1,
            argument2,
        } => {
            fill_density_array_with_interp(*argument1, chunk, output, mode);
            match kind {
                BinaryDensityFunction::Add => {
                    let mut second = chunk.take_density_array_scratch(output.len());
                    fill_density_array_with_interp(*argument2, chunk, &mut second, mode);
                    for (value, second) in output.iter_mut().zip(second.iter()) {
                        *value += *second;
                    }
                    chunk.return_density_array_scratch(second);
                }
                BinaryDensityFunction::Mul => {
                    for (index, value) in output.iter_mut().enumerate() {
                        if *value == 0.0 {
                            continue;
                        }
                        let (pos_x, pos_y, pos_z) =
                            prepare_density_array_context(chunk, mode, index);
                        *value *=
                            eval_density_fn_with_interp(*argument2, chunk, pos_x, pos_y, pos_z);
                    }
                }
                BinaryDensityFunction::Min => {
                    let second_min = chunk.density_value_bounds(argument2).0;
                    for (index, value) in output.iter_mut().enumerate() {
                        if *value < second_min {
                            continue;
                        }
                        let (pos_x, pos_y, pos_z) =
                            prepare_density_array_context(chunk, mode, index);
                        *value = value.min(eval_density_fn_with_interp(
                            *argument2, chunk, pos_x, pos_y, pos_z,
                        ));
                    }
                }
                BinaryDensityFunction::Max => {
                    let second_max = chunk.density_value_bounds(argument2).1;
                    for (index, value) in output.iter_mut().enumerate() {
                        if *value > second_max {
                            continue;
                        }
                        let (pos_x, pos_y, pos_z) =
                            prepare_density_array_context(chunk, mode, index);
                        *value = value.max(eval_density_fn_with_interp(
                            *argument2, chunk, pos_x, pos_y, pos_z,
                        ));
                    }
                }
            }
        }
        DensityFunction::RangeChoice {
            input,
            min_inclusive,
            max_exclusive,
            when_in_range,
            when_out_of_range,
        } => {
            let mut selector = chunk.take_density_array_scratch(output.len());
            fill_density_array_with_interp(*input, chunk, &mut selector, mode);
            for index in 0..output.len() {
                let (pos_x, pos_y, pos_z) = prepare_density_array_context(chunk, mode, index);
                output[index] =
                    if selector[index] >= min_inclusive && selector[index] < max_exclusive {
                        eval_density_fn_with_interp(*when_in_range, chunk, pos_x, pos_y, pos_z)
                    } else {
                        eval_density_fn_with_interp(*when_out_of_range, chunk, pos_x, pos_y, pos_z)
                    };
            }
            chunk.return_density_array_scratch(selector);
        }
        DensityFunction::ShiftedNoise { .. } => {
            fill_density_array_direct(df, chunk, output, mode);
        }
        DensityFunction::WeirdScaledSampler {
            input,
            noise,
            rarity_mapper,
        } => {
            fill_density_array_with_interp(*input, chunk, output, mode);
            for index in 0..output.len() {
                let input_value = output[index];
                let (pos_x, pos_y, pos_z) = prepare_density_array_context(chunk, mode, index);
                output[index] = weird_scaled_sampler_value(
                    chunk,
                    noise,
                    rarity_mapper,
                    pos_x,
                    pos_y,
                    pos_z,
                    input_value,
                );
            }
        }
        DensityFunction::FindTopSurface { .. } => {
            fill_density_array_direct(df, chunk, output, mode);
        }
        DensityFunction::Constant(value) => output.fill(value),
        DensityFunction::BlendAlpha => output.fill(1.0),
        DensityFunction::BlendOffset | DensityFunction::Beardifier => output.fill(0.0),
        DensityFunction::YClampedGradient { .. }
        | DensityFunction::Noise { .. }
        | DensityFunction::ShiftA { .. }
        | DensityFunction::ShiftB { .. }
        | DensityFunction::Shift { .. }
        | DensityFunction::BlendedNoise { .. }
        | DensityFunction::EndIslands { .. }
        | DensityFunction::Spline { .. } => {
            fill_density_array_direct(df, chunk, output, mode);
        }
    }
}

fn prepare_density_array_context(
    chunk: &mut NoiseChunk,
    mode: DensityArrayFillMode,
    index: usize,
) -> (i32, i32, i32) {
    match mode {
        DensityArrayFillMode::Slice { block_x, block_z } => {
            let block_y = (chunk.cell_noise_min_y + index as i32) * chunk.cell_height;
            chunk.cell_start_block_x = block_x;
            chunk.cell_start_block_y = block_y;
            chunk.cell_start_block_z = block_z;
            chunk.interpolation_counter += 1;
            chunk.in_cell_x = 0;
            chunk.in_cell_y = 0;
            chunk.in_cell_z = 0;
            chunk.array_index = index;
            (block_x, block_y, block_z)
        }
        DensityArrayFillMode::Cell => {
            let cell_width = chunk.cell_width as usize;
            let y_stride = cell_width * cell_width;
            let y_from_top = index / y_stride;
            let xz_index = index % y_stride;
            let x_in_cell = xz_index / cell_width;
            let z_in_cell = xz_index % cell_width;
            let y_in_cell = chunk.cell_height - 1 - y_from_top as i32;
            chunk.in_cell_x = x_in_cell as i32;
            chunk.in_cell_y = y_in_cell;
            chunk.in_cell_z = z_in_cell as i32;
            chunk.array_index = index;
            (
                chunk.cell_start_block_x + chunk.in_cell_x,
                chunk.cell_start_block_y + chunk.in_cell_y,
                chunk.cell_start_block_z + chunk.in_cell_z,
            )
        }
    }
}

fn fill_density_array_direct(
    df: DensityFunction,
    chunk: &mut NoiseChunk,
    output: &mut [f64],
    mode: DensityArrayFillMode,
) {
    match mode {
        DensityArrayFillMode::Slice { block_x, block_z } => {
            for (cell_y_index, value) in output.iter_mut().enumerate() {
                let block_y = (chunk.cell_noise_min_y + cell_y_index as i32) * chunk.cell_height;
                chunk.cell_start_block_x = block_x;
                chunk.cell_start_block_y = block_y;
                chunk.cell_start_block_z = block_z;
                chunk.interpolation_counter += 1;
                chunk.in_cell_x = 0;
                chunk.in_cell_y = 0;
                chunk.in_cell_z = 0;
                chunk.array_index = cell_y_index;
                *value = eval_density_fn_with_interp(df, chunk, block_x, block_y, block_z);
            }
        }
        DensityArrayFillMode::Cell => {
            chunk.array_index = 0;
            for y_in_cell in (0..chunk.cell_height).rev() {
                chunk.in_cell_y = y_in_cell;
                let pos_y = chunk.cell_start_block_y + y_in_cell;
                for x_in_cell in 0..chunk.cell_width {
                    chunk.in_cell_x = x_in_cell;
                    let pos_x = chunk.cell_start_block_x + x_in_cell;
                    for z_in_cell in 0..chunk.cell_width {
                        chunk.in_cell_z = z_in_cell;
                        let pos_z = chunk.cell_start_block_z + z_in_cell;
                        output[chunk.array_index] =
                            eval_density_fn_with_interp(df, chunk, pos_x, pos_y, pos_z);
                        chunk.array_index += 1;
                    }
                }
            }
        }
    }
}

// ── NoiseInterpolatorState ────────────────────────────────────────────────────

/// Per-density-function trilinear interpolator.
///
/// Mirrors Java's `NoiseChunk.NoiseInterpolator`.
///
/// Two "slice" arrays (`slice0` / `slice1`) hold sampled corner values along
/// the current and next X-cell-column respectively.  Each slice is indexed as
/// `slice[z_corner][y_corner]` where both indices run from `0` to `cell_count`
/// (inclusive).
///
/// During block iteration the 8 cell-corner values are loaded by
/// `select_cell_yz`, then the Y/X/Z lerp steps update partial accumulators
/// until `value` holds the fully-interpolated density.
struct NoiseInterpolatorState {
    /// The inner density function that is sampled at cell corners.
    inner_fn: &'static DensityFunction,
    /// `slice0[z_idx][y_idx]`: corner values for the *current* X cell column.
    slice0: Vec<Vec<f64>>,
    /// `slice1[z_idx][y_idx]`: corner values for the *next* X cell column.
    slice1: Vec<Vec<f64>>,
    // Eight cell-corner values (populated by `select_cell_yz`).
    // Naming: noise_XYZ where X/Y/Z = 0 (current cell edge) or 1 (next edge).
    noise000: f64,
    noise001: f64,
    noise100: f64,
    noise101: f64,
    noise010: f64,
    noise011: f64,
    noise110: f64,
    noise111: f64,
    // Partial lerp accumulators — written by update_for_y / update_for_x.
    value_xz00: f64,
    value_xz10: f64,
    value_xz01: f64,
    value_xz11: f64,
    value_z0: f64,
    value_z1: f64,
    /// Fully-interpolated value for the current block position (written by
    /// `update_for_z`).
    value: f64,
}

impl NoiseInterpolatorState {
    fn new(cell_count_y: usize, cell_count_xz: usize, inner_fn: &'static DensityFunction) -> Self {
        let sz = cell_count_xz + 1; // z corners
        let sy = cell_count_y + 1; // y corners
        Self {
            inner_fn,
            slice0: (0..sz).map(|_| vec![0.0; sy]).collect(),
            slice1: (0..sz).map(|_| vec![0.0; sy]).collect(),
            noise000: 0.0,
            noise001: 0.0,
            noise100: 0.0,
            noise101: 0.0,
            noise010: 0.0,
            noise011: 0.0,
            noise110: 0.0,
            noise111: 0.0,
            value_xz00: 0.0,
            value_xz10: 0.0,
            value_xz01: 0.0,
            value_xz11: 0.0,
            value_z0: 0.0,
            value_z1: 0.0,
            value: 0.0,
        }
    }

    /// Evaluate `inner_fn` at every (Z, Y) cell-corner for the given X
    /// cell-column and store the results into either `slice0` or `slice1`.
    ///
    /// Mirrors Java's `NoiseChunk.fillSlice` / `NoiseInterpolator.fillArray`.
    fn fill_slice(
        &mut self,
        use_slice0: bool,
        block_x: i32,
        cell_count_y: i32,
        cell_noise_min_y: i32,
        cell_height: i32,
        first_cell_z: i32,
        cell_count_xz: i32,
        cell_width: i32,
        seed: i64,
        settings: NoiseGeneratorSettings,
    ) {
        let slice = if use_slice0 {
            &mut self.slice0
        } else {
            &mut self.slice1
        };
        for z_idx in 0..=(cell_count_xz as usize) {
            let block_z = (first_cell_z + z_idx as i32) * cell_width;
            for y_idx in 0..=(cell_count_y as usize) {
                // The Y corner corresponds to block_y = (cell_noise_min_y + y_idx) * cell_height.
                // Java iterates y from 0 to cellCountY (inclusive) with inCellY = 0 and
                // cellStartBlockY = (y_idx + cellNoiseMinY) * cellHeight — exactly this.
                let block_y = (cell_noise_min_y + y_idx as i32) * cell_height;
                slice[z_idx][y_idx] = self
                    .inner_fn
                    .compute_with_noise(seed, settings, block_x, block_y, block_z);
            }
        }
    }

    /// Load the 8 corner values for the cell at `(cell_y_idx, cell_z_idx)`.
    ///
    /// Mirrors Java `NoiseInterpolator.selectCellYZ`.
    fn select_cell_yz(&mut self, cell_y_idx: usize, cell_z_idx: usize) {
        self.noise000 = self.slice0[cell_z_idx][cell_y_idx];
        self.noise001 = self.slice0[cell_z_idx + 1][cell_y_idx];
        self.noise100 = self.slice1[cell_z_idx][cell_y_idx];
        self.noise101 = self.slice1[cell_z_idx + 1][cell_y_idx];
        self.noise010 = self.slice0[cell_z_idx][cell_y_idx + 1];
        self.noise011 = self.slice0[cell_z_idx + 1][cell_y_idx + 1];
        self.noise110 = self.slice1[cell_z_idx][cell_y_idx + 1];
        self.noise111 = self.slice1[cell_z_idx + 1][cell_y_idx + 1];
    }

    /// Lerp along Y: populate `value_xz*` from the 8 corner values.
    ///
    /// `factor_y` is `y_in_cell / cell_height` (0.0 at bottom of cell → 1.0 at top).
    ///
    /// Mirrors Java `NoiseInterpolator.updateForY`.
    fn update_for_y(&mut self, factor_y: f64) {
        self.value_xz00 = lerp(factor_y, self.noise000, self.noise010);
        self.value_xz10 = lerp(factor_y, self.noise100, self.noise110);
        self.value_xz01 = lerp(factor_y, self.noise001, self.noise011);
        self.value_xz11 = lerp(factor_y, self.noise101, self.noise111);
    }

    /// Lerp along X: populate `value_z*` from `value_xz*`.
    ///
    /// `factor_x` is `x_in_cell / cell_width`.
    ///
    /// Mirrors Java `NoiseInterpolator.updateForX`.
    fn update_for_x(&mut self, factor_x: f64) {
        self.value_z0 = lerp(factor_x, self.value_xz00, self.value_xz10);
        self.value_z1 = lerp(factor_x, self.value_xz01, self.value_xz11);
    }

    /// Lerp along Z: write the fully-interpolated `value`.
    ///
    /// `factor_z` is `z_in_cell / cell_width`.
    ///
    /// Mirrors Java `NoiseInterpolator.updateForZ`.
    fn update_for_z(&mut self, factor_z: f64) {
        self.value = lerp(factor_z, self.value_z0, self.value_z1);
    }

    /// Swap `slice0` and `slice1` so that the previously-filled "next" slice
    /// becomes the "current" slice at the start of the next X-cell-column.
    ///
    /// Mirrors Java `NoiseInterpolator.swapSlices`.
    fn swap_slices(&mut self) {
        std::mem::swap(&mut self.slice0, &mut self.slice1);
    }
}

struct CacheAllInCellState {
    inner_fn: &'static DensityFunction,
    values: Vec<f64>,
}

impl CacheAllInCellState {
    fn new(cell_width: i32, cell_height: i32, inner_fn: &'static DensityFunction) -> Self {
        let len = (cell_width * cell_width * cell_height) as usize;
        Self {
            inner_fn,
            values: vec![0.0; len],
        }
    }
}

struct Cache2DState {
    inner_fn: &'static DensityFunction,
    last_pos_2d: i64,
    last_value: f64,
}

impl Cache2DState {
    fn new(inner_fn: &'static DensityFunction) -> Self {
        Self {
            inner_fn,
            last_pos_2d: i64::MIN,
            last_value: 0.0,
        }
    }
}

struct FlatCacheState {
    inner_fn: &'static DensityFunction,
    values: Vec<f64>,
    size_xz: usize,
}

impl FlatCacheState {
    fn new(
        chunk_min_block_x: i32,
        chunk_min_block_z: i32,
        noise_size_xz: i32,
        seed: i64,
        settings: NoiseGeneratorSettings,
        inner_fn: &'static DensityFunction,
    ) -> Self {
        let size_xz = (noise_size_xz + 1) as usize;
        let first_noise_x = chunk_min_block_x >> 2;
        let first_noise_z = chunk_min_block_z >> 2;
        let mut values = vec![0.0; size_xz * size_xz];
        for x in 0..=noise_size_xz {
            let block_x = (first_noise_x + x) << 2;
            for z in 0..=noise_size_xz {
                let block_z = (first_noise_z + z) << 2;
                values[x as usize + z as usize * size_xz] =
                    inner_fn.compute_with_noise(seed, settings, block_x, 0, block_z);
            }
        }
        Self {
            inner_fn,
            values,
            size_xz,
        }
    }
}

#[derive(Debug, Clone, Copy, Default)]
struct NoiseChunkFillStats {
    full_noise_cache_ms: u128,
    full_noise_cache_us: u128,
    full_noise_cache_fills: usize,
    vein_noise_cache_ms: u128,
    vein_noise_cache_us: u128,
    vein_noise_cache_fills: usize,
    cache_once_scalar_hits: usize,
    cache_once_scalar_misses: usize,
    cache_once_array_hits: usize,
    cache_once_array_misses: usize,
}

// ── NoiseChunk ────────────────────────────────────────────────────────────────

/// Cell-based sampling context for one chunk's noise generation.
///
/// Mirrors Java's `NoiseChunk` (inner interpolation state only; Aquifer and
/// Beardifier are not yet wired).
///
/// The overworld uses 4-wide × 8-tall cells (`cell_width = 4`, `cell_height = 8`).
/// For each X-cell-column, `advance_cell_x` fills the *next* slice, then
/// `swap_slices` promotes it to the *current* slice.  Within each cell, values
/// are trilinearly interpolated by successive calls to `update_for_y`,
/// `update_for_x`, and `update_for_z`.
pub struct NoiseChunk {
    pub cell_width: i32,
    pub cell_height: i32,
    /// Number of cells along X and Z (= 16 / cell_width).
    pub cell_count_xz: i32,
    /// Number of cells along Y (= height / cell_height).
    pub cell_count_y: i32,
    /// Lowest Y cell index (= min_y / cell_height, using floor division).
    pub cell_noise_min_y: i32,
    /// Cell X index of the chunk's west edge.
    pub first_cell_x: i32,
    /// Cell Z index of the chunk's north edge.
    pub first_cell_z: i32,
    /// Quart-block count along XZ within the chunk (= cell_count_xz * cell_width >> 2).
    pub noise_size_xz: i32,

    /// One interpolator per `Interpolated`-marked inner function found in
    /// `final_density`.
    interpolators: Vec<NoiseInterpolatorState>,
    /// Maps inner-function pointer address → `interpolators` index so that
    /// `eval_density_fn_with_interp` can look up the current interpolated value
    /// in O(1).
    interp_by_ptr: Arc<HashMap<usize, usize>>,
    cache_all_in_cell: Vec<CacheAllInCellState>,
    cache_all_by_ptr: Arc<HashMap<usize, usize>>,
    cache_2d: RefCell<Vec<Cache2DState>>,
    cache_2d_by_ptr: Arc<HashMap<usize, usize>>,
    flat_cache: Vec<FlatCacheState>,
    flat_cache_by_ptr: Arc<HashMap<usize, usize>>,
    full_noise_values: Vec<f64>,
    vein_toggle_values: Vec<f64>,
    vein_ridged_values: Vec<f64>,
    vein_gap_values: Vec<f64>,
    vein_toggle_interp_index: Option<usize>,
    vein_a_interp_index: Option<usize>,
    vein_b_interp_index: Option<usize>,

    // Current position tracking (updated during the iteration loops).
    pub cell_start_block_x: i32,
    pub cell_start_block_y: i32,
    pub cell_start_block_z: i32,
    pub in_cell_x: i32,
    pub in_cell_y: i32,
    pub in_cell_z: i32,

    /// `true` while inside the X-cell-column iteration loop.
    interpolating: bool,

    /// Cache of preliminary surface levels, keyed by `pack_column(blockX, blockZ)`.
    prelim_surface_cache: RefCell<HashMap<i64, i32>>,
    cache_once_values: RefCell<Vec<CacheOnceState>>,
    cache_once_by_ptr: Arc<HashMap<usize, usize>>,
    normal_noise_cache: RefCell<HashMap<&'static str, NormalNoiseSnapshot>>,
    blended_noise_cache: RefCell<Vec<([u64; 5], BlendedNoiseSnapshot)>>,
    density_value_bounds_cache: RefCell<HashMap<usize, (f64, f64)>>,
    terrain_spline_cache: RefCell<HashMap<TerrainSplineKind, TerrainCubicSpline>>,
    density_array_scratch: Vec<Vec<f64>>,
    filling_cell_cache: Cell<bool>,
    filling_cell: bool,
    interpolation_counter: i64,
    array_interpolation_counter: i64,
    array_index: usize,
    fill_stats: NoiseChunkFillStats,
    cache_once_scalar_hits: Cell<usize>,
    cache_once_scalar_misses: Cell<usize>,
    cache_once_array_hits: Cell<usize>,
    cache_once_array_misses: Cell<usize>,

    pub seed: i64,
    pub settings: NoiseGeneratorSettings,
    pub noise_router: NoiseRouter,
}

impl NoiseChunk {
    /// Create a new `NoiseChunk` for the chunk whose western-most block column
    /// starts at `(chunk_min_block_x, chunk_min_block_z)`.
    ///
    /// Collects all `Interpolated`-marker inner functions from `final_density`
    /// and pre-fills the first X-slice (the slice for `first_cell_x`).
    ///
    /// Mirrors Java `NoiseChunk.forChunk` / `NoiseChunk.initializeForFirstCellX`.
    pub fn new(
        chunk_min_block_x: i32,
        chunk_min_block_z: i32,
        settings: NoiseGeneratorSettings,
        seed: i64,
        noise_router: NoiseRouter,
    ) -> Self {
        let cell_width = settings.noise.cell_width();
        let cell_height = settings.noise.cell_height();
        let cell_count_xz = 16 / cell_width;
        let cell_count_y = settings.noise.height / cell_height;
        let cell_noise_min_y = settings.noise.min_y.div_euclid(cell_height);
        let first_cell_x = chunk_min_block_x.div_euclid(cell_width);
        let first_cell_z = chunk_min_block_z.div_euclid(cell_width);
        let noise_size_xz = (cell_count_xz * cell_width) >> 2;

        let template = noise_chunk_template(settings.id, noise_router);

        // Allocate one interpolator per unique inner function.
        let interpolators: Vec<NoiseInterpolatorState> = template
            .interpolated_inputs
            .iter()
            .map(|&fn_ref| {
                NoiseInterpolatorState::new(cell_count_y as usize, cell_count_xz as usize, fn_ref)
            })
            .collect();
        let cache_all_in_cell: Vec<CacheAllInCellState> = template
            .cache_all_inputs
            .iter()
            .map(|&fn_ref| CacheAllInCellState::new(cell_width, cell_height, fn_ref))
            .collect();
        let cache_2d: Vec<Cache2DState> = template
            .cache_2d_inputs
            .iter()
            .map(|&fn_ref| Cache2DState::new(fn_ref))
            .collect();
        let cache_once_values: Vec<CacheOnceState> = template
            .cache_once_inputs
            .iter()
            .map(|_| CacheOnceState::default())
            .collect();
        let flat_cache: Vec<FlatCacheState> = template
            .flat_cache_inputs
            .iter()
            .map(|&fn_ref| {
                FlatCacheState::new(
                    chunk_min_block_x,
                    chunk_min_block_z,
                    noise_size_xz,
                    seed,
                    settings,
                    fn_ref,
                )
            })
            .collect();
        let cell_value_count = (cell_width * cell_width * cell_height) as usize;
        let full_noise_values = vec![0.0; cell_value_count];
        let vein_toggle_values = vec![0.0; cell_value_count];
        let vein_ridged_values = vec![0.0; cell_value_count];
        let vein_gap_values = vec![0.0; cell_value_count];

        let lookup_interp = |function: &'static DensityFunction| {
            lookup_density_index(
                &template.interp_by_ptr,
                function as *const DensityFunction as usize,
            )
        };
        let vein_toggle_interp_index = lookup_interp(&OVERWORLD_VEIN_TOGGLE_RANGE_DENSITY);
        let vein_a_interp_index = lookup_interp(&OVERWORLD_VEIN_A_RANGE_DENSITY);
        let vein_b_interp_index = lookup_interp(&OVERWORLD_VEIN_B_RANGE_DENSITY);

        // Fill slice0 for the first cell-X column (mirrors initializeForFirstCellX).
        let mut chunk = Self {
            cell_width,
            cell_height,
            cell_count_xz,
            cell_count_y,
            cell_noise_min_y,
            first_cell_x,
            first_cell_z,
            noise_size_xz,
            interpolators,
            interp_by_ptr: template.interp_by_ptr,
            cache_all_in_cell,
            cache_all_by_ptr: template.cache_all_by_ptr,
            cache_2d: RefCell::new(cache_2d),
            cache_2d_by_ptr: template.cache_2d_by_ptr,
            flat_cache,
            flat_cache_by_ptr: template.flat_cache_by_ptr,
            full_noise_values,
            vein_toggle_values,
            vein_ridged_values,
            vein_gap_values,
            vein_toggle_interp_index,
            vein_a_interp_index,
            vein_b_interp_index,
            cell_start_block_x: first_cell_x * cell_width,
            cell_start_block_y: cell_noise_min_y * cell_height,
            cell_start_block_z: first_cell_z * cell_width,
            in_cell_x: 0,
            in_cell_y: 0,
            in_cell_z: 0,
            interpolating: false,
            prelim_surface_cache: RefCell::new(HashMap::new()),
            cache_once_values: RefCell::new(cache_once_values),
            cache_once_by_ptr: template.cache_once_by_ptr,
            normal_noise_cache: RefCell::new(HashMap::new()),
            blended_noise_cache: RefCell::new(Vec::new()),
            density_value_bounds_cache: RefCell::new(HashMap::new()),
            terrain_spline_cache: RefCell::new(HashMap::new()),
            density_array_scratch: Vec::new(),
            filling_cell_cache: Cell::new(false),
            filling_cell: false,
            interpolation_counter: 0,
            array_interpolation_counter: 0,
            array_index: 0,
            fill_stats: NoiseChunkFillStats::default(),
            cache_once_scalar_hits: Cell::new(0),
            cache_once_scalar_misses: Cell::new(0),
            cache_once_array_hits: Cell::new(0),
            cache_once_array_misses: Cell::new(0),
            seed,
            settings,
            noise_router,
        };

        // Fill slice0 for the first cell-X column (mirrors initializeForFirstCellX).
        chunk.interpolating = true;
        chunk.interpolation_counter = 0;
        chunk.fill_interpolator_slice(true, first_cell_x * cell_width);
        chunk
    }

    /// Fill the *next* X-slice (slice1) for `first_cell_x + cell_x_index + 1`
    /// and set `cell_start_block_x` to the start of the current X-cell-column.
    ///
    /// Mirrors Java `NoiseChunk.advanceCellX`.
    pub fn advance_cell_x(&mut self, cell_x_index: i32) {
        let next_cell_x = self.first_cell_x + cell_x_index + 1;
        let block_x = next_cell_x * self.cell_width;
        self.fill_interpolator_slice(false, block_x);
        self.cell_start_block_x = (self.first_cell_x + cell_x_index) * self.cell_width;
        self.interpolating = true;
    }

    fn fill_interpolator_slice(&mut self, use_slice0: bool, block_x: i32) {
        self.cell_start_block_x = block_x;
        self.in_cell_x = 0;
        for z_idx in 0..=(self.cell_count_xz as usize) {
            let block_z = (self.first_cell_z + z_idx as i32) * self.cell_width;
            self.cell_start_block_z = block_z;
            self.in_cell_z = 0;
            self.array_interpolation_counter += 1;

            for interp_index in 0..self.interpolators.len() {
                let inner_fn = self.interpolators[interp_index].inner_fn;
                let mut row = {
                    let interp = &mut self.interpolators[interp_index];
                    if use_slice0 {
                        std::mem::take(&mut interp.slice0[z_idx])
                    } else {
                        std::mem::take(&mut interp.slice1[z_idx])
                    }
                };
                row.resize((self.cell_count_y + 1) as usize, 0.0);
                fill_density_array_with_interp(
                    *inner_fn,
                    self,
                    &mut row,
                    DensityArrayFillMode::Slice { block_x, block_z },
                );
                let interp = &mut self.interpolators[interp_index];
                if use_slice0 {
                    interp.slice0[z_idx] = row;
                } else {
                    interp.slice1[z_idx] = row;
                }
            }
        }
        self.array_interpolation_counter += 1;
    }

    fn take_density_array_scratch(&mut self, len: usize) -> Vec<f64> {
        let mut scratch = self
            .density_array_scratch
            .pop()
            .unwrap_or_else(|| Vec::with_capacity(len));
        scratch.resize(len, 0.0);
        scratch
    }

    fn return_density_array_scratch(&mut self, mut scratch: Vec<f64>) {
        scratch.clear();
        self.density_array_scratch.push(scratch);
    }

    fn density_value_bounds(&self, function: &'static DensityFunction) -> (f64, f64) {
        let key = density_function_key(function);
        if let Some(bounds) = self.density_value_bounds_cache.borrow().get(&key).copied() {
            return bounds;
        }

        let bounds = function.value_bounds();
        self.density_value_bounds_cache
            .borrow_mut()
            .insert(key, bounds);
        bounds
    }

    fn normal_noise_sample(&self, noise_id: &'static str, x: f64, y: f64, z: f64) -> f64 {
        if !self.normal_noise_cache.borrow().contains_key(noise_id) {
            let Some(snapshot) =
                random_state_normal_noise_snapshot(self.seed, self.settings, noise_id)
            else {
                return 0.0;
            };
            self.normal_noise_cache
                .borrow_mut()
                .insert(noise_id, snapshot);
        }

        self.normal_noise_cache
            .borrow()
            .get(noise_id)
            .map(|snapshot| normal_noise_sample(snapshot, x, y, z))
            .unwrap_or(0.0)
    }

    #[allow(clippy::too_many_arguments)]
    fn blended_noise_sample(
        &self,
        xz_scale: f64,
        y_scale: f64,
        xz_factor: f64,
        y_factor: f64,
        smear_scale_multiplier: f64,
        x: f64,
        y: f64,
        z: f64,
    ) -> f64 {
        let key = [
            xz_scale.to_bits(),
            y_scale.to_bits(),
            xz_factor.to_bits(),
            y_factor.to_bits(),
            smear_scale_multiplier.to_bits(),
        ];
        if !self
            .blended_noise_cache
            .borrow()
            .iter()
            .any(|(cached_key, _)| *cached_key == key)
        {
            let Ok(snapshot) = random_state_blended_noise_snapshot(
                self.seed,
                self.settings,
                xz_scale,
                y_scale,
                xz_factor,
                y_factor,
                smear_scale_multiplier,
            ) else {
                return 0.0;
            };
            self.blended_noise_cache.borrow_mut().push((key, snapshot));
        }

        self.blended_noise_cache
            .borrow()
            .iter()
            .find_map(|(cached_key, snapshot)| {
                (*cached_key == key).then(|| blended_noise_sample(snapshot, x, y, z))
            })
            .unwrap_or(0.0)
    }

    fn terrain_spline_value(&self, kind: TerrainSplineKind, context: TerrainSplineContext) -> f64 {
        if let Some(value) = {
            let cache = self.terrain_spline_cache.borrow();
            cache.get(&kind).map(|spline| spline.apply(context))
        } {
            return value;
        }

        let spline = terrain_spline(kind);
        let value = spline.apply(context);
        self.terrain_spline_cache.borrow_mut().insert(kind, spline);
        value
    }

    fn interpolator_value(&self, interp_index: usize) -> f64 {
        let interp = &self.interpolators[interp_index];
        if self.filling_cell {
            lerp3(
                f64::from(self.in_cell_x) / f64::from(self.cell_width),
                f64::from(self.in_cell_y) / f64::from(self.cell_height),
                f64::from(self.in_cell_z) / f64::from(self.cell_width),
                interp.noise000,
                interp.noise100,
                interp.noise010,
                interp.noise110,
                interp.noise001,
                interp.noise101,
                interp.noise011,
                interp.noise111,
            )
        } else {
            interp.value
        }
    }

    /// Load the 8 corner values for the (Y, Z) cell at `(cell_y_idx, cell_z_idx)`
    /// and set the block-Y/Z start positions.
    ///
    /// Mirrors Java `NoiseChunk.selectCellYZ`.
    pub fn select_cell_yz(&mut self, cell_y_idx: i32, cell_z_idx: i32) {
        for interp in &mut self.interpolators {
            interp.select_cell_yz(cell_y_idx as usize, cell_z_idx as usize);
        }
        self.cell_start_block_y = (self.cell_noise_min_y + cell_y_idx) * self.cell_height;
        self.cell_start_block_z = (self.first_cell_z + cell_z_idx) * self.cell_width;
        self.filling_cell = true;
        self.filling_cell_cache.set(true);
        self.array_interpolation_counter += 1;
        self.fill_cache_all_in_cell();
        self.fill_full_noise_cache();
        self.array_interpolation_counter += 1;
        self.filling_cell_cache.set(false);
        self.filling_cell = false;
    }

    fn cache_all_cell_index(&self) -> Option<usize> {
        let x = self.in_cell_x;
        let y = self.in_cell_y;
        let z = self.in_cell_z;
        (x >= 0
            && y >= 0
            && z >= 0
            && x < self.cell_width
            && y < self.cell_height
            && z < self.cell_width)
            .then_some(
                (((self.cell_height - 1 - y) * self.cell_width + x) * self.cell_width + z) as usize,
            )
    }

    fn fill_cache_all_in_cell(&mut self) {
        if self.cache_all_in_cell.is_empty() {
            return;
        }
        for cache_index in 0..self.cache_all_in_cell.len() {
            let inner_fn = self.cache_all_in_cell[cache_index].inner_fn;
            let mut values = std::mem::take(&mut self.cache_all_in_cell[cache_index].values);
            values.resize(
                (self.cell_width * self.cell_width * self.cell_height) as usize,
                0.0,
            );
            fill_density_array_with_interp(
                *inner_fn,
                self,
                &mut values,
                DensityArrayFillMode::Cell,
            );
            self.cache_all_in_cell[cache_index].values = values;
        }
    }

    fn full_noise_uncached_at(&self, x: i32, y: i32, z: i32) -> f64 {
        eval_density_fn_with_interp(self.noise_router.final_density, self, x, y, z)
            + eval_density_fn_with_interp(DensityFunction::Beardifier, self, x, y, z)
    }

    fn fill_full_noise_cache(&mut self) {
        let started = Instant::now();
        let mut values = std::mem::take(&mut self.full_noise_values);
        values.resize(
            (self.cell_width * self.cell_width * self.cell_height) as usize,
            0.0,
        );
        if !self.fill_overworld_final_density_cache(&mut values) {
            fill_density_array_with_interp(
                self.noise_router.final_density,
                self,
                &mut values,
                DensityArrayFillMode::Cell,
            );
        }
        // RustCraft's current Beardifier is a zero stub; keep this cell cache
        // on the same final-density-only path until structure density is wired.
        self.full_noise_values = values;
        let elapsed = started.elapsed();
        self.fill_stats.full_noise_cache_ms += elapsed.as_millis();
        self.fill_stats.full_noise_cache_us += elapsed.as_micros();
        self.fill_stats.full_noise_cache_fills += 1;
    }

    fn fill_overworld_final_density_cache(&mut self, output: &mut [f64]) -> bool {
        if self.settings.id != "minecraft:overworld"
            || self.noise_router.final_density
                != DensityFunction::Reference("minecraft:overworld/final_density")
        {
            return false;
        }

        let blend_ptr = &OVERWORLD_FINAL_BLEND_DENSITY as *const DensityFunction as usize;
        let Some(blend_interp_index) = lookup_density_index(&self.interp_by_ptr, blend_ptr) else {
            return false;
        };
        let noodle_min = OVERWORLD_CAVES_NOODLE_REFERENCE_DENSITY.value_bounds().0;

        let mut needs_noodle = false;
        self.array_index = 0;
        for y_in_cell in (0..self.cell_height).rev() {
            self.in_cell_y = y_in_cell;
            for x_in_cell in 0..self.cell_width {
                self.in_cell_x = x_in_cell;
                for z_in_cell in 0..self.cell_width {
                    self.in_cell_z = z_in_cell;
                    let post_process = MappedDensityFunction::Squeeze
                        .transform(self.interpolator_value(blend_interp_index) * 0.64);
                    if post_process >= noodle_min {
                        needs_noodle = true;
                    }
                    output[self.array_index] = post_process;
                    self.array_index += 1;
                }
            }
        }
        if needs_noodle {
            let mut noodle = self.take_density_array_scratch(output.len());
            if !self.fill_overworld_noodle_density_cache(&mut noodle) {
                fill_density_array_with_interp(
                    OVERWORLD_CAVES_NOODLE_REFERENCE_DENSITY,
                    self,
                    &mut noodle,
                    DensityArrayFillMode::Cell,
                );
            }
            for (value, noodle_value) in output.iter_mut().zip(noodle.iter()) {
                *value = value.min(*noodle_value);
            }
            self.return_density_array_scratch(noodle);
        }
        true
    }

    fn fill_overworld_noodle_density_cache(&mut self, output: &mut [f64]) -> bool {
        let toggle_ptr = &NOODLE_TOGGLE_RANGE_DENSITY as *const DensityFunction as usize;
        let thickness_ptr = &NOODLE_THICKNESS_RANGE_DENSITY as *const DensityFunction as usize;
        let ridge_a_ptr = &NOODLE_RIDGE_A_RANGE_DENSITY as *const DensityFunction as usize;
        let ridge_b_ptr = &NOODLE_RIDGE_B_RANGE_DENSITY as *const DensityFunction as usize;
        let (Some(toggle_index), Some(thickness_index), Some(ridge_a_index), Some(ridge_b_index)) = (
            lookup_density_index(&self.interp_by_ptr, toggle_ptr),
            lookup_density_index(&self.interp_by_ptr, thickness_ptr),
            lookup_density_index(&self.interp_by_ptr, ridge_a_ptr),
            lookup_density_index(&self.interp_by_ptr, ridge_b_ptr),
        ) else {
            return false;
        };

        self.array_index = 0;
        for y_in_cell in (0..self.cell_height).rev() {
            self.in_cell_y = y_in_cell;
            for x_in_cell in 0..self.cell_width {
                self.in_cell_x = x_in_cell;
                for z_in_cell in 0..self.cell_width {
                    self.in_cell_z = z_in_cell;
                    let toggle = self.interpolator_value(toggle_index);
                    output[self.array_index] = if (-1_000_000.0..0.0).contains(&toggle) {
                        64.0
                    } else {
                        let thickness = self.interpolator_value(thickness_index);
                        let ridge_a = self.interpolator_value(ridge_a_index).abs();
                        let ridge_b = self.interpolator_value(ridge_b_index).abs();
                        thickness + 1.5 * ridge_a.max(ridge_b)
                    };
                    self.array_index += 1;
                }
            }
        }
        true
    }

    fn fill_vein_noise_cache(&mut self) {
        let started = Instant::now();
        let len = (self.cell_width * self.cell_width * self.cell_height) as usize;
        let mut toggle = std::mem::take(&mut self.vein_toggle_values);
        toggle.resize(len, 0.0);
        fill_density_array_with_interp(
            self.noise_router.vein_toggle,
            self,
            &mut toggle,
            DensityArrayFillMode::Cell,
        );
        self.vein_toggle_values = toggle;
        let elapsed = started.elapsed();
        self.fill_stats.vein_noise_cache_ms += elapsed.as_millis();
        self.fill_stats.vein_noise_cache_us += elapsed.as_micros();
        self.fill_stats.vein_noise_cache_fills += 1;
    }

    /// Advance the Y factor and update Y-axis partial lerp values for all
    /// interpolators.
    ///
    /// `factor_y = y_in_cell / cell_height` (Java: `(double)posY / cellHeight`).
    ///
    /// Mirrors Java `NoiseChunk.updateForY`.
    pub fn update_for_y(&mut self, pos_y: i32, factor_y: f64) {
        self.in_cell_y = pos_y - self.cell_start_block_y;
        for interp in &mut self.interpolators {
            interp.update_for_y(factor_y);
        }
    }

    /// Advance the X factor and update X-axis partial lerp values for all
    /// interpolators.
    ///
    /// `factor_x = x_in_cell / cell_width`.
    ///
    /// Mirrors Java `NoiseChunk.updateForX`.
    pub fn update_for_x(&mut self, pos_x: i32, factor_x: f64) {
        self.in_cell_x = pos_x - self.cell_start_block_x;
        for interp in &mut self.interpolators {
            interp.update_for_x(factor_x);
        }
    }

    /// Advance the Z factor and write the fully-interpolated `value` for all
    /// interpolators.
    ///
    /// `factor_z = z_in_cell / cell_width`.
    ///
    /// Mirrors Java `NoiseChunk.updateForZ`.
    pub fn update_for_z(&mut self, pos_z: i32, factor_z: f64) {
        self.in_cell_z = pos_z - self.cell_start_block_z;
        self.interpolation_counter += 1;
        for interp in &mut self.interpolators {
            interp.update_for_z(factor_z);
        }
    }

    /// Swap the current and next X-slices for all interpolators.
    ///
    /// Called once per X-cell-column after all blocks in that column have been
    /// processed.  Mirrors Java `NoiseChunk.swapSlices`.
    pub fn swap_slices(&mut self) {
        for interp in &mut self.interpolators {
            interp.swap_slices();
        }
    }

    /// Return the trilinearly-interpolated final density at the current block
    /// position.
    ///
    /// Walks the `final_density` tree, substituting the current interpolated
    /// value for every `Marker(Interpolated)` node tracked by this chunk.
    /// `DensityFunction::Reference` nodes are followed into the built-in
    /// registry so that the overworld's reference-based final_density is
    /// evaluated correctly.
    ///
    /// If there are no `Interpolated` markers in `final_density` (rare), falls
    /// back to a full point evaluation.
    pub fn interpolated_density(&self, x: i32, y: i32, z: i32) -> f64 {
        if let Some(value_index) = self.cache_all_cell_index() {
            if let Some(value) = self.full_noise_values.get(value_index) {
                return *value;
            }
        }

        self.full_noise_uncached_at(x, y, z)
    }

    fn cached_vein_toggle(&self, x: i32, y: i32, z: i32) -> f64 {
        if self.noise_router.vein_toggle == OVERWORLD_VEIN_TOGGLE_DENSITY {
            if let Some(index) = self.vein_toggle_interp_index {
                return self.interpolator_value(index);
            }
        }
        eval_density_fn_with_interp(self.noise_router.vein_toggle, self, x, y, z)
    }

    fn vein_ridged_at(&self, x: i32, y: i32, z: i32) -> f64 {
        if self.noise_router.vein_ridged == OVERWORLD_VEIN_RIDGED_DENSITY {
            if let (Some(a_index), Some(b_index)) =
                (self.vein_a_interp_index, self.vein_b_interp_index)
            {
                return -0.079_999_998_211_860_66
                    + self
                        .interpolator_value(a_index)
                        .abs()
                        .max(self.interpolator_value(b_index).abs());
            }
        }
        eval_density_fn_with_interp(self.noise_router.vein_ridged, self, x, y, z)
    }

    fn vein_gap_at(&self, x: i32, y: i32, z: i32) -> f64 {
        eval_density_fn_with_interp(self.noise_router.vein_gap, self, x, y, z)
    }

    fn take_fill_stats(&mut self) -> NoiseChunkFillStats {
        let mut stats = self.fill_stats;
        stats.cache_once_scalar_hits = self.cache_once_scalar_hits.replace(0);
        stats.cache_once_scalar_misses = self.cache_once_scalar_misses.replace(0);
        stats.cache_once_array_hits = self.cache_once_array_hits.replace(0);
        stats.cache_once_array_misses = self.cache_once_array_misses.replace(0);
        self.fill_stats = NoiseChunkFillStats::default();
        stats
    }

    /// Compute and cache the preliminary surface level at the given block
    /// column, quantised to the nearest quart-block boundary (matching Java's
    /// `QuartPos.toBlock(QuartPos.fromBlock(x))`).
    ///
    /// Mirrors Java `NoiseChunk.preliminarySurfaceLevel`.
    pub fn preliminary_surface_level(&self, block_x: i32, block_z: i32) -> i32 {
        // Quantise: shift right by 2 then left by 2 (= round down to multiple of 4).
        let qx = (block_x >> 2) << 2;
        let qz = (block_z >> 2) << 2;
        let key = pack_column(qx, qz);
        if let Some(cached) = self.prelim_surface_cache.borrow().get(&key).copied() {
            return cached;
        }
        let value = eval_density_fn_single_point(
            self.noise_router.preliminary_surface_level,
            self,
            qx,
            0,
            qz,
        )
        .floor() as i32;
        self.prelim_surface_cache.borrow_mut().insert(key, value);
        value
    }

    pub fn max_preliminary_surface_level(
        &self,
        min_block_x: i32,
        min_block_z: i32,
        max_block_x: i32,
        max_block_z: i32,
    ) -> i32 {
        let mut max_y = i32::MIN;
        let mut block_z = min_block_z;
        while block_z <= max_block_z {
            let mut block_x = min_block_x;
            while block_x <= max_block_x {
                max_y = max_y.max(self.preliminary_surface_level(block_x, block_z));
                block_x += 4;
            }
            block_z += 4;
        }
        max_y
    }
}

// ── fill_from_noise_chunk ────────────────────────────────────────────────────

/// Fill a chunk's blocks using cell-based trilinear interpolation of the noise
/// density functions.
///
/// Mirrors Java `NoiseBasedChunkGenerator.doFill`.
///
/// When `settings.aquifers_enabled`, block placement uses `NoiseBasedAquifer`
/// (Voronoi cell + barrier noise) for underground fluid pockets.  Otherwise
/// a simplified global-fluid rule is applied (sea-level water, bedrock lava).
///
/// The returned chunk has status `"minecraft:noise"` and contains
/// `WORLD_SURFACE_WG` and `OCEAN_FLOOR_WG` heightmaps.
pub fn fill_from_noise_chunk(
    pos: ChunkPos,
    settings: &NoiseGeneratorSettings,
    seed: i64,
    noise_router: NoiseRouter,
) -> LevelChunk {
    fill_from_noise_chunk_timed(pos, settings, seed, noise_router).0
}

pub fn fill_from_noise_chunk_timed(
    pos: ChunkPos,
    settings: &NoiseGeneratorSettings,
    seed: i64,
    noise_router: NoiseRouter,
) -> (LevelChunk, LiveTerrainTimings) {
    // Activate the thread-local noise-snapshot cache so that Perlin noise tables
    // are initialised once per noise key per chunk, not once per cell-corner
    // evaluation — this makes chunk generation ~1000× faster.
    with_noise_snapshot_cache(|| {
        fill_from_noise_chunk_inner_timed(pos, settings, seed, noise_router)
    })
}

fn fill_from_noise_chunk_inner(
    pos: ChunkPos,
    settings: &NoiseGeneratorSettings,
    seed: i64,
    noise_router: NoiseRouter,
) -> LevelChunk {
    fill_from_noise_chunk_inner_timed(pos, settings, seed, noise_router).0
}

fn fill_from_noise_chunk_inner_timed(
    pos: ChunkPos,
    settings: &NoiseGeneratorSettings,
    seed: i64,
    noise_router: NoiseRouter,
) -> (LevelChunk, LiveTerrainTimings) {
    let (mut chunk, timings, section_blocks, _) =
        fill_from_noise_chunk_inner_sections_timed(pos, settings, seed, noise_router);
    flush_generated_section_blocks(&mut chunk, &section_blocks);
    (chunk, timings)
}

fn fill_from_noise_chunk_inner_sections_timed(
    pos: ChunkPos,
    settings: &NoiseGeneratorSettings,
    seed: i64,
    noise_router: NoiseRouter,
) -> (
    LevelChunk,
    LiveTerrainTimings,
    GeneratedSectionBlocks,
    LiveNoiseGenerationContext,
) {
    let total_started = Instant::now();
    let mut timings = LiveTerrainTimings::default();
    let mut chunk = LevelChunk::empty(pos);
    chunk.status = "minecraft:noise".to_string();

    let min_y = settings.noise.min_y;
    let height = settings.noise.height;
    let section_count = (height + 15) / 16;
    let min_section = min_y.div_euclid(16);
    chunk.min_section_y = min_section;

    let started = Instant::now();
    let mut section_blocks = GeneratedSectionBlocks::new(min_section, section_count);
    // Initialise all chunk sections to air.
    chunk.sections = (0..section_count)
        .map(|i| {
            let section_y = min_section + i;
            let biome = Tag::String("minecraft:plains".to_string());
            ChunkSection {
                y: section_y as i8,
                block_states: PalettedContainer::single(
                    block_state_tag_fast("minecraft:air"),
                    SECTION_VOLUME,
                )
                .to_nbt(),
                biomes: PalettedContainer::single(biome, BIOME_SECTION_VOLUME).to_nbt(),
                block_light: None,
                sky_light: Some(vec![-1i8; 2048]),
            }
        })
        .collect();
    timings.fill_init_sections_ms = started.elapsed().as_millis();

    let chunk_min_x = pos.x * 16;
    let chunk_min_z = pos.z * 16;

    let cell_width = settings.noise.cell_width();
    let cell_height = settings.noise.cell_height();
    let cell_count_xz = 16 / cell_width;
    let cell_count_y = height / cell_height;
    let cell_noise_min_y = min_y.div_euclid(cell_height);

    let started = Instant::now();
    let mut noise_chunk = NoiseChunk::new(chunk_min_x, chunk_min_z, *settings, seed, noise_router);
    timings.fill_noise_chunk_init_ms = started.elapsed().as_millis();
    timings.interpolator_count = noise_chunk.interpolators.len();

    // Create the noise-based aquifer when enabled, or use None for the simple path.
    let algorithm = if settings.legacy_random_source {
        crate::random_source::RandomAlgorithm::Legacy
    } else {
        crate::random_source::RandomAlgorithm::Xoroshiro
    };
    let factories = crate::random_source::random_state_seed_factories(seed, algorithm);
    let started = Instant::now();
    let mut aquifer = settings.aquifers_enabled.then(|| {
        NoiseBasedAquifer::new(
            &mut noise_chunk,
            chunk_min_x,
            chunk_min_x + 15,
            chunk_min_z,
            chunk_min_z + 15,
            min_y,
            height,
            seed,
            *settings,
            noise_router,
            factories.aquifer,
        )
    });
    timings.fill_aquifer_init_ms = started.elapsed().as_millis();
    let material_rules = NoiseMaterialRuleList::new(settings, factories.ore);

    // Heightmap accumulators (Y+1 of the highest non-air block).
    let mut ocean_floor = [min_y; 256];
    let mut world_surface = [min_y; 256];
    let detailed_timing = std::env::var_os("RUSTCRAFT_WORLDGEN_DETAILED_TIMING").is_some();

    let started = Instant::now();
    for cell_x_index in 0..cell_count_xz {
        // Fill the next-X slice for this column and set cell_start_block_x.
        noise_chunk.advance_cell_x(cell_x_index);

        for cell_z_index in 0..cell_count_xz {
            timings.cell_columns += 1;
            // Iterate Y from top of the world downward (matches Java doFill).
            for cell_y_index in (0..cell_count_y).rev() {
                noise_chunk.select_cell_yz(cell_y_index, cell_z_index);

                for y_in_cell in (0..cell_height).rev() {
                    let pos_y = (cell_noise_min_y + cell_y_index) * cell_height + y_in_cell;
                    let section_index = (pos_y.div_euclid(16) - min_section) as usize;
                    let local_y = (pos_y & 15) as usize;
                    let factor_y = y_in_cell as f64 / cell_height as f64;
                    if detailed_timing {
                        let interpolation_started = Instant::now();
                        noise_chunk.update_for_y(pos_y, factor_y);
                        timings.fill_interpolation_update_us +=
                            interpolation_started.elapsed().as_micros();
                    } else {
                        noise_chunk.update_for_y(pos_y, factor_y);
                    }

                    for x_in_cell in 0..cell_width {
                        let pos_x = chunk_min_x + cell_x_index * cell_width + x_in_cell;
                        let local_x = (pos_x & 15) as usize;
                        let factor_x = x_in_cell as f64 / cell_width as f64;
                        if detailed_timing {
                            let interpolation_started = Instant::now();
                            noise_chunk.update_for_x(pos_x, factor_x);
                            timings.fill_interpolation_update_us +=
                                interpolation_started.elapsed().as_micros();
                        } else {
                            noise_chunk.update_for_x(pos_x, factor_x);
                        }

                        for z_in_cell in 0..cell_width {
                            let pos_z = chunk_min_z + cell_z_index * cell_width + z_in_cell;
                            let local_z = (pos_z & 15) as usize;
                            let factor_z = z_in_cell as f64 / cell_width as f64;
                            if detailed_timing {
                                let interpolation_started = Instant::now();
                                noise_chunk.update_for_z(pos_z, factor_z);
                                timings.fill_interpolation_update_us +=
                                    interpolation_started.elapsed().as_micros();
                            } else {
                                noise_chunk.update_for_z(pos_z, factor_z);
                            }

                            timings.block_samples += 1;
                            let density = if detailed_timing {
                                let density_started = Instant::now();
                                let density = noise_chunk.interpolated_density(pos_x, pos_y, pos_z);
                                timings.fill_density_lookup_us +=
                                    density_started.elapsed().as_micros();
                                density
                            } else {
                                noise_chunk.interpolated_density(pos_x, pos_y, pos_z)
                            };

                            let block = material_rules.calculate(
                                aquifer.as_mut(),
                                &noise_chunk,
                                settings,
                                pos_x,
                                pos_y,
                                pos_z,
                                density,
                                &mut timings,
                                detailed_timing,
                            );

                            if block != "minecraft:air" {
                                let block_id = section_blocks.id_for(block);
                                let block_index = local_y * 256 + local_z * 16 + local_x;
                                let section = &mut section_blocks.sections[section_index];
                                let old_id = section.ids[block_index];
                                if old_id == 0 {
                                    section.non_air_blocks += 1;
                                }
                                section.ids[block_index] = block_id;
                                timings.block_writes += 1;
                                let idx = local_z * 16 + local_x;
                                if pos_y + 1 > world_surface[idx] {
                                    world_surface[idx] = pos_y + 1;
                                }
                                // Ocean floor tracks solid (non-fluid) blocks only.
                                if block != "minecraft:water"
                                    && block != "minecraft:lava"
                                    && pos_y + 1 > ocean_floor[idx]
                                {
                                    ocean_floor[idx] = pos_y + 1;
                                }
                            }
                        }
                    }
                }
            }
        }

        // Swap so that the filled next-slice becomes the current slice for the
        // next iteration.
        noise_chunk.swap_slices();
    }
    timings.fill_block_loop_ms = started.elapsed().as_millis();
    let fill_stats = noise_chunk.take_fill_stats();
    timings.fill_full_noise_cache_ms = fill_stats.full_noise_cache_ms;
    timings.fill_full_noise_cache_us = fill_stats.full_noise_cache_us;
    timings.full_noise_cache_fills = fill_stats.full_noise_cache_fills;
    timings.fill_vein_noise_cache_ms = fill_stats.vein_noise_cache_ms;
    timings.fill_vein_noise_cache_us = fill_stats.vein_noise_cache_us;
    timings.vein_noise_cache_fills = fill_stats.vein_noise_cache_fills;
    timings.cache_once_scalar_hits = fill_stats.cache_once_scalar_hits;
    timings.cache_once_scalar_misses = fill_stats.cache_once_scalar_misses;
    timings.cache_once_array_hits = fill_stats.cache_once_array_hits;
    timings.cache_once_array_misses = fill_stats.cache_once_array_misses;

    let started = Instant::now();
    chunk.heightmaps = BTreeMap::from([
        (
            HeightmapKind::WorldSurfaceWg.storage_name().to_string(),
            Tag::LongArray(pack_heightmap(world_surface)),
        ),
        (
            HeightmapKind::OceanFloorWg.storage_name().to_string(),
            Tag::LongArray(pack_heightmap(ocean_floor)),
        ),
    ]);
    timings.fill_heightmap_pack_ms = started.elapsed().as_millis();
    timings.fill_total_ms = total_started.elapsed().as_millis();

    (
        chunk,
        timings,
        section_blocks,
        LiveNoiseGenerationContext {
            noise_chunk,
            aquifer,
        },
    )
}

fn flush_generated_section_blocks(chunk: &mut LevelChunk, section_blocks: &GeneratedSectionBlocks) {
    let containers = section_blocks.to_paletted_containers();
    for (section, blocks) in chunk.sections.iter_mut().zip(containers.iter()) {
        section.block_states = blocks.to_nbt();
    }
}

